const LESSONS=[{"id":1,"title":"Excuse me!","titleCn":"对不起！","kind":"text","words":[{"en":"excuse","ipa":"/ɪkˈskjuːz/","cn":"v. 原谅","source":"supplement"},{"en":"me","ipa":"/miː/","cn":"pron. 我（宾格）","source":"supplement"},{"en":"yes","ipa":"/jes/","cn":"adv. 是的","source":"supplement"},{"en":"is","ipa":"/ɪz/","cn":"v. be 动词（第三人称单数）","source":"supplement"},{"en":"this","ipa":"/ðɪs/","cn":"pron. 这","source":"supplement"},{"en":"your","ipa":"/jɔː/","cn":"det. 你的","source":"supplement"},{"en":"handbag","ipa":"/ˈhændbæɡ/","cn":"n. 手提包","source":"supplement"},{"en":"pardon","ipa":"/ˈpɑːdn/","cn":"int. 原谅，请再说一遍","source":"supplement"},{"en":"it","ipa":"/ɪt/","cn":"pron. 它","source":"supplement"},{"en":"thank you","ipa":"/ˈθæŋk juː/","cn":"phr. 谢谢你","source":"supplement"}],"patterns":[{"en":"Excuse me!","cn":"劳驾／对不起（用于事前引起对方注意）","source":"adaptation"},{"en":"Is this your handbag?","cn":"这是您的手提包吗？（be 动词一般疑问句）","source":"adaptation"},{"en":"Yes, it is. / No, it isn't.","cn":"是的。／不是。（一般疑问句的肯定与否定回答）","source":"adaptation"}],"grammar":"be 动词一般疑问句把 Is 提到主语之前：Is this...? 回答要用 it 代替 this：Yes, it is. / No, it isn't. 不能说 Yes, this is.","tip":"excuse me 用于事前打扰（问路、借过），sorry 用于事后致歉；没听清对方时说 Pardon? 请他再说一遍。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Excuse me!","cn":"对不起！／劳驾！","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes?","cn":"什么事？","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this your handbag?","cn":"这是您的手提包吗？","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Pardon?","cn":"对不起，请再说一遍。","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this your handbag?","cn":"这是您的手提包吗？","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, it is.","cn":"是的，是我的。","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you very much.","cn":"非常感谢！","source":"adaptation","pdfPage":5,"printedPage":1,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"捡到东西怎么找到主人","chat":"小朋友，想象你在路上捡到一个手提包，要还给主人怎么办？先说 Excuse me!（打扰一下）引起注意，再问 Is this your…?（这是你的……吗？）。是主人的会说 Yes, it is.，不是的会说 No, it isn't.","formula":"Is this your + 东西? → Yes, it is.（是我的）／ No, it isn't.（不是）","examples":[{"en":"Is this your handbag?","cn":"这是您的手提包吗？","source":"supplement"},{"en":"Is this your pen?","cn":"这是你的钢笔吗？","source":"supplement"},{"en":"Yes, it is. Thank you very much!","cn":"是的，是我的。非常感谢！","source":"supplement"}],"watch":"回答时要用 it 代替 this：说「Yes, it is.」，不能说「Yes, this is.」哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ your handbag?","opts":["Is","Are","Am","Be"],"a":"Is","why":"this/it 是单数，配 Is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"—Is this your pen? —Yes, ___.","opts":["it is","this is","it isn't","I am"],"a":"it is","why":"回答时用 it 代替 this。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"课文里问了几次「这是你的手提包吗」？","opts":["两次","一次","三次","没有问"],"a":"两次","hint":"对方说 Pardon? 之后又问了一遍。","why":"Pardon? = 请再说一遍，所以问了两次。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"这个人想要做什么？","opts":["找到手提包的主人","买一个新手提包","卖掉手提包","借一把伞"],"a":"找到手提包的主人","hint":"Excuse me! 的用途。","why":"捡到东西要物归原主。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":5,"printedPage":1,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":2,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":1},{"id":3,"title":"Sorry, sir.","titleCn":"对不起，先生。","kind":"text","words":[{"en":"umbrella","ipa":"/ʌmˈbrelə/","cn":"n. 伞","source":"supplement"},{"en":"please","ipa":"/pliːz/","cn":"int. 请","source":"supplement"},{"en":"here","ipa":"/hɪə/","cn":"adv. 这里","source":"supplement"},{"en":"my","ipa":"/maɪ/","cn":"det. 我的","source":"supplement"},{"en":"ticket","ipa":"/ˈtɪkɪt/","cn":"n. 票","source":"supplement"},{"en":"thanks","ipa":"/θæŋks/","cn":"int. 多谢（口语）","source":"supplement"},{"en":"sir","ipa":"/sɜː/","cn":"n. 先生","source":"supplement"},{"en":"cloakroom","ipa":"/ˈkləʊkruːm/","cn":"n. 衣帽存放处","source":"supplement"},{"en":"coat","ipa":"/kəʊt/","cn":"n. 上衣，外套","source":"supplement"},{"en":"number","ipa":"/ˈnʌmbə/","cn":"n. 号码","source":"supplement"}],"patterns":[{"en":"Sorry, sir.","cn":"对不起，先生。（事后致歉）","source":"adaptation"},{"en":"Here's my ticket.","cn":"这是我的票。（Here's = Here is）","source":"adaptation"},{"en":"This is not my umbrella.","cn":"这不是我的伞。（is not = isn't）","source":"adaptation"}],"grammar":"Here's... 即 Here is...，把东西递给对方或指给对方看时常用；否定句在 be 动词后加 not：This is not my umbrella.","tip":"对陌生男士可尊称 sir；把东西递给对方时说 Here you are.（给您），接收方说 Thank you. 两句要配对使用。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"My coat and my umbrella, please.","cn":"请把我的外套和伞拿给我。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here is my ticket.","cn":"这是我的票。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you, sir. Number five.","cn":"谢谢，先生。是5号。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here's your umbrella and your coat.","cn":"这是您的伞和外套。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This is not my umbrella.","cn":"这不是我的伞。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Sorry, sir. Is this yours?","cn":"对不起，先生。这把是您的吗？","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, it isn't.","cn":"不，不是。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this it?","cn":"这把是吗？","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, it is. Thank you very much.","cn":"是，就是这把。非常感谢。","source":"adaptation","pdfPage":9,"printedPage":5,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"Here's…：递东西的魔法句","chat":"拿错别人的东西要马上说 Sorry.（对不起）。把东西还给人家时说 Here's your…，Here's 就是 Here is 的缩写，意思是「给，这是您的……」，特别好用！","formula":"Here's your + 东西. （这是您的……）","examples":[{"en":"Here's your umbrella.","cn":"这是您的伞。","source":"supplement"},{"en":"Here's your coat and your ticket.","cn":"这是您的外套和票。","source":"supplement"},{"en":"Sorry, sir. This is not my umbrella.","cn":"对不起，先生，这不是我的伞。","source":"supplement"}],"watch":"Excuse me 是「事前打扰」（问路前），Sorry 是「事后道歉」（做错后），时间点不一样哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Here ___ your umbrella.","opts":["is","are","am","be"],"a":"is","why":"Here's = Here is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"拿错了别人的东西应该马上说：","opts":["Sorry.","Excuse me.","Please.","Hello."],"a":"Sorry.","why":"事后道歉用 Sorry。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"这位先生的票是几号？","opts":["5号","3号","4号","15号"],"a":"5号","hint":"听店员说的话。","why":"Number five. 5号。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"先生第一次拿到的伞是他的吗？","opts":["不是","是","课文没说","是店员的"],"a":"不是","hint":"他说了 This is not my umbrella.","why":"所以店员又给他换了一把。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":9,"printedPage":5,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":4,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":3},{"id":5,"title":"Nice to meet you.","titleCn":"很高兴见到你。","kind":"text","words":[{"en":"Mr.","ipa":"/ˈmɪstə/","cn":"n. 先生","source":"supplement"},{"en":"good","ipa":"/ɡʊd/","cn":"adj. 好","source":"supplement"},{"en":"morning","ipa":"/ˈmɔːnɪŋ/","cn":"n. 早晨","source":"supplement"},{"en":"Miss","ipa":"/mɪs/","cn":"n. 小姐","source":"supplement"},{"en":"new","ipa":"/njuː/","cn":"adj. 新的","source":"supplement"},{"en":"student","ipa":"/ˈstjuːdnt/","cn":"n. 学生","source":"supplement"},{"en":"French","ipa":"/frentʃ/","cn":"adj.&n. 法国的／法语","source":"supplement"},{"en":"nice","ipa":"/naɪs/","cn":"adj. 美好的","source":"supplement"},{"en":"meet","ipa":"/miːt/","cn":"v. 遇见","source":"supplement"},{"en":"German","ipa":"/ˈdʒɜːmən/","cn":"adj.&n. 德国的／德语","source":"supplement"}],"patterns":[{"en":"This is Sophie Dupont.","cn":"这位是索菲娅·杜邦。（介绍他人句型）","source":"adaptation"},{"en":"Nice to meet you.","cn":"很高兴见到你。（初次见面）","source":"adaptation"},{"en":"She is French, too.","cn":"她也是法国人。（too 放句尾表示“也”）","source":"adaptation"}],"grammar":"介绍别人统一用 This is...（不必管性别，不说 He is/She is）；表示国籍的词首字母大写且前面不加冠词：She is French.","tip":"初次见面的回答是 Nice to meet you, too.，别忘了 too；Good morning 用于中午十二点前。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Good morning.","cn":"早上好。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Good morning, Mr. Blake.","cn":"早上好，布莱克先生。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This is Miss Sophie Dupont. Sophie is a new student. She is French.","cn":"这位是索菲娅·杜邦小姐。索菲娅是个新学生，她是法国人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Sophie, this is Hans. He is German.","cn":"索菲娅，这是汉斯，他是德国人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And this is Naoko. She's Japanese.","cn":"这是直子，她是日本人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And this is Chang-woo. He's Korean.","cn":"这是昌宇，他是韩国人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And this is Luming. He's Chinese.","cn":"这是鲁明，他是中国人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And this is Xiaohui. She's Chinese, too.","cn":"这是晓慧，她也是中国人。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"adaptation","pdfPage":13,"printedPage":9,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"介绍朋友只用 This is","chat":"把朋友介绍给别人，不管男生女生、老师同学，统统用 This is…（这位是……）！被介绍的人回答 Nice to meet you.（很高兴认识你），对方会加上 too（我也很高兴）。","formula":"This is + 名字. → Nice to meet you. → Nice to meet you, too.","examples":[{"en":"This is Sophie. She is French.","cn":"这位是索菲娅，她是法国人。","source":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","source":"supplement"},{"en":"Nice to meet you, too.","cn":"我也很高兴见到你。","source":"supplement"}],"watch":"国籍词要大写、前面不加 a：She is French.（她是法国人），不说 She is a French！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ is Miss Sophie Dupont.","opts":["This","That","These","It"],"a":"This","why":"介绍别人统一用 This is…","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"—Nice to meet you. —Nice to meet you, ___.","opts":["too","to","two","also"],"a":"too","why":"too 放句尾表示「也」。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"索菲娅是哪国人？","opts":["法国","德国","日本","中国"],"a":"法国","hint":"She is French.","why":"课文明确说 She is French. 也作为国籍词示例。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"布莱克先生一共介绍了几位（含索菲娅）？","opts":["6位","5位","4位","7位"],"a":"6位","hint":"Hans、Naoko、Chang-woo、Luming、Xiaohui…","why":"索菲娅+5位同学=6位。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":13,"printedPage":9,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":6,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":5},{"id":7,"title":"Are you a teacher?","titleCn":"你是教师吗？","kind":"text","words":[{"en":"name","ipa":"/neɪm/","cn":"n. 名字","source":"supplement"},{"en":"what","ipa":"/wɒt/","cn":"pron. 什么","source":"supplement"},{"en":"job","ipa":"/dʒɒb/","cn":"n. 工作","source":"supplement"},{"en":"nationality","ipa":"/ˌnæʃəˈnæləti/","cn":"n. 国籍","source":"supplement"},{"en":"policeman","ipa":"/pəˈliːsmən/","cn":"n. 警察","source":"supplement"},{"en":"nurse","ipa":"/nɜːs/","cn":"n. 护士","source":"supplement"},{"en":"mechanic","ipa":"/məˈkænɪk/","cn":"n. 机械师","source":"supplement"},{"en":"hairdresser","ipa":"/ˈheədresə/","cn":"n. 理发师","source":"supplement"},{"en":"housewife","ipa":"/ˈhaʊswaɪf/","cn":"n. 家庭主妇","source":"supplement"},{"en":"engineer","ipa":"/ˌendʒɪˈnɪə/","cn":"n. 工程师","source":"supplement"}],"patterns":[{"en":"I'm a new student.","cn":"我是个新学生。（I'm = I am）","source":"adaptation"},{"en":"What's your job?","cn":"你是做什么工作的？","source":"textbook","pdfPage":17,"printedPage":13,"verification":"verified","translationSource":"supplement"},{"en":"I'm an engineer.","cn":"我是工程师。（元音音素前用 an）","source":"adaptation"}],"grammar":"介绍职业用 I'm a/an + 职业；a 用于辅音音素前（a teacher / a student），an 用于元音音素前（an engineer / an operator）。","tip":"问职业还可以说 What do you do?；本课介绍一个人的职业可用 I’m a/an + 职业。a/an 的选择看后面紧接词的实际读音，不只看字母。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"I am a new student.","cn":"我是个新学生。","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My name's Robert.","cn":"我叫罗伯特。","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Nice to meet you.","cn":"很高兴见到你。","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My name's Sophie.","cn":"我叫索菲娅。","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Are you French?","cn":"你是法国人吗？","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, I am.","cn":"是的，我是。","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Are you French, too?","cn":"你也是法国人吗？","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, I am not.","cn":"不，我不是。","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What nationality are you?","cn":"你是哪国人？","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm Italian.","cn":"我是意大利人。","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Are you a teacher?","cn":"你是教师吗？","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, I'm not.","cn":"不，我不是。","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What's your job?","cn":"你是做什么工作的？","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm a keyboard operator.","cn":"我是电脑录入员。","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What's your job?","cn":"你是做什么工作的？","speaker":"SOPHIE","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I am an engineer.","cn":"我是工程师。","speaker":"ROBERT","source":"textbook","pdfPage":17,"printedPage":13,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"a 还是 an？听读音！","chat":"问别人做什么工作：What's your job? 回答可以说 I'm a/an + 职业。engineer 的第一个音 /e/ 是元音音素，所以用 an；teacher 的第一个音 /t/ 是辅音音素，所以用 a。要听实际读音，不能只看 a/e/i/o/u 这五个字母。","formula":"What's your job? → I'm a teacher. ／ I'm an engineer.","examples":[{"en":"What's your job?","cn":"你是做什么工作的？","source":"supplement"},{"en":"I'm a policeman.","cn":"我是一名警察。","source":"supplement"},{"en":"I'm an engineer.","cn":"我是一名工程师。","source":"supplement"}],"watch":"看「读音」不看「字母」：an hour（h 不发音，用 an），a university（u 读「you」，用 a）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"I'm ___ engineer.","opts":["an","a","the","不填"],"a":"an","why":"engineer 以元音音素开头，用 an。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"I'm ___ keyboard operator.","opts":["a","an","the","不填"],"a":"a","why":"keyboard 以辅音音素开头，用 a。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"根据课文，罗伯特做什么工作？","opts":["工程师","教师","电脑录入员","警察"],"a":"工程师","hint":"ROBERT: I am an engineer.","why":"罗伯特既是新学生，也是一名工程师。题目问工作；索菲娅是电脑录入员。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"索菲娅是哪国人？","opts":["French 法国","Italian 意大利","German 德国","English 英国"],"a":"French 法国","hint":"Are you French? Yes, I am.","why":"索菲娅是法国人；罗伯特是意大利人。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":17,"printedPage":13,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":8,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":7},{"id":9,"title":"How are you today?","titleCn":"你今天好吗？","kind":"text","words":[{"en":"hello","ipa":"/həˈləʊ/","cn":"int. 你好","source":"supplement"},{"en":"hi","ipa":"/haɪ/","cn":"int. 嗨","source":"supplement"},{"en":"how","ipa":"/haʊ/","cn":"adv. 怎样","source":"supplement"},{"en":"fine","ipa":"/faɪn/","cn":"adj. 美好的，健康的","source":"supplement"},{"en":"well","ipa":"/wel/","cn":"adj. 好的（身体）；adv. 好","source":"supplement"},{"en":"thanks","ipa":"/θæŋks/","cn":"int. 多谢（口语）","source":"supplement"},{"en":"see","ipa":"/siː/","cn":"v. 看见，见面","source":"supplement"},{"en":"goodbye","ipa":"/ˌɡʊdˈbaɪ/","cn":"int. 再见","source":"supplement"},{"en":"fat","ipa":"/fæt/","cn":"adj. 胖的","source":"supplement"},{"en":"thin","ipa":"/θɪn/","cn":"adj. 瘦的","source":"supplement"}],"patterns":[{"en":"How are you today?","cn":"你今天好吗？（问候健康）","source":"adaptation"},{"en":"I'm very well, thank you. And you?","cn":"我很好，谢谢。你呢？","source":"adaptation"},{"en":"Look at that man. He's very fat.","drill":true,"cn":"看那个男人，他很胖。（Look at + 名词）","source":"supplement"}],"grammar":"How are you? 是固定问候语，回答 I'm fine. / I'm very well, thank you.；Look at 后接名词表示“看……”，引出对人的描述。","tip":"当面说别人 fat 不礼貌，英语里更委婉；熟人间见面说 Nice to see you，初次见面才说 Nice to meet you。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Hello, Helen.","cn":"你好，海伦。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Hi, Steven.","cn":"你好，史蒂文。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How are you today?","cn":"你今天好吗？","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm very well, thank you. And you?","cn":"很好，谢谢你。你好吗？","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm fine, thanks.","cn":"很好，谢谢。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How is Tony?","cn":"托尼好吗？","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's fine, thanks. How's Emma?","cn":"他很好，谢谢。埃玛好吗？","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She's very well, too, Helen.","cn":"她也很好，海伦。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Goodbye, Helen. Nice to see you.","cn":"再见，海伦。见到你真高兴。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nice to see you, too, Steven. Goodbye.","cn":"我也很高兴见到你，史蒂文。再见。","source":"adaptation","pdfPage":21,"printedPage":17,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"How are you? 是打招呼","chat":"How are you? 不是真的在问「你怎么样」，它是英语里的打招呼用语，就像「你好吗」。标准回答：I'm fine, thank you. 或 I'm very well, thanks. 然后礼貌地问回去 And you?（你呢？）。","formula":"How are you? → I'm fine / very well, thank you. And you?","examples":[{"en":"How are you today?","cn":"你今天好吗？","source":"supplement"},{"en":"I'm very well, thank you. And you?","cn":"我很好，谢谢。你呢？","source":"supplement"},{"en":"I'm fine, thanks.","cn":"我很好，谢谢。","source":"supplement"}],"watch":"描写人的样子要用形容词：He is fat.（他胖）She is thin.（她瘦）——形容词跟在 is/am/are 后面。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"—How are you? —I'm very ___, thank you.","opts":["well","good","better","best"],"a":"well","why":"形容身体好用 well（形容词）。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"熟人见面说：Nice to ___ you.","opts":["see","meet","look","watch"],"a":"see","why":"初次见面才用 meet，熟人是 see。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"是谁问了「埃玛好吗」（How's Emma?）？","opts":["海伦","史蒂文","托尼","埃玛"],"a":"海伦","hint":"对话一来一回注意说话人。","why":"史蒂文问托尼，海伦接着问埃玛。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"两人最后互相说了什么？","opts":["Goodbye 再见","Sorry 对不起","Pardon 请再说一遍","Thanks 谢谢"],"a":"Goodbye 再见","why":"结尾是道别：Nice to see you. Goodbye.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":21,"printedPage":17,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}]}},{"id":10,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":9},{"id":11,"title":"Is this your shirt?","titleCn":"这是你的衬衫吗？","kind":"text","words":[{"en":"whose","ipa":"/huːz/","cn":"pron. 谁的","source":"supplement"},{"en":"shirt","ipa":"/ʃɜːt/","cn":"n. 衬衫","source":"supplement"},{"en":"blouse","ipa":"/blaʊz/","cn":"n. 女衬衫","source":"supplement"},{"en":"tie","ipa":"/taɪ/","cn":"n. 领带","source":"supplement"},{"en":"brother","ipa":"/ˈbrʌðə/","cn":"n. 兄，弟","source":"supplement"},{"en":"sister","ipa":"/ˈsɪstə/","cn":"n. 姐，妹","source":"supplement"},{"en":"father","ipa":"/ˈfɑːðə/","cn":"n. 父亲","source":"supplement"},{"en":"mother","ipa":"/ˈmʌðə/","cn":"n. 母亲","source":"supplement"},{"en":"his","ipa":"/hɪz/","cn":"det. 他的","source":"supplement"},{"en":"her","ipa":"/hɜː/","cn":"det. 她的","source":"supplement"}],"patterns":[{"en":"Whose shirt is that?","cn":"那是谁的衬衫？","source":"adaptation"},{"en":"It's Dave's.","cn":"是戴夫的。（人名 + 's 表示所属）","source":"adaptation"},{"en":"Is this your shirt, Dave?","cn":"戴夫，这是你的衬衫吗？","source":"adaptation"}],"grammar":"对物主提问用 Whose：Whose shirt is that?；名词所有格在人名后加 's：Dave's = Dave 的（衬衫），后面名词常省略。","tip":"his / her 的选择看所有者的性别：his shirt（他的），her blouse（她的）；whose 与 who's（who is）读音相同，含义不同。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Whose shirt is that?","cn":"那是谁的衬衫？","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is that your shirt, Dave?","cn":"戴夫，那是你的衬衫吗？","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, sir. It's not my shirt. This is my shirt. My shirt's blue.","cn":"不，先生。那不是我的衬衫。我的衬衫在这儿，是蓝色的。","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this shirt Tim's?","cn":"这件衬衫是蒂姆的吗？","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Perhaps it is, sir. Tim's shirt's white.","cn":"可能是，先生。蒂姆的衬衫是白色的。","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Tim!","cn":"蒂姆！","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, sir?","cn":"什么事，先生？","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this your shirt?","cn":"这是你的衬衫吗？","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, sir.","cn":"是的，先生。","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are. Catch!","cn":"给你。接住！","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you, sir.","cn":"谢谢您，先生。","source":"adaptation","pdfPage":25,"printedPage":21,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"Whose 谁的？'s 是名字标签","chat":"想知道东西是谁的，用 Whose（谁的）提问。回答的小秘密：在人名后面加一个小小的 's，表示「某某的」！Dave's 就是「戴夫的」，像给东西贴上主人的名字标签。","formula":"Whose + 东西 is this/that? → It's + 人名 + 's.","examples":[{"en":"Whose shirt is that?","cn":"那是谁的衬衫？","source":"supplement"},{"en":"It's Dave's.","cn":"是戴夫的。","source":"supplement"},{"en":"Is this your shirt, Tim?","cn":"蒂姆，这是你的衬衫吗？","source":"supplement"}],"watch":"his（他的）和 her（她的）看主人性别：his bag 他的包，her bag 她的包，别贴错标签！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ shirt is that?","opts":["Whose","Who's","Who","Which"],"a":"Whose","why":"问「谁的」用 Whose；Who's = Who is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"It's ___.（戴夫的）","opts":["Dave's","Daves'","Dave","Daves"],"a":"Dave's","why":"人名 + 's 表示所属。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"戴夫的衬衫是什么颜色？","opts":["蓝色","白色","红色","绿色"],"a":"蓝色","hint":"My shirt's blue.","why":"戴夫说自己的衬衫是蓝色的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"白衬衫是谁的？","opts":["蒂姆的","戴夫的","老师的","未知"],"a":"蒂姆的","why":"Perhaps it is, sir. Tim's shirt's white. 白色是蒂姆的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":25,"printedPage":21,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}]}},{"id":12,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":11},{"id":13,"title":"A new dress","titleCn":"一件新连衣裙","kind":"text","words":[{"en":"colour","ipa":"/ˈkʌlə/","cn":"n. 颜色","source":"supplement"},{"en":"green","ipa":"/ɡriːn/","cn":"adj. 绿色的","source":"supplement"},{"en":"come","ipa":"/kʌm/","cn":"v. 来","source":"supplement"},{"en":"upstairs","ipa":"/ˌʌpˈsteəz/","cn":"adv. 楼上","source":"supplement"},{"en":"smart","ipa":"/smɑːt/","cn":"adj. 漂亮的，时髦的","source":"supplement"},{"en":"hat","ipa":"/hæt/","cn":"n. 帽子","source":"supplement"},{"en":"same","ipa":"/seɪm/","cn":"adj. 相同的","source":"supplement"},{"en":"lovely","ipa":"/ˈlʌvli/","cn":"adj. 可爱的，好看的","source":"supplement"},{"en":"case","ipa":"/keɪs/","cn":"n. 箱子","source":"supplement"},{"en":"carpet","ipa":"/ˈkɑːpɪt/","cn":"n. 地毯","source":"supplement"}],"patterns":[{"en":"What colour's your new dress?","cn":"你的新连衣裙是什么颜色的？（colour's = colour is）","source":"adaptation"},{"en":"Come upstairs and see it.","cn":"到楼上来看看它吧。","source":"adaptation"},{"en":"It's the same colour.","cn":"它是同样的颜色。","source":"adaptation"}],"grammar":"对颜色提问用 What colour...?；same 前习惯加 the：the same colour；陈述颜色时系动词 + 形容词：It's green.","tip":"smart 在本课形容衣着“时髦漂亮”，不是“聪明”；英式拼写是 colour，美式是 color。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"What colour's your new dress?","cn":"你的新连衣裙是什么颜色的？","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's green. Come upstairs and see it.","cn":"是绿色的。到楼上来看看吧。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you.","cn":"谢谢。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Look! Here it is!","cn":"瞧，就是这件。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's a nice dress. It's very smart.","cn":"这是件漂亮的连衣裙，非常时髦。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"My hat's new, too.","cn":"我的帽子也是新的。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What colour is it?","cn":"它是什么颜色的？","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's the same colour. It's green, too.","cn":"一样的颜色，也是绿色的。","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That is a lovely hat!","cn":"真是一顶可爱的帽子！","source":"adaptation","pdfPage":29,"printedPage":25,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"问颜色的专用问法","chat":"问颜色有专门的句型：What colour…?（什么颜色？）colour's 是 colour is 的缩写。回答直接说 It's + 颜色。注意：same（相同的）是个小明星，出门必须带 the！","formula":"What colour is your…? → It's red / green / blue. ｜ the same colour 相同的颜色","examples":[{"en":"What colour's your new dress?","cn":"你的新连衣裙是什么颜色的？","source":"supplement"},{"en":"It's green. It's the same colour.","cn":"是绿色的，一样的颜色。","source":"supplement"},{"en":"That is a lovely hat!","cn":"真是一顶可爱的帽子！","source":"supplement"}],"watch":"smart 在这课形容衣服「时髦漂亮」，不是「聪明」哦！另外英式写 colour，美式写 color。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ is your hat?","opts":["What colour","What","Which","Whose"],"a":"What colour","why":"问颜色用 What colour。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"My hat is ___ colour.","opts":["the same","same","a same","the some"],"a":"the same","why":"same 前面必须加 the。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"新连衣裙是什么颜色？","opts":["绿色","蓝色","红色","白色"],"a":"绿色","hint":"It's green.","why":"绿裙子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"新裙子和新帽子有什么共同点？","opts":["颜色相同","款式相同","大小相同","主人相同"],"a":"颜色相同","hint":"It's the same colour.","why":"都是绿色的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":29,"printedPage":25,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":14,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":13},{"id":15,"title":"Your passports, please.","titleCn":"请出示你们的护照。","kind":"text","words":[{"en":"passport","ipa":"/ˈpɑːspɔːt/","cn":"n. 护照","source":"supplement"},{"en":"customs","ipa":"/ˈkʌstəmz/","cn":"n. 海关","source":"supplement"},{"en":"tourist","ipa":"/ˈtʊərɪst/","cn":"n. 旅游者","source":"supplement"},{"en":"friend","ipa":"/frend/","cn":"n. 朋友","source":"supplement"},{"en":"Norwegian","ipa":"/nɔːˈwiːdʒən/","cn":"adj.&n. 挪威的／挪威人","source":"supplement"},{"en":"Danish","ipa":"/ˈdeɪnɪʃ/","cn":"adj.&n. 丹麦的／丹麦人","source":"supplement"},{"en":"Russian","ipa":"/ˈrʌʃn/","cn":"adj.&n. 俄罗斯的／俄国人","source":"supplement"},{"en":"Dutch","ipa":"/dʌtʃ/","cn":"adj.&n. 荷兰的／荷兰人","source":"supplement"},{"en":"these","ipa":"/ðiːz/","cn":"pron. 这些","source":"supplement"},{"en":"those","ipa":"/ðəʊz/","cn":"pron. 那些","source":"supplement"}],"patterns":[{"en":"Are you Swedish?","cn":"你们是瑞典人吗？（复数主语用 are）","source":"adaptation"},{"en":"Are these your cases?","cn":"这些是你们的箱子吗？","source":"adaptation"},{"en":"Your passports, please.","cn":"请出示你们的护照。（礼貌祈使句）","source":"adaptation"}],"grammar":"主语是复数（we / you / they / these / those）时 be 动词用 are；祈使句省略主语，用名词 + please 表示客气请求。","tip":"these（这些）指近处，those（那些）指远处；请别人出示东西的固定说法是 Your ..., please.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Are you Swedish?","cn":"你们是瑞典人吗？","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, we aren't. We're Danish.","cn":"不，我们不是。我们是丹麦人。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Are your friends Danish, too?","cn":"你们的朋友也是丹麦人吗？","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, they aren't. They're Norwegian.","cn":"不，他们不是。他们是挪威人。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Your passports, please.","cn":"请出示你们的护照。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here they are.","cn":"给您。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Are these your cases?","cn":"这些是你们的箱子吗？","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, they aren't.","cn":"不是。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Our cases are brown. Here they are.","cn":"我们的箱子是棕色的，在这儿呢。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Are you tourists?","cn":"你们是来旅游的吗？","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, we are.","cn":"是的。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Are your friends tourists too?","cn":"你们的朋友也是来旅游的吗？","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, they are.","cn":"是的。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's fine.","cn":"好了。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you very much.","cn":"非常感谢。","source":"adaptation","pdfPage":33,"printedPage":29,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"复数的 be 动词都是 are","chat":"问一群人「你们是……国人吗」：Are you…? 回答用 We are / We aren't（aren't = are not）。请别人出示证件：Your passports, please. 名词后面加 please，一句话就有礼貌！","formula":"Are you + 国籍(复数)? → Yes, we are. ／ No, we aren't. ｜ Your…, please. 请出示……","examples":[{"en":"Are you Swedish?","cn":"你们是瑞典人吗？","source":"supplement"},{"en":"No, we aren't. We're Danish.","cn":"不，我们是丹麦人。","source":"supplement"},{"en":"Your passports, please.","cn":"请出示你们的护照。","source":"supplement"}],"watch":"these（这些）指近处，those（那些）指远处；主语是复数时，be 动词全用 are！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ you Swedish?","opts":["Are","Is","Am","Do"],"a":"Are","why":"你们=复数，用 Are。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"___ are their cases?","opts":["These","This","That","It"],"a":"These","why":"cases 是复数，用 These。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"他们的朋友是哪国人？","opts":["挪威","丹麦","瑞典","俄国"],"a":"挪威","hint":"They're Norwegian.","why":"朋友是挪威人，他们自己是丹麦人。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"这群人是来做什么的？","opts":["旅游","教书","工作","留学"],"a":"旅游","hint":"Are you tourists?","why":"They're tourists. 海关确认他们是游客。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":33,"printedPage":29,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":16,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":15},{"id":17,"title":"How do you do?","titleCn":"你好！","kind":"text","words":[{"en":"employee","ipa":"/ɪmˈplɔɪiː/","cn":"n. 雇员","source":"supplement"},{"en":"hard-working","ipa":"/ˌhɑːd ˈwɜːkɪŋ/","cn":"adj. 勤奋的","source":"supplement"},{"en":"sales rep","ipa":"/ˈseɪlz rep/","cn":"n. 推销员","source":"supplement"},{"en":"office","ipa":"/ˈɒfɪs/","cn":"n. 办公室","source":"supplement"},{"en":"assistant","ipa":"/əˈsɪstənt/","cn":"n. 助理","source":"supplement"},{"en":"busy","ipa":"/ˈbɪzi/","cn":"adj. 忙的","source":"supplement"},{"en":"lazy","ipa":"/ˈleɪzi/","cn":"adj. 懒的","source":"supplement"},{"en":"young","ipa":"/jʌŋ/","cn":"adj. 年轻的","source":"supplement"},{"en":"woman","ipa":"/ˈwʊmən/","cn":"n. 女人","source":"supplement"},{"en":"man","ipa":"/mæn/","cn":"n. 男人","source":"supplement"}],"patterns":[{"en":"How do you do?","cn":"你好！（初次被介绍时的正式问候）","source":"adaptation"},{"en":"What are their jobs?","cn":"他们是做什么工作的？（复数）","source":"adaptation"},{"en":"Those women are very hard-working.","cn":"那些女职员工作很勤快。","source":"adaptation"}],"grammar":"How do you do? 不是疑问句，回答也用 How do you do?；对复数主语提问职业用 What are their jobs?（单数用 What's your job?）。","tip":"How do you do? 只在正式介绍时用一次；回答后可再补一句 Nice to meet you. 缓和气氛。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Come and meet our employees, Mr. Richards.","cn":"来见见我们的员工，理查兹先生。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you, Mr. Jackson.","cn":"谢谢，杰克逊先生。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This is Nicola Grey, and this is Claire Taylor.","cn":"这位是尼克拉·格雷，这位是克莱尔·泰勒。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How do you do?","cn":"你们好！","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Those women are very hard-working. What are their jobs?","cn":"那些女职员工作很勤快。她们是做什么工作的？","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They're keyboard operators.","cn":"她们是电脑录入员。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This is Michael Baker, and this is Jeremy Short.","cn":"这位是迈克尔·贝克，这位是杰里米·肖特。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How do you do?","cn":"你们好！","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They aren't very busy. What are their jobs?","cn":"他们不很忙。他们是做什么工作的？","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They're sales reps. They're very lazy.","cn":"他们是推销员，非常懒。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Who is this young man?","cn":"这个年轻人是谁？","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This is Jim. He's our office assistant.","cn":"他是吉姆，是我们办公室的勤杂人员。","source":"adaptation","pdfPage":37,"printedPage":33,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"How do you do? 要原句奉还","chat":"How do you do? 是正式场合被介绍时的问候语，它看起来像问句，其实不是！回答也是原句 How do you do?，像照镜子一样。问一群人的职业：What are their jobs?（their = 他们的）。","formula":"How do you do? ⇄ How do you do! ｜ What are their jobs? → They're…","examples":[{"en":"How do you do?","cn":"你们好！","source":"supplement"},{"en":"What are their jobs?","cn":"他们是做什么工作的？","source":"supplement"},{"en":"They're sales reps. They're very lazy.","cn":"他们是推销员，非常懒。","source":"supplement"}],"watch":"How do you do? 只在正式介绍时用一次；平时打招呼用 Hello / Hi 就够了！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"What ___ their jobs?","opts":["are","is","am","do"],"a":"are","why":"their jobs 复数，用 are。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"This is Jim. ___ our office assistant.","opts":["He's","She's","They're","His"],"a":"He's","why":"Jim 是男生，用 He's。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"课里谁被说「非常懒」？","opts":["推销员们","尼克拉","克莱尔","迈克尔"],"a":"推销员们","hint":"They're sales reps. They're very lazy.","why":"推销员被开玩笑说懒。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"吉姆的工作是什么？","opts":["办公室勤杂","电脑录入","推销员","经理"],"a":"办公室勤杂","why":"He's our office assistant.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":37,"printedPage":33,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}]}},{"id":18,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":17},{"id":19,"title":"Tired and thirsty","titleCn":"又累又渴","kind":"text","words":[{"en":"matter","ipa":"/ˈmætə/","cn":"n. 事情（the matter 麻烦）","source":"supplement"},{"en":"children","ipa":"/ˈtʃɪldrən/","cn":"n. 孩子们（child 的复数）","source":"supplement"},{"en":"tired","ipa":"/ˈtaɪəd/","cn":"adj. 累的","source":"supplement"},{"en":"thirsty","ipa":"/ˈθɜːsti/","cn":"adj. 渴的","source":"supplement"},{"en":"Mum","ipa":"/mʌm/","cn":"n. 妈妈（口语）","source":"supplement"},{"en":"sit down","ipa":"/ˈsɪt daʊn/","cn":"phr. 坐下","source":"supplement"},{"en":"right","ipa":"/raɪt/","cn":"adj. 好的；右边的","source":"supplement"},{"en":"ice cream","ipa":"/ˈaɪs kriːm/","cn":"n. 冰淇淋","source":"supplement"},{"en":"hot","ipa":"/hɒt/","cn":"adj. 热的","source":"supplement"},{"en":"boy","ipa":"/bɔɪ/","cn":"n. 男孩","source":"supplement"}],"patterns":[{"en":"What's the matter, children?","cn":"怎么啦，孩子们？","source":"textbook","pdfPage":41,"printedPage":37,"verification":"verified","translationSource":"supplement"},{"en":"We're tired and thirsty.","cn":"我们又累又渴。","source":"adaptation"},{"en":"There's an ice cream man.","cn":"有个卖冰淇淋的。（There be 句型）","source":"textbook","pdfPage":41,"printedPage":37,"verification":"verified","translationSource":"supplement"}],"grammar":"What's the matter (with sb)? 用来询问对方怎么了；There be 句型表示“某处存在某物”，be 动词与后面的名词单复数一致（There's / There are）。","tip":"两个形容词并列用 and 连接：tired and thirsty；thirsty 的名词是 thirst（渴），注意 th 要咬舌。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"What's the matter, children?","cn":"孩子们，怎么啦？","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"We're tired . . .","cn":"我们累了……","speaker":"GIRL","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":". . . and thirsty, Mum.","cn":"……而且渴了，妈妈。","speaker":"BOY","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Sit down here.","cn":"坐在这儿吧。","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Are you all right now?","cn":"你们现在好些了吗？","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, we aren't.","cn":"不，还没有。","speaker":"BOY","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Look!","cn":"瞧！","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"There's an ice cream man.","cn":"有个卖冰淇淋的。","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Two ice creams please.","cn":"请拿两个冰淇淋。","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Here you are, children.","cn":"拿着，孩子们。","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Thanks, Mum.","cn":"谢谢，妈妈。","speaker":"CHILDREN","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"These ice creams are nice.","cn":"这些冰淇淋真好吃。","speaker":"GIRL","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Are you all right now?","cn":"你们现在好些了吗？","speaker":"MOTHER","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, we are, thank you!","cn":"是的，好些了，谢谢！","speaker":"CHILDREN","source":"textbook","pdfPage":41,"printedPage":37,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"What's the matter? 与 There be","chat":"看到别人不舒服，问 What's the matter?（怎么啦？），回答用形容词说感觉：I'm tired.（我累了）I'm thirsty.（我渴了）。要说「哪里有什么东西」，请出 There be 句型：There's an ice cream man.（有个卖冰淇淋的）。","formula":"What's the matter? → I'm tired / hungry. ｜ There's + 一个东西 + 位置.","examples":[{"en":"What's the matter, children?","cn":"孩子们，怎么啦？","source":"supplement"},{"en":"We're tired and thirsty.","cn":"我们又累又渴。","source":"supplement"},{"en":"There's an ice cream man.","cn":"有个卖冰淇淋的。","source":"supplement"}],"watch":"两个形容词手拉手要用 and 连接：tired and thirsty（又累又渴）。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"What's the ___, children?","opts":["matter","matters","problem","mad"],"a":"matter","why":"固定搭配 What's the matter?","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"There ___ an ice cream man.","opts":["is","are","am","be"],"a":"is","why":"an ice cream man 单数，用 There's。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"孩子们感觉怎么样？","opts":["又累又渴","又饿又冷","又开心又热","很好"],"a":"又累又渴","hint":"GIRL: We’re tired . . . / BOY: . . . and thirsty, Mum.","why":"tired and thirsty。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"孩子们吃了什么？","opts":["冰淇淋","苹果","面包","蛋糕"],"a":"冰淇淋","why":"Two ice creams, please.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":41,"printedPage":37,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}]}},{"id":20,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":19},{"id":21,"title":"Which book?","titleCn":"哪一本书？","kind":"text","words":[{"en":"give","ipa":"/ɡɪv/","cn":"v. 给","source":"supplement"},{"en":"which","ipa":"/wɪtʃ/","cn":"pron. 哪一个","source":"supplement"},{"en":"one","ipa":"/wʌn/","cn":"pron. 一个（代替前文提到的名词）","source":"supplement"},{"en":"red","ipa":"/red/","cn":"adj. 红色的","source":"supplement"},{"en":"clean","ipa":"/kliːn/","cn":"adj. 干净的","source":"supplement"},{"en":"dirty","ipa":"/ˈdɜːti/","cn":"adj. 脏的","source":"supplement"},{"en":"empty","ipa":"/ˈempti/","cn":"adj. 空的","source":"supplement"},{"en":"full","ipa":"/fʊl/","cn":"adj. 满的","source":"supplement"},{"en":"big","ipa":"/bɪɡ/","cn":"adj. 大的","source":"supplement"},{"en":"little","ipa":"/ˈlɪtl/","cn":"adj. 小的","source":"supplement"}],"patterns":[{"en":"Give me a book, please.","cn":"请给我一本书。（give + 人 + 物）","source":"adaptation"},{"en":"Which book?","cn":"哪一本？","source":"textbook","pdfPage":45,"printedPage":41,"verification":"verified","translationSource":"supplement"},{"en":"This one?","cn":"是这本吗？（one 代替 book）","source":"textbook","pdfPage":45,"printedPage":41,"verification":"verified","translationSource":"supplement"}],"grammar":"give 后可接双宾语：give me a book = give a book to me；one 用来代替前面提过的可数名词，避免重复（复数用 ones）。","tip":"要东西说 Give me..., please.，递东西说 Here you are.；反义形容词成对记：clean/dirty、empty/full、big/little。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"Give me a book please, Jane.","cn":"请拿本书给我，简。","speaker":"MAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Which book?","cn":"哪一本？","speaker":"WOMAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"This one?","cn":"这本吗？","speaker":"WOMAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, not that one. The red one.","cn":"不，不是那本，是红色那本。","speaker":"MAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"This one?","cn":"这本吗？","speaker":"WOMAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, please.","cn":"是的，请给我。","speaker":"MAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Here you are.","cn":"给你。","speaker":"WOMAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Thank you.","cn":"谢谢。","speaker":"MAN","source":"textbook","pdfPage":45,"printedPage":41,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"one 是名词的替身","chat":"请别人递东西：Give me…, please.（请给我……）。要弄清「哪一个」：Which book?（哪本？）。精彩的地方来了——回答时不用再说 book，用 one 当「替身」：This one?（这本吗？）The red one.（红色那本）。","formula":"Give me a/an…, please. → Which one? → This one? → The + 颜色/特征 + one.","examples":[{"en":"Give me a book, please.","cn":"请给我一本书。","source":"supplement"},{"en":"Which book?","cn":"哪一本？","source":"supplement"},{"en":"The red one.","cn":"红色那本。","source":"supplement"}],"watch":"one 只能代替「一个可数名词」；很多东西要用 ones：Which ones?（哪几只？）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"Give ___ a book, please.","opts":["me","I","my","mine"],"a":"me","why":"动词后面用宾格 me。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"—Which book? —The red ___.","opts":["one","ones","it","that"],"a":"one","why":"one 代替单数名词 book。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"简最后给的是哪本书？","opts":["红皮的","蓝皮的","大的","旧的"],"a":"红皮的","hint":"No, not that one. The red one.","why":"要的是红色那本。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"简第一次拿的书对吗？","opts":["不对，需要红的那本","对了","课文没说","她拿了两本"],"a":"不对，需要红的那本","why":"Not that one. 说明第一次拿错。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":45,"printedPage":41,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}]}},{"id":22,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":21},{"id":23,"title":"Which glasses?","titleCn":"哪几只杯子？","kind":"text","words":[{"en":"glasses","ipa":"/ˈɡlɑːsɪz/","cn":"n. 眼镜","source":"supplement"},{"en":"shelf","ipa":"/ʃelf/","cn":"n. 架子","source":"supplement"},{"en":"desk","ipa":"/desk/","cn":"n. 书桌","source":"supplement"},{"en":"table","ipa":"/ˈteɪbl/","cn":"n. 桌子","source":"supplement"},{"en":"plate","ipa":"/pleɪt/","cn":"n. 盘子","source":"supplement"},{"en":"cupboard","ipa":"/ˈkʌbəd/","cn":"n. 碗橱","source":"supplement"},{"en":"cigarette","ipa":"/ˌsɪɡəˈret/","cn":"n. 香烟","source":"supplement"},{"en":"television","ipa":"/ˈtelɪvɪʒn/","cn":"n. 电视机","source":"supplement"},{"en":"floor","ipa":"/flɔː/","cn":"n. 地板","source":"supplement"},{"en":"magazine","ipa":"/ˌmæɡəˈziːn/","cn":"n. 杂志","source":"supplement"}],"patterns":[{"en":"Give me some glasses, please.","cn":"请给我几只杯子。（some + 复数名词）","source":"adaptation"},{"en":"Which glasses?","cn":"哪几只？","source":"adaptation"},{"en":"The ones on the shelf.","cn":"架子上那几只。","source":"adaptation"}],"grammar":"some 修饰复数名词表示“一些”；which ones 问复数中的“哪些”；on the shelf 是介词短语作后置定语，修饰 the ones。","tip":"glasses 表“眼镜”时永远是复数，量词用 a pair of glasses（一副眼镜）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Give me some glasses, please, Jane.","cn":"请拿几只杯子给我，简。","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Which glasses? These glasses?","cn":"哪几只？是这几只吗？","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, not those. The ones on the shelf.","cn":"不，不是那几只，是架子上那几只。","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"These?","cn":"是这几只吗？","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please.","cn":"是的，请给我。","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are.","cn":"给你。","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thanks.","cn":"谢谢。","source":"adaptation","pdfPage":49,"printedPage":45,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"some 与 ones：要「一些」东西","chat":"要几个东西时说 Give me some glasses.（some = 一些，配复数名词）。指认哪几个还是 Which…?，回答 The ones on the shelf.——ones 是复数替身，on the shelf（在架子上）告诉我们位置。","formula":"Give me some + 复数名词, please. → Which ones? → The ones + 位置.","examples":[{"en":"Give me some glasses, please.","cn":"请给我几只杯子。","source":"supplement"},{"en":"The ones on the shelf.","cn":"架子上那几只。","source":"supplement"},{"en":"The ones on the table are clean.","cn":"桌上的那几只是干净的。","source":"supplement"}],"watch":"glasses（眼镜）永远是复数，因为有两片镜片；一副眼镜是 a pair of glasses！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Give me ___ glasses, please.","opts":["some","any","a","one"],"a":"some","why":"肯定句用 some。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The ___ on the shelf.","opts":["ones","one","it","that"],"a":"ones","why":"ones 代替复数名词 glasses。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"杯子在哪里？","opts":["架子上","桌子上","碗橱里","地板上"],"a":"架子上","hint":"The ones on the shelf.","why":"on the shelf 在架子上。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"请谁拿杯子？","opts":["简","艾米","彭妮","露西"],"a":"简","why":"Give me some glasses, please, Jane.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":49,"printedPage":45,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}]}},{"id":24,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":23},{"id":25,"title":"Mrs. Smith's kitchen","titleCn":"史密斯太太的厨房","kind":"text","words":[{"en":"kitchen","ipa":"/ˈkɪtʃɪn/","cn":"n. 厨房","source":"supplement"},{"en":"Mrs.","ipa":"/ˈmɪsɪz/","cn":"n. 夫人","source":"supplement"},{"en":"refrigerator","ipa":"/rɪˈfrɪdʒəreɪtə/","cn":"n. 冰箱","source":"supplement"},{"en":"cooker","ipa":"/ˈkʊkə/","cn":"n. 炉具，炊具","source":"supplement"},{"en":"electric","ipa":"/ɪˈlektrɪk/","cn":"adj. 用电的","source":"supplement"},{"en":"left","ipa":"/left/","cn":"n. 左边","source":"supplement"},{"en":"middle","ipa":"/ˈmɪdl/","cn":"n. 中间","source":"supplement"},{"en":"room","ipa":"/ruːm/","cn":"n. 房间","source":"supplement"},{"en":"blue","ipa":"/bluː/","cn":"adj. 蓝色的","source":"supplement"},{"en":"white","ipa":"/waɪt/","cn":"adj. 白色的","source":"supplement"}],"patterns":[{"en":"There is a refrigerator in the kitchen.","cn":"厨房里有一台冰箱。（There is + 单数）","source":"adaptation"},{"en":"It's on the right.","cn":"它在右边。","source":"adaptation"},{"en":"The cooker is blue.","cn":"炉灶是蓝色的。","source":"adaptation"}],"grammar":"There is + 单数名词表示“某处有某物”；方位短语：on the left 在左边 / on the right 在右边 / in the middle 在中间。","tip":"the cooker 指“炉灶”，cooker 不是“厨师”（厨师是 cook）；the 用于特指双方都知道的东西。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Mrs. Smith's kitchen is small.","cn":"史密斯太太的厨房很小。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a refrigerator in the kitchen.","cn":"厨房里有个电冰箱。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The refrigerator is white.","cn":"冰箱是白色的。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is on the right.","cn":"它位于房间的右侧。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is an electric cooker in the kitchen.","cn":"厨房里有个电灶。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The cooker is blue.","cn":"电灶是蓝色的。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is on the left.","cn":"它位于房间的左边。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a table in the middle of the room.","cn":"房间的中央有张桌子。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a bottle on the table.","cn":"桌子上有个瓶子。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The bottle is empty.","cn":"瓶子是空的。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a cup on the table, too.","cn":"桌上还有一只杯子。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The cup is clean.","cn":"杯子很干净。","source":"adaptation","pdfPage":53,"printedPage":49,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"There is：说「哪里有什么」","chat":"想告诉别人房间里有什么东西，用 There is + 一个东西 + 位置。位置词很重要：on the right 在右边，on the left 在左边，in the middle 在中间。记住：说「某处有」用 There is，不能用 Have！","formula":"There is + a/an + 东西 + 位置. （某处有一个……）","examples":[{"en":"There is a refrigerator in the kitchen.","cn":"厨房里有台冰箱。","source":"supplement"},{"en":"The cooker is on the left.","cn":"炉子在左边。","source":"supplement"},{"en":"There is a table in the middle of the room.","cn":"房间中央有张桌子。","source":"supplement"}],"watch":"「某处有」用 There is，「某人有」才用 have：There is a TV in the room. ／ I have a TV.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"There ___ a refrigerator in the kitchen.","opts":["is","are","am","have"],"a":"is","why":"a refrigerator 单数用 There is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The cooker is on the ___.","opts":["left","right","middle","wall"],"a":"left","why":"课文：It is on the left.（电灶在左边）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"冰箱是什么颜色？","opts":["白色","蓝色","干净","很大"],"a":"白色","hint":"The refrigerator is white.","why":"白色的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"桌子在厨房的什么位置？","opts":["正中间","右边","左边","门附近"],"a":"正中间","hint":"in the middle of the room","why":"房间中央。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":53,"printedPage":49,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":26,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":25},{"id":27,"title":"Mrs. Smith's living room","titleCn":"史密斯太太的客厅","kind":"text","words":[{"en":"living room","ipa":"/ˈlɪvɪŋ ruːm/","cn":"n. 客厅","source":"supplement"},{"en":"armchair","ipa":"/ˈɑːmtʃeə/","cn":"n. 扶手椅","source":"supplement"},{"en":"near","ipa":"/nɪə/","cn":"prep. 靠近","source":"supplement"},{"en":"door","ipa":"/dɔː/","cn":"n. 门","source":"supplement"},{"en":"stereo","ipa":"/ˈsteriəʊ/","cn":"n. 立体声音响","source":"supplement"},{"en":"picture","ipa":"/ˈpɪktʃə/","cn":"n. 图画","source":"supplement"},{"en":"wall","ipa":"/wɔːl/","cn":"n. 墙","source":"supplement"},{"en":"window","ipa":"/ˈwɪndəʊ/","cn":"n. 窗户","source":"supplement"},{"en":"newspaper","ipa":"/ˈnjuːzpeɪpə/","cn":"n. 报纸","source":"supplement"},{"en":"magazine","ipa":"/ˌmægəˈziːn/","cn":"n. 杂志","source":"supplement"}],"patterns":[{"en":"There are some armchairs in the living room.","cn":"客厅里有几把扶手椅。（There are + 复数）","source":"adaptation"},{"en":"The pictures are on the wall.","cn":"画挂在墙上。","source":"adaptation"},{"en":"Where are they?","drill":true,"cn":"它们在哪儿？","source":"supplement"}],"grammar":"There are + 复数名词；对位置提问用 Where is...? / Where are...?；on the wall / near the door 等介词短语说明位置。","tip":"there be（某地“有”）与 have（某人“拥有”）分工不同：There is a TV in the room. ／ I have a TV.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Mrs. Smith's living room is large.","cn":"史密斯太太的客厅很大。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a television in the room.","cn":"客厅里有台电视机。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The television is near the window.","cn":"电视机靠近窗子。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some magazines on the television.","cn":"电视机上放着几本杂志。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a table in the room.","cn":"客厅里有张桌子。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some newspapers on the table.","cn":"桌上放着几份报纸。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some armchairs in the room.","cn":"客厅里有几把扶手椅。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The armchairs are near the table.","cn":"扶手椅靠近桌子。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There is a stereo near the door.","cn":"门附近有台立体声音响。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some books on the stereo.","cn":"音响上面放着几本书。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some pictures in the room.","cn":"客厅里有几幅画。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The pictures are on the wall.","cn":"画挂在墙上。","source":"adaptation","pdfPage":57,"printedPage":53,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"There are：东西变多了","chat":"东西从「一个」变成「好几个」，There is 就要变身 There are！问它们在哪里：Where are they? 回答用方位短语：near the door（在门附近）、on the wall（在墙上）。","formula":"There are + 复数名词 + 位置. ｜ Where is it?（单个）／ Where are they?（多个）","examples":[{"en":"There are some armchairs in the room.","cn":"房间里有几把扶手椅。","source":"supplement"},{"en":"The pictures are on the wall.","cn":"画挂在墙上。","source":"supplement"},{"en":"There are some books on the stereo.","cn":"音响上放着几本书。","source":"supplement"}],"watch":"先数一数：一个用 There is，两个以上用 There are——这是最容易混的一对！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"There ___ some magazines on the television.","opts":["are","is","am","have"],"a":"are","why":"magazines 复数用 There are。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"画挂在哪儿？","opts":["墙上","窗边","门后","桌子下面"],"a":"墙上","why":"The pictures are on the wall. 画挂在墙上。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"音响（stereo）在哪儿？","opts":["门附近","窗附近","墙上","桌子中间"],"a":"门附近","hint":"There is a stereo near the door.","why":"near the door。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"史密斯太太的客厅怎么样？","opts":["很大","很小","不整齐","很暗"],"a":"很大","hint":"Mrs. Smith's living room is large.","why":"large = 大。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":57,"printedPage":53,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":28,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":27},{"id":29,"title":"Come in, Amy.","titleCn":"进来，艾米。","kind":"text","words":[{"en":"shut","ipa":"/ʃʌt/","cn":"v. 关（门、窗）","source":"supplement"},{"en":"open","ipa":"/ˈəʊpən/","cn":"v. 打开","source":"supplement"},{"en":"bedroom","ipa":"/ˈbedruːm/","cn":"n. 卧室","source":"supplement"},{"en":"untidy","ipa":"/ʌnˈtaɪdi/","cn":"adj. 不整齐的","source":"supplement"},{"en":"must","ipa":"/mʌst/","cn":"v. 必须","source":"supplement"},{"en":"air","ipa":"/eə/","cn":"v. 使……通风；n. 空气","source":"supplement"},{"en":"clothes","ipa":"/kləʊðz/","cn":"n. 衣服（复数）","source":"supplement"},{"en":"wardrobe","ipa":"/ˈwɔːdrəʊb/","cn":"n. 衣柜","source":"supplement"},{"en":"sweep","ipa":"/swiːp/","cn":"v. 扫，打扫","source":"supplement"},{"en":"dust","ipa":"/dʌst/","cn":"v. 掸去灰尘；n. 灰尘","source":"supplement"}],"patterns":[{"en":"Come in and shut the door, please.","cn":"请进来把门关上。","source":"adaptation"},{"en":"This bedroom's very untidy.","cn":"这间卧室太不整齐了。","source":"adaptation"},{"en":"Open the window and air the room.","cn":"打开窗子，给房间通通风。","source":"adaptation"}],"grammar":"祈使句以动词原形开头，否定式在前面加 Don't：Shut the door. / Don't shut it. must 后接动词原形，表示“必须”。","tip":"家务高频动词短语：make the bed 铺床、sweep the floor 扫地、dust the table 掸灰、air the room 通风。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Come in, Amy.","cn":"进来，艾米。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Shut the door, please.","cn":"请把门关上。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This bedroom's very untidy.","cn":"这卧室太不整齐了。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What must I do, Mrs. Jones?","cn":"我应该做些什么呢，琼斯太太？","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Open the window and air the room.","cn":"打开窗子，给房间通通风。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then put these clothes in the wardrobe.","cn":"然后把这些衣服放进衣柜里。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then make the bed.","cn":"再把床整理一下。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then sweep the floor.","cn":"然后扫扫地。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then dust the dressing table.","cn":"然后掸掸梳妆台上的灰尘。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then empty the basket.","cn":"然后把纸篓倒掉。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And then you can read this magazine.","cn":"然后你就可以看这本杂志了。","source":"adaptation","pdfPage":61,"printedPage":57,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"祈使句：下指令的话","chat":"祈使句就是「指令句」，老师每天在说：Open the window!（开窗！）Shut the door!（关门！）它直接用动词开头，没有主语，加 please 就变礼貌。说「必须做什么」用 must + 动词原形。","formula":"动词原形 + 宾语 (+ please). ｜ must + 动词原形 = 必须","examples":[{"en":"Open the window and air the room.","cn":"打开窗户，给房间通风。","source":"supplement"},{"en":"Then make the bed.","cn":"然后整理床铺。","source":"supplement"},{"en":"What must I do, Mrs. Jones?","cn":"我必须做什么呢，琼斯太太？","source":"supplement"}],"watch":"祈使句的否定在前面加 Don't：Don't shut the door!（别关门！）——不是 not 开头哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ the door, please.","opts":["Shut","Shuts","Shutting","To shut"],"a":"Shut","why":"祈使句用动词原形开头。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Then put these clothes ___ the wardrobe.","opts":["in","on","under","at"],"a":"in","why":"放进衣柜用 in。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"卧室整齐吗？","opts":["不，太乱了","整齐","很干净","是新卧室"],"a":"不，太乱了","hint":"This bedroom's very untidy.","why":"untidy = 不整齐。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"艾米做的第一件事是什么？","opts":["开窗通风","整理床铺","扫地","看杂志"],"a":"开窗通风","hint":"Open the window and air the room.","why":"第一项是开窗通风。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":61,"printedPage":57,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":30,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":29},{"id":31,"title":"Where's Sally?","titleCn":"萨莉在哪里？","kind":"text","words":[{"en":"garden","ipa":"/ˈɡɑːdn/","cn":"n. 花园","source":"supplement"},{"en":"under","ipa":"/ˈʌndə/","cn":"prep. 在……下面","source":"supplement"},{"en":"tree","ipa":"/triː/","cn":"n. 树","source":"supplement"},{"en":"climb","ipa":"/klaɪm/","cn":"v. 爬，攀登","source":"supplement"},{"en":"run","ipa":"/rʌn/","cn":"v. 跑","source":"supplement"},{"en":"grass","ipa":"/ɡrɑːs/","cn":"n. 草地","source":"supplement"},{"en":"after","ipa":"/ˈɑːftə/","cn":"prep. 在……之后（run after 追赶）","source":"supplement"},{"en":"type","ipa":"/taɪp/","cn":"v. 打字","source":"supplement"},{"en":"drink","ipa":"/drɪŋk/","cn":"v. 喝","source":"supplement"},{"en":"eat","ipa":"/iːt/","cn":"v. 吃","source":"supplement"}],"patterns":[{"en":"She's sitting under the tree.","cn":"她正坐在树下。（现在进行时）","source":"adaptation"},{"en":"What's she doing?","cn":"她在做什么？","source":"adaptation"},{"en":"It's running after a cat.","cn":"它正在追一只猫。","source":"adaptation"}],"grammar":"现在进行时 = be + 动词-ing，表示说话时正在进行的动作；对正在做的事提问用 What's he/she doing?","tip":"动词变 -ing 三规则：直接加（do→doing）、去 e 加（make→making）、重读闭音节双写尾字母（run→running）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Where's Sally, Jack?","cn":"杰克，萨莉在哪儿？","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She's in the garden, Jean.","cn":"她在花园里，简。","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's she doing?","cn":"她在做什么？","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She's sitting under the tree.","cn":"她正在树荫下坐着。","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is Tim in the garden, too?","cn":"蒂姆也在花园里吗？","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, he is. He's climbing the tree.","cn":"是的，他正在爬树。","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I beg your pardon? Who's climbing the tree?","cn":"你说什么？谁在爬树？","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Tim is.","cn":"蒂姆在爬树。","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about the dog?","cn":"那狗呢？","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The dog's in the garden, too. It's running across the grass. It's running after a cat.","cn":"狗也在花园里，它正在草地上跑，在追一只猫。","source":"adaptation","pdfPage":65,"printedPage":61,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"现在进行时：正在播的动作","chat":"现在进行时就像给动作拍「正在播」的视频：be（am/is/are）+ 动词ing。她正坐着 She's sitting.。问「正在做什么」：What's she doing? 回答也用进行时。","formula":"主语 + am/is/are + 动词ing（正在……）","examples":[{"en":"She's sitting under the tree.","cn":"她正坐在树下。","source":"supplement"},{"en":"What's Tim doing? He's climbing the tree.","cn":"蒂姆在干什么？他在爬树。","source":"supplement"},{"en":"It's running after a cat.","cn":"它正在追一只猫。","source":"supplement"}],"watch":"动词变 ing 三规则：直接加（do→doing）、去 e 加（make→making）、双写尾字母（run→running）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"She ___ sitting under the tree.","opts":["is","are","am","be"],"a":"is","why":"She 配 is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The dog is running ___ a cat.","opts":["after","over","under","at"],"a":"after","why":"run after = 追赶。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"萨莉在哪儿？","opts":["花园里","卧室里","学校","厨房"],"a":"花园里","hint":"She's in the garden.","why":"在花园的树下。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"蒂姆正在做什么？","opts":["爬树","坐在树下","在草地上跑","喝牛奶"],"a":"爬树","hint":"He's climbing the tree.","why":"Tim is climbing the tree.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":65,"printedPage":61,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":32,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":31},{"id":33,"title":"A fine day","titleCn":"晴天","kind":"text","words":[{"en":"sun","ipa":"/sʌn/","cn":"n. 太阳","source":"supplement"},{"en":"shine","ipa":"/ʃaɪn/","cn":"v. 照耀","source":"supplement"},{"en":"cloud","ipa":"/klaʊd/","cn":"n. 云","source":"supplement"},{"en":"sky","ipa":"/skaɪ/","cn":"n. 天空","source":"supplement"},{"en":"family","ipa":"/ˈfæməli/","cn":"n. 家庭","source":"supplement"},{"en":"walk","ipa":"/wɔːk/","cn":"v. 走路，散步","source":"supplement"},{"en":"bridge","ipa":"/brɪdʒ/","cn":"n. 桥","source":"supplement"},{"en":"boat","ipa":"/bəʊt/","cn":"n. 小船","source":"supplement"},{"en":"ship","ipa":"/ʃɪp/","cn":"n. 大船","source":"supplement"},{"en":"fly","ipa":"/flaɪ/","cn":"v. 飞；放（风筝）","source":"supplement"}],"patterns":[{"en":"It is a fine day today.","cn":"今天天气好。","source":"adaptation"},{"en":"There are some clouds in the sky, but the sun is shining.","cn":"天上有几朵云，但阳光灿烂。","source":"adaptation"},{"en":"They are walking over the bridge.","cn":"他们正在过桥。","source":"adaptation"}],"grammar":"现在进行时描绘眼前画面；walk over the bridge 中的 over 表示“越过”；look at / walk over 都是“动词 + 介词”搭配。","tip":"英式英语写 aeroplane，美式写 airplane；boat 是小船，ship 是大船。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"It is a fine day today.","cn":"今天天气好。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some clouds in the sky, but the sun is shining.","cn":"天上有几朵云，但阳光灿烂。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mr. Jones is with his family. They are walking over the bridge.","cn":"琼斯先生同他的家人在一起，他们正在过桥。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There are some boats on the river.","cn":"河上有几条小船。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mr. Jones and his wife are looking at them.","cn":"琼斯先生和他的妻子正在看这些船。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Sally is looking at a big ship.","cn":"萨莉正在看一艘大船。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The ship is going under the bridge.","cn":"那大船正从桥下驶过。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Tim is looking at an aeroplane.","cn":"蒂姆正在看一架飞机。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The aeroplane is flying over the river.","cn":"飞机正从河上飞过。","source":"adaptation","pdfPage":69,"printedPage":65,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"用进行时描绘一幅画","chat":"今天用进行时来「画」一幅风景：太阳正在照 The sun is shining. 人们正在过桥 They are walking over the bridge. over 在这里表示「越过」，走到桥的另一头。","formula":"主语 + is/are + 动词ing + 地点/方向.","examples":[{"en":"The sun is shining.","cn":"阳光正灿烂。","source":"supplement"},{"en":"They are walking over the bridge.","cn":"他们正在过桥。","source":"supplement"},{"en":"The ship is going under the bridge.","cn":"船正从桥下驶过。","source":"supplement"}],"watch":"over = 越过（从上方过去），under = 从下面过去：船过桥用 under！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"The sun ___ shining.","opts":["is","are","am","be"],"a":"is","why":"the sun 单数配 is。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"There are some boats ___ the river.","opts":["on","in","under","over"],"a":"on","why":"「在河上」的船用 on the river。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"今天天气怎么样？","opts":["晴天","雨天","雪天","大风"],"a":"晴天","hint":"It is a fine day today.","why":"fine day 晴天。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"蒂姆正在看什么？","opts":["一架飞机","一艘大船","一座桥","几条小船"],"a":"一架飞机","hint":"Tim is looking at an aeroplane.","why":"萨莉看大船，蒂姆看飞机。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":69,"printedPage":65,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":34,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":33},{"id":35,"title":"Our village","titleCn":"我们的村庄","kind":"text","words":[{"en":"photograph","ipa":"/ˈfəʊtəɡrɑːf/","cn":"n. 照片","source":"supplement"},{"en":"village","ipa":"/ˈvɪlɪdʒ/","cn":"n. 村庄","source":"supplement"},{"en":"between","ipa":"/bɪˈtwiːn/","cn":"prep. 在……之间","source":"supplement"},{"en":"hill","ipa":"/hɪl/","cn":"n. 小山","source":"supplement"},{"en":"wife","ipa":"/waɪf/","cn":"n. 妻子","source":"supplement"},{"en":"along","ipa":"/əˈlɒŋ/","cn":"prep. 沿着","source":"supplement"},{"en":"bank","ipa":"/bæŋk/","cn":"n. 河岸；银行","source":"supplement"},{"en":"swim","ipa":"/swɪm/","cn":"v. 游泳","source":"supplement"},{"en":"building","ipa":"/ˈbɪldɪŋ/","cn":"n. 大楼，建筑物","source":"supplement"},{"en":"park","ipa":"/pɑːk/","cn":"n. 公园","source":"supplement"}],"patterns":[{"en":"This is a photograph of our village.","cn":"这是我们村庄的一张照片。","source":"textbook","pdfPage":73,"printedPage":69,"verification":"verified","translationSource":"supplement"},{"en":"It is between two hills.","cn":"它位于两座小山之间。","source":"textbook","pdfPage":73,"printedPage":69,"verification":"verified","translationSource":"supplement"},{"en":"My wife and I are walking along the banks of the river.","cn":"我和妻子正沿着河岸散步。","source":"textbook","pdfPage":73,"printedPage":69,"verification":"verified","translationSource":"supplement"}],"grammar":"between 表示“在两者之间”；along 沿着（静态路径），into 进入（动态方向）；a photograph of... 中 of 表所属。","tip":"bank 既指“河岸”也指“银行”，靠上下文区分；walk along... 沿着走，walk into... 走进。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"This is a photograph of our village.","cn":"这是我们村庄的一张照片。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Our village is in a valley.","cn":"我们的村庄坐落在一个山谷之中。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It is between two hills.","cn":"它位于两座小山之间。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"The village is on a river.","cn":"它靠近一条小河。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Here is another photograph of the village.","cn":"这是我们村庄的另一张照片。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My wife and I are walking along the banks of the river.","cn":"我和妻子正沿河岸走着。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"We are on the left.","cn":"我们在照片的左边。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"There is a boy in the water.","cn":"河里有个男孩。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He is swimming across the river.","cn":"他正横渡小河。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Here is another photograph.","cn":"这是另一张照片。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"This is the school building.","cn":"这是学校大楼。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It is beside a park. The park is on the right.","cn":"它位于公园的旁边，公园在右面。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Some children are coming out of the building. Some of them are going into the park.","cn":"一些孩子正从楼里出来，他们中有几个正走进公园。","source":"textbook","pdfPage":73,"printedPage":69,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"方位介词：位置小词典","chat":"这课认识四个方位介词：between（在两者之间）、along（沿着）、across（横穿）、into（走进）。用它们说说照片里的人在哪儿、往哪儿去。","formula":"between A and B ｜ along the river 沿河 ｜ across 横穿 ｜ into 进入","examples":[{"en":"It is between two hills.","cn":"它在两座小山之间。","source":"supplement"},{"en":"He is swimming across the river.","cn":"他正游过河。","source":"supplement"},{"en":"Some of them are going into the park.","cn":"他们中的一些正走进公园。","source":"supplement"}],"watch":"into 是「从外到里」（有方向），in 是「已经在里面」（静态）：walk into the park 走进公园。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"Our village is ___ a valley.","opts":["in","on","between","under"],"a":"in","why":"在山谷「里」用 in a valley。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"It is ___ two hills.","opts":["between","along","across","into"],"a":"between","why":"between 表示「在两者之间」。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"水里的男孩正在做什么？","opts":["游过河","沿着河岸走","走进公园","从学校出来"],"a":"游过河","hint":"He is swimming across the river.","why":"他正横渡小河。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"课文说公园在照片画面的哪一边？","opts":["右边","左边","正前方","后面"],"a":"右边","hint":"The park is on the right.","why":"The park is on the right. 这里的右边以照片画面为参照，不是人物朝向。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":73,"printedPage":69,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":36,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":35},{"id":37,"title":"Making a bookcase","titleCn":"做书架","kind":"text","words":[{"en":"work","ipa":"/wɜːk/","cn":"v. 工作","source":"supplement"},{"en":"hard","ipa":"/hɑːd/","cn":"adv. 努力地；adj. 硬的","source":"supplement"},{"en":"make","ipa":"/meɪk/","cn":"v. 做","source":"supplement"},{"en":"bookcase","ipa":"/ˈbʊkkeɪs/","cn":"n. 书架","source":"supplement"},{"en":"hammer","ipa":"/ˈhæmə/","cn":"n. 锤子","source":"supplement"},{"en":"paint","ipa":"/peɪnt/","cn":"v. 刷漆；n. 油漆","source":"supplement"},{"en":"pink","ipa":"/pɪŋk/","cn":"adj. 粉红色的","source":"supplement"},{"en":"favourite","ipa":"/ˈfeɪvərɪt/","cn":"adj. 最喜欢的","source":"supplement"},{"en":"daughter","ipa":"/ˈdɔːtə/","cn":"n. 女儿","source":"supplement"},{"en":"for","ipa":"/fɔː/","cn":"prep. 给，为","source":"supplement"}],"patterns":[{"en":"You're working hard!","cn":"你干得真卖力！","source":"adaptation"},{"en":"I'm making a bookcase.","cn":"我正在做一个书架。","source":"adaptation"},{"en":"What are you going to do?","cn":"你打算做什么？","source":"adaptation"},{"en":"I'm going to paint it pink.","cn":"我打算把它漆成粉红色。","source":"adaptation"}],"grammar":"be going to + 动词原形表示“打算、将要”；paint it pink 是“动词 + 宾语 + 宾语补足语”结构（把它漆成粉色）。","tip":"be doing（正在做）与 be going to do（打算做）只差一个 going，一个看眼前、一个看计划。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"You're working hard, George. What are you doing?","cn":"你干得真卖力，乔治。你在做什么呢？","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm making a bookcase. Give me that hammer, please, Dan.","cn":"我正在做一个书架。请把那把锤子递给我，丹。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Which hammer? This one?","cn":"哪一把？是这把吗？","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, not that one. The big one.","cn":"不，不是那把，是那把大的。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are.","cn":"给你。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thanks, Dan.","cn":"谢谢，丹。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What are you going to do now, George?","cn":"你现在打算做什么，乔治？","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm going to paint it.","cn":"我打算给它刷上漆。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What colour are you going to paint it?","cn":"你打算把它漆成什么颜色？","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm going to paint it pink.","cn":"我想漆成粉红色。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Pink!","cn":"粉红色！","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This bookcase isn't for me. It's for my daughter, Susan. Pink's her favourite colour.","cn":"这个书架不是为我做的，是为我女儿苏珊做的。粉红色是她最喜欢的颜色。","source":"adaptation","pdfPage":77,"printedPage":73,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"be going to：打算做的事","chat":"说「打算做某事」（还没做，计划中），用 be going to + 动词原形：I'm going to paint it.（我打算给它刷漆）。问别人打算：What are you going to do?","formula":"主语 + am/is/are going to + 动词原形（打算做……）","examples":[{"en":"I'm going to paint it pink.","cn":"我打算把它漆成粉色。","source":"supplement"},{"en":"What are you going to do now, George?","cn":"乔治，你现在打算做什么？","source":"supplement"},{"en":"This bookcase isn't for me. It's for my daughter.","cn":"这书架不是给我的，是给我女儿的。","source":"supplement"}],"watch":"be doing = 眼前正在做；be going to do = 计划要做——一个是「直播」，一个是「预告片」！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I'm going ___ it.","opts":["to paint","painting","paint","painted"],"a":"to paint","why":"be going to + 动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Give me that ___, please.","opts":["hammer","book","cake","cup"],"a":"hammer","why":"做书架需要锤子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"乔治正在做什么？","opts":["做书架","刷墙","做桌子","整理花园"],"a":"做书架","hint":"I'm making a bookcase.","why":"making a bookcase。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"书架是给谁做的？","opts":["女儿苏珊","丹","他自己","他妻子"],"a":"女儿苏珊","hint":"It's for my daughter, Susan.","why":"粉红色是苏珊最喜欢的颜色。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":77,"printedPage":73,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":38,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":37},{"id":39,"title":"Don't drop it!","titleCn":"别摔了！","kind":"text","words":[{"en":"front","ipa":"/frʌnt/","cn":"n. 前面（in front of 在……前面）","source":"supplement"},{"en":"careful","ipa":"/ˈkeəfʊl/","cn":"adj. 小心的","source":"supplement"},{"en":"vase","ipa":"/vɑːz/","cn":"n. 花瓶","source":"supplement"},{"en":"drop","ipa":"/drɒp/","cn":"v. 掉落，失手落下","source":"supplement"},{"en":"flower","ipa":"/ˈflaʊə/","cn":"n. 花","source":"supplement"},{"en":"show","ipa":"/ʃəʊ/","cn":"v. 给……看","source":"supplement"},{"en":"send","ipa":"/send/","cn":"v. 寄，送","source":"supplement"},{"en":"take","ipa":"/teɪk/","cn":"v. 拿，带走","source":"supplement"},{"en":"with","ipa":"/wɪð/","cn":"prep. 关于（do with 处理）；和……一起","source":"supplement"}],"patterns":[{"en":"What are you going to do with that vase?","cn":"你打算拿那个花瓶怎么办？","source":"adaptation"},{"en":"Don't drop it!","cn":"别摔了！（祈使句否定式）","source":"adaptation"},{"en":"Be careful!","cn":"小心！","source":"adaptation"},{"en":"I'm going to send it to my mother.","drill":true,"cn":"我准备把它寄给我妈妈。","source":"supplement"}],"grammar":"祈使句的否定式 = Don't + 动词原形：Don't drop it! / Don't do that!；send sth to sb = send sb sth（双宾语）。","tip":"do with 表示“处理、安置”；Be careful! 比 Take care! 更急迫；in front of 指“在某物外部的前面”。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"What are you going to do with that vase, Penny?","cn":"你打算拿那个花瓶怎么办，彭妮？","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm going to put it on this table, Sam.","cn":"我打算把它放在这张桌子上，萨姆。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Don't do that. Give it to me.","cn":"不要放在那里，把它给我。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What are you going to do with it?","cn":"你打算拿它怎么办？","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm going to put it here, in front of the window.","cn":"我打算把它放在这儿，放在窗前。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Be careful! Don't drop it!","cn":"小心点！别摔了！","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Don't put it there, Sam. Put it here, on this shelf.","cn":"别放在那儿，萨姆。放在这儿，放在这个架子上。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There we are! It's a lovely vase.","cn":"好了！这是只漂亮的花瓶。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Those flowers are lovely, too.","cn":"那些花也很漂亮。","source":"adaptation","pdfPage":81,"printedPage":77,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"Don't…!：劝人别做某事","chat":"劝别人「别做某事」，在动词前加 Don't：Don't drop it!（别摔了！）。提醒小心说 Be careful!。「把东西给某人」：give/send/show + 东西 + to + 人。","formula":"Don't + 动词原形! ｜ Be careful! ｜ give/send sth to sb","examples":[{"en":"Be careful! Don't drop it!","cn":"小心！别摔了！","source":"supplement"},{"en":"Don't put it there, Sam.","cn":"萨姆，别放在那儿。","source":"supplement"},{"en":"I'm going to send it to my mother.","cn":"我打算把它寄给我妈妈。","source":"supplement"}],"watch":"祈使句本来就没有主语，否定是 Don't 开头，不是 not 开头哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ drop it!","opts":["Don't","Not","No","Doesn't"],"a":"Don't","why":"祈使句否定用 Don't + 动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I'm going to send it ___ my mother.","opts":["to","for","at","with"],"a":"to","why":"send sth to sb 寄给某人。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"彭妮一开始打算把花瓶放在哪儿？","opts":["这张桌子上","窗前","架子上","地板上"],"a":"这张桌子上","hint":"I'm going to put it on this table.","why":"萨姆说 Don't do that，才改的地方。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"花瓶最后放在哪儿？","opts":["这个架子上","那张桌子上","窗前","萨姆手里"],"a":"这个架子上","hint":"Put it here, on this shelf.","why":"彭妮让萨姆放在架子上。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":81,"printedPage":77,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":40,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":39},{"id":41,"title":"Penny's bag","titleCn":"彭妮的提包","kind":"text","words":[{"en":"cheese","ipa":"/tʃiːz/","cn":"n. 奶酪","source":"supplement"},{"en":"bread","ipa":"/bred/","cn":"n. 面包","source":"supplement"},{"en":"soap","ipa":"/səʊp/","cn":"n. 肥皂","source":"supplement"},{"en":"chocolate","ipa":"/ˈtʃɒklət/","cn":"n. 巧克力","source":"supplement"},{"en":"sugar","ipa":"/ˈʃʊɡə/","cn":"n. 糖","source":"supplement"},{"en":"coffee","ipa":"/ˈkɒfi/","cn":"n. 咖啡","source":"supplement"},{"en":"tea","ipa":"/tiː/","cn":"n. 茶","source":"supplement"},{"en":"tobacco","ipa":"/təˈbækəʊ/","cn":"n. 烟草，烟丝","source":"supplement"},{"en":"piece","ipa":"/piːs/","cn":"n. 片，块（a piece of）","source":"supplement"},{"en":"loaf","ipa":"/ləʊf/","cn":"n. 一条（面包）（a loaf of）","source":"supplement"}],"patterns":[{"en":"Is that bag heavy, Penny?","cn":"那个提包重吗，彭妮？","source":"adaptation"},{"en":"A piece of cheese.","cn":"一块奶酪。","source":"adaptation"},{"en":"A loaf of bread.","cn":"一条面包。","source":"adaptation"}],"grammar":"不可数名词计量用“a ... of”短语：a piece of cheese / a bar of soap / a bottle of milk / a tin of tobacco；它们一般没有复数形式。","tip":"cheese、bread、soap、sugar、coffee、tea、chocolate 都是常见不可数名词——不能加 s，不能用 a 直接修饰。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Is that bag heavy, Penny?","cn":"那个提包重吗，彭妮？","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Not very.","cn":"不太重。","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here! Put it on this chair. What's in it?","cn":"放在这把椅子上。里面是什么东西？","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"A piece of cheese. A loaf of bread. A bar of chocolate.","cn":"一块奶酪、一条面包、一块巧克力。","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"A bottle of milk. A pound of sugar. Half a pound of coffee.","cn":"一瓶牛奶、一磅糖、半磅咖啡。","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"A quarter of a pound of tea. And a tin of tobacco.","cn":"四分之一磅茶叶，还有一听烟丝。","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is that tin of tobacco for me?","cn":"那听烟丝是给我的吗？","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, it's certainly not for me!","cn":"噢，当然不是给我的！","source":"adaptation","pdfPage":85,"printedPage":81,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"不可数名词的「量杯」","chat":"水、面包、糖这些词数不清个数，叫「不可数名词」。想表达「多少」，要请「量杯」来帮忙：a piece of（一块）、a loaf of（一条）、a bottle of（一瓶）、a pound of（一磅）。","formula":"a + 单位 + of + 不可数名词：a piece of cheese 一块奶酪","examples":[{"en":"A loaf of bread.","cn":"一条面包。","source":"supplement"},{"en":"A bottle of milk.","cn":"一瓶牛奶。","source":"supplement"},{"en":"A quarter of a pound of tea.","cn":"四分之一磅茶叶。","source":"supplement"}],"watch":"不可数名词不能加 s、不能直接加 a：不说 a bread，要说 a loaf of bread！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ cheese.","opts":["A piece of","A piece","Pieces of a","Some piece of"],"a":"A piece of","why":"不可数名词用 a piece of 计量。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Is that bag ___?","opts":["heavy","heavily","heavier","heaviest"],"a":"heavy","why":"be 动词后接形容词原级。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"下面哪样东西不在彭妮的包里？","opts":["一只鸡","一块奶酪","一条面包","一块巧克力"],"a":"一只鸡","hint":"cheese, bread, chocolate, milk, sugar, coffee, tea, tobacco","why":"包里没有鸡！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"那听烟丝是给谁的？","opts":["萨姆","彭妮","孩子们","汤姆"],"a":"萨姆","hint":"Is that tin of tobacco for me? — Well, it's certainly not for me!","why":"不是彭妮的，那就是问话的萨姆的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":85,"printedPage":81,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":42,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":41},{"id":43,"title":"Hurry up!","titleCn":"快点！","kind":"text","words":[{"en":"kettle","ipa":"/ˈketl/","cn":"n. 水壶","source":"supplement"},{"en":"behind","ipa":"/bɪˈhaɪnd/","cn":"prep. 在……后面","source":"supplement"},{"en":"teapot","ipa":"/ˈtiːpɒt/","cn":"n. 茶壶","source":"supplement"},{"en":"now","ipa":"/naʊ/","cn":"adv. 现在","source":"supplement"},{"en":"find","ipa":"/faɪnd/","cn":"v. 找到","source":"supplement"},{"en":"boil","ipa":"/bɔɪl/","cn":"v. 沸腾，烧开","source":"supplement"},{"en":"water","ipa":"/ˈwɔːtə/","cn":"n. 水","source":"supplement"},{"en":"hurry","ipa":"/ˈhʌri/","cn":"v. 赶快","source":"supplement"}],"patterns":[{"en":"Can you make the tea, Sam?","cn":"萨姆，你会沏茶吗？","source":"adaptation"},{"en":"Is there any water in this kettle?","cn":"这壶里有水吗？（疑问句用 any）","source":"adaptation"},{"en":"Hurry up!","cn":"快点！","source":"adaptation"}],"grammar":"表示“一些”时，肯定句通常用 some，普通疑问句和否定句通常用 any；请求或期待肯定回答的问句也可用 some。There be 的一般疑问句把 be 动词提前：Is there any...?","tip":"water 不可数：一些水说 some water；hurry up 快点，名词短语 in a hurry 表示“匆忙”。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Can you make the tea, Sam?","cn":"你会沏茶吗，萨姆？","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, of course I can, Penny.","cn":"会的，我当然会，彭妮。","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is there any water in this kettle?","cn":"这水壶里有水吗？","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, there is.","cn":"有。","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Where's the tea?","cn":"茶叶在哪儿？","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's there, behind the teapot.","cn":"就在那儿，茶壶后面。","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you see it?","cn":"你看见了吗？","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I can see the teapot, but I can't see the tea.","cn":"我看见茶壶了，但没看见茶叶。","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There it is! It's in front of you!","cn":"那不是嘛！就在你眼前！","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Ah yes, I can see it now.","cn":"噢，是啊，我现在看到了。","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Hurry up, Sam! The kettle's boiling!","cn":"快点，萨姆！水壶开了！","source":"adaptation","pdfPage":89,"printedPage":85,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"some 和 any 的分工","chat":"some 和 any 都可以表示“一些”。本课肯定句用 some（There’s some water.），普通疑问句和否定句用 any（Is there any water? / There isn’t any tea.）。这是常见用法，不是绝对规则；请求、邀请或期待肯定回答时，问句也可以用 some。","formula":"表示“一些”：肯定句通常用 some ｜ 普通疑问句、否定句通常用 any（还要看语境）","examples":[{"en":"Is there any water in this kettle?","cn":"这壶里有水吗？","source":"supplement"},{"en":"Yes, there is.","cn":"是的，有。","source":"supplement"},{"en":"Hurry up! The kettle's boiling!","cn":"快点！水开了！","source":"supplement"}],"watch":"水不可数：说 some water，不能说 a water 或 waters！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"根据本课常见表达，补全原句：Is there ___ water in this kettle?","opts":["any","some","many","a"],"a":"any","why":"本题按本课给出的表达选择 any；some/any 的选择还受语境影响，不能把疑问句或否定句一律当作排除 some 的依据。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The tea is behind the ___.","opts":["teapot","kettle","door","cup"],"a":"teapot","why":"behind the teapot 在茶壶后面。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"萨姆一开始找不到什么？","opts":["茶叶","水壶","水","杯子"],"a":"茶叶","hint":"I can see the teapot, but I can't see the tea.","why":"看见茶壶看不见茶叶。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"谁在催萨姆？","opts":["彭妮","露西","海伦","克里斯廷"],"a":"彭妮","hint":"Hurry up, Sam!","why":"彭妮说水开了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":89,"printedPage":85,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":44,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":43},{"id":45,"title":"The boss's letter","titleCn":"老板的信","kind":"text","words":[{"en":"boss","ipa":"/bɒs/","cn":"n. 老板，上司","source":"supplement"},{"en":"minute","ipa":"/ˈmɪnɪt/","cn":"n. 分钟","source":"supplement"},{"en":"ask","ipa":"/ɑːsk/","cn":"v. 请（某人做）；问","source":"supplement"},{"en":"handwriting","ipa":"/ˈhændraɪtɪŋ/","cn":"n. 书写，笔迹","source":"supplement"},{"en":"terrible","ipa":"/ˈterəbl/","cn":"adj. 糟糕的","source":"supplement"},{"en":"can","ipa":"/kæn/","cn":"aux. 能，可以","source":"supplement"},{"en":"lift","ipa":"/lɪft/","cn":"v. 举起，搬起","source":"supplement"},{"en":"cake","ipa":"/keɪk/","cn":"n. 蛋糕","source":"supplement"},{"en":"carry","ipa":"/ˈkæri/","cn":"v. 搬运，携带","source":"supplement"}],"patterns":[{"en":"Can you come here a minute, please?","cn":"请你来一下好吗？","source":"adaptation"},{"en":"Can she type this letter for me?","cn":"她能替我打一下这封信吗？","source":"adaptation"},{"en":"I can't read it!","cn":"我认不出来！（can't = cannot）","source":"adaptation"}],"grammar":"can 后接动词原形，没有人称变化；否定式 can't；for me 表示“替我”。","tip":"用 Can you...? 提出请求，接受说 Of course. / Sure.，拒绝更礼貌的说法是 Sorry, I can't.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Can you come here a minute, please, Bob?","cn":"鲍勃，请你来一下好吗？","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, sir?","cn":"什么事，先生？","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Where's Pamela?","cn":"帕梅拉在哪儿？","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She's next door. She's in her office, sir.","cn":"她在隔壁，在她的办公室里，先生。","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can she type this letter for me? Ask her please.","cn":"她能为我打一下这封信吗？请问问她。","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, sir.","cn":"好的，先生。","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you type this letter for the boss, please, Pamela?","cn":"帕梅拉，请你为老板打一下这封信好吗？","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, of course I can.","cn":"当然可以。","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are.","cn":"给您信。","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you, Bob. Bob!","cn":"谢谢你，鲍勃。鲍勃！","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes? What's the matter?","cn":"怎么了？怎么回事？","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I can't type this letter. I can't read it! The boss's handwriting is terrible!","cn":"我打不了这封信，我没法辨认！老板的字迹太糟糕了！","source":"adaptation","pdfPage":93,"printedPage":89,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"can：万能的「能、可以」","chat":"can 表示「能、会、可以」，后面直接跟动词原形，不管我是你还是他，can 都不变！否定是 can't。礼貌请求别人：Can you…, please?","formula":"Can + 主语 + 动词原形? → Yes, …can. ／ No, …can't.","examples":[{"en":"Can you come here a minute, please?","cn":"你能来一下吗？","source":"supplement"},{"en":"Can she type this letter for me?","cn":"她能帮我打这封信吗？","source":"supplement"},{"en":"I can't read it!","cn":"我没法辨认它！","source":"supplement"}],"watch":"can 后面的动词永远用原形：she can types ❌ → she can type ✓（不加 s！）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Can she ___ this letter for me?","opts":["type","types","typing","typed"],"a":"type","why":"can 后面跟动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The boss's handwriting is ___.","opts":["terrible","good","beautiful","nice"],"a":"terrible","why":"老板字迹太糟糕。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"帕梅拉在哪儿？","opts":["隔壁她的办公室","家里","街上","厨房"],"a":"隔壁她的办公室","hint":"She's next door. She's in her office.","why":"在隔壁办公室。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"帕梅拉为什么打不了这封信？","opts":["认不出老板的字迹","她太忙","她不会打字","她生病了"],"a":"认不出老板的字迹","hint":"I can't read it!","why":"字太潦草，不是不会打字。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":93,"printedPage":89,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":46,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":45},{"id":47,"title":"A cup of coffee","titleCn":"一杯咖啡","kind":"text","words":[{"en":"like","ipa":"/laɪk/","cn":"v. 喜欢","source":"supplement"},{"en":"want","ipa":"/wɒnt/","cn":"v. 想要","source":"supplement"},{"en":"cup","ipa":"/kʌp/","cn":"n. 杯子","source":"supplement"},{"en":"black","ipa":"/blæk/","cn":"adj. 不加牛奶的；黑色的","source":"supplement"},{"en":"biscuit","ipa":"/ˈbɪskɪt/","cn":"n. 饼干","source":"supplement"},{"en":"fresh","ipa":"/freʃ/","cn":"adj. 新鲜的","source":"supplement"},{"en":"egg","ipa":"/eɡ/","cn":"n. 鸡蛋","source":"supplement"},{"en":"butter","ipa":"/ˈbʌtə/","cn":"n. 黄油","source":"supplement"},{"en":"honey","ipa":"/ˈhʌni/","cn":"n. 蜂蜜","source":"supplement"},{"en":"jam","ipa":"/dʒæm/","cn":"n. 果酱","source":"supplement"}],"patterns":[{"en":"Do you like coffee?","cn":"你喜欢咖啡吗？（问长期喜好）","source":"adaptation"},{"en":"Do you want a cup?","cn":"你想要一杯吗？（问此刻想要）","source":"adaptation"},{"en":"Yes, please. / No, thank you.","cn":"好的，来一杯。／不用了，谢谢。","source":"adaptation"}],"grammar":"Do you like...? 问习惯性喜好，回答 Yes, I do.；Do you want...? 问此时此刻想要什么；礼貌接受 Yes, please.，婉拒 No, thank you.","tip":"black coffee 指“清咖啡（不加奶）”，与颜色无关；想加奶说 with milk, please.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you like coffee, Ann?","cn":"你喜欢咖啡吗，安？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I do.","cn":"是的，我喜欢。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want a cup?","cn":"你想要来一杯吗？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please, Christine.","cn":"好的，请来一杯，克里斯廷。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want any sugar?","cn":"你要加些糖吗？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please.","cn":"好的，请加一些。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want any milk?","cn":"你要放些牛奶吗？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, thank you. I don't want any milk, thank you. I like black coffee.","cn":"不了，谢谢。我不要牛奶，我喜欢清咖啡。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you like biscuits?","cn":"你喜欢饼干吗？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I do.","cn":"是的，喜欢。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want one?","cn":"你想要一块吗？","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please.","cn":"好的，请来一块。","source":"adaptation","pdfPage":97,"printedPage":93,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"like 与 want：喜欢和想要","chat":"Do you like…? 问「你（一贯）喜欢……吗」，是问爱好；Do you want…? 问「你现在想要……吗」，是问此刻。别人给你东西，接受说 Yes, please.，拒绝说 No, thank you.——这对礼貌用语天天用得上！","formula":"Do you like + 东西?（问爱好）｜ Do you want + 东西?（问此刻想要）","examples":[{"en":"Do you like coffee?","cn":"你喜欢咖啡吗？","source":"supplement"},{"en":"Do you want a cup?","cn":"你想来一杯吗？","source":"supplement"},{"en":"No, thank you. I like black coffee.","cn":"不了谢谢，我喜欢清咖啡。","source":"supplement"}],"watch":"black coffee 是「不加奶的清咖啡」，和颜色没关系！接受要说 Yes, please.，不能只说 Yes!","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ you like coffee?","opts":["Do","Does","Are","Is"],"a":"Do","why":"这是一般现在时、含实义动词 like 的疑问句；主语 you 用 Do。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"根据本课常见表达，补全原句：I don't want ___ milk.","opts":["any","some","many","a"],"a":"any","why":"本题按本课给出的表达选择 any；some/any 的选择还受语境影响，不能把疑问句或否定句一律当作排除 some 的依据。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"安喜欢什么样的咖啡？","opts":["清咖啡（不加奶）","加奶咖啡","加很多糖","茶"],"a":"清咖啡（不加奶）","hint":"I like black coffee.","why":"black coffee = 清咖啡。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"安要加糖吗？","opts":["要","不要","加很多","只要一点"],"a":"要","hint":"Do you want any sugar? Yes, please.","why":"她要加糖，但不要牛奶。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":97,"printedPage":93,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":48,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":47},{"id":49,"title":"At the butcher's","titleCn":"在肉店","kind":"text","words":[{"en":"butcher","ipa":"/ˈbʊtʃə/","cn":"n. 卖肉的，肉商","source":"supplement"},{"en":"meat","ipa":"/miːt/","cn":"n. 肉","source":"supplement"},{"en":"beef","ipa":"/biːf/","cn":"n. 牛肉","source":"supplement"},{"en":"lamb","ipa":"/læm/","cn":"n. 羔羊肉","source":"supplement"},{"en":"husband","ipa":"/ˈhʌzbənd/","cn":"n. 丈夫","source":"supplement"},{"en":"steak","ipa":"/steɪk/","cn":"n. 牛排","source":"supplement"},{"en":"mince","ipa":"/mɪns/","cn":"n. 肉馅，绞肉","source":"supplement"},{"en":"chicken","ipa":"/ˈtʃɪkɪn/","cn":"n. 鸡肉；鸡","source":"supplement"},{"en":"either","ipa":"/ˈaɪðə/","cn":"adv. 也（不）（用于否定句）","source":"supplement"},{"en":"cabbage","ipa":"/ˈkæbɪdʒ/","cn":"n. 卷心菜","source":"supplement"}],"patterns":[{"en":"Do you want beef or lamb?","cn":"你要牛肉还是羔羊肉？（选择疑问句）","source":"adaptation"},{"en":"I don't like chicken!","cn":"我不喜欢鸡肉！","source":"adaptation"},{"en":"My husband doesn't like chicken, either.","cn":"我丈夫也不喜欢鸡肉。","source":"adaptation"}],"grammar":"一般现在时否定式用 don't / doesn't + 动词原形；“也不”在否定句句尾用 either，不用 too。","tip":"at the butcher's 中的 's 指“店铺”（肉店）；同样有 at the grocer's 食品店、at the greengrocer's 蔬果店。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you want beef or lamb, Mrs. Bird?","cn":"伯德夫人，您要牛肉还是要羔羊肉？","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Beef, please.","cn":"请给我牛肉。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This lamb's very good.","cn":"这羔羊肉很好。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I like lamb, but my husband doesn't.","cn":"我喜欢羔羊肉，可我丈夫不喜欢。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about some steak? This is a nice piece.","cn":"来点牛排吗？这块很好。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Give me that piece, please.","cn":"就请给我那块吧。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And a pound of mince, too.","cn":"再来一磅绞肉。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want a chicken, Mrs. Bird? They're very nice.","cn":"伯德夫人，您要一只鸡吗？这些鸡很好。","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, thank you. My husband likes steak, but he doesn't like chicken!","cn":"不要了，谢谢。我丈夫喜欢牛排，但他不喜欢鸡！","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"To tell you the truth, Mrs. Bird, I don't like chicken either!","cn":"说实在的，伯德夫人，我也不喜欢鸡！","source":"adaptation","pdfPage":101,"printedPage":97,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"doesn't like 与 either","chat":"说「他喜欢」要加 s：He likes steak. 说「他不喜欢」用 doesn't + 动词原形：He doesn't like chicken.（doesn't 已经替你背了 s，后面的动词变回原形）。「我也不喜欢」在句尾用 either！","formula":"He/She + likes… ／ doesn't like… ｜ 句尾 …, either.（也<不>……）","examples":[{"en":"My husband doesn't like chicken.","cn":"我丈夫不喜欢鸡肉。","source":"supplement"},{"en":"I don't like chicken either!","cn":"我也不喜欢鸡肉！","source":"supplement"},{"en":"Do you want beef or lamb?","cn":"你要牛肉还是羔羊肉？","source":"supplement"}],"watch":"too 用在肯定句尾（I like it too 我也喜欢），either 用在否定句尾（I don't like it either 我也不喜欢）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ he like steak?","opts":["Does","Do","Is","Has"],"a":"Does","why":"这是一般现在时、含实义动词 like 的疑问句；he 是第三人称单数，用 Does，like 保持原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I don't like chicken ___.","opts":["either","too","also","neither"],"a":"either","why":"否定句句尾用 either。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"伯德夫人买了什么？","opts":["牛肉和肉馅","羔羊肉和鸡","鸡和牛排","牛肉和鸡"],"a":"牛肉和肉馅","hint":"Beef, please. And a pound of mince, too.","why":"牛肉 + 一磅肉馅。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"肉贩自己喜欢鸡肉吗？","opts":["不喜欢","喜欢","课文没说","特别喜欢"],"a":"不喜欢","hint":"To tell you the truth, I don't like chicken either!","why":"肉贩说He也不喜欢鸡肉。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":101,"printedPage":97,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":50,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":49},{"id":51,"title":"A pleasant climate","titleCn":"宜人的气候","kind":"text","words":[{"en":"Greece","ipa":"/ɡriːs/","cn":"n. 希腊","source":"supplement"},{"en":"climate","ipa":"/ˈklaɪmət/","cn":"n. 气候","source":"supplement"},{"en":"country","ipa":"/ˈkʌntri/","cn":"n. 国家","source":"supplement"},{"en":"pleasant","ipa":"/ˈpleznt/","cn":"adj. 宜人的","source":"supplement"},{"en":"weather","ipa":"/ˈweðə/","cn":"n. 天气","source":"supplement"},{"en":"spring","ipa":"/sprɪŋ/","cn":"n. 春天","source":"supplement"},{"en":"windy","ipa":"/ˈwɪndi/","cn":"adj. 有风的","source":"supplement"},{"en":"warm","ipa":"/wɔːm/","cn":"adj. 温暖的","source":"supplement"},{"en":"rain","ipa":"/reɪn/","cn":"v. 下雨；n. 雨","source":"supplement"},{"en":"sometimes","ipa":"/ˈsʌmtaɪmz/","cn":"adv. 有时","source":"supplement"}],"patterns":[{"en":"What's the climate like in your country?","cn":"你们国家的气候怎么样？","source":"textbook","pdfPage":105,"printedPage":101,"verification":"verified","translationSource":"supplement"},{"en":"It's often windy in March.","cn":"三月里常常刮风。","source":"textbook","pdfPage":105,"printedPage":101,"verification":"verified","translationSource":"supplement"},{"en":"Does it often rain?","drill":true,"cn":"这儿常下雨吗？","source":"supplement"}],"grammar":"What's ... like? 用来问性质特点；季节、月份前用介词 in（in spring / in March）；rain 和 snow 可作动词：It often rains here.","tip":"climate 指长期的“气候”，weather 指短期的“天气”；聊天气是英语最常用的开场白。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"Where do you come from?","cn":"你是哪国人？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I come from Greece.","cn":"我来自希腊。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What's the climate like in your country?","cn":"你们国家的气候怎么样？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's very pleasant.","cn":"气候非常宜人。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What's the weather like in spring?","cn":"春天的天气怎么样？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's often windy in March. It's always warm in April and May, but it rains sometimes.","cn":"三月里常常刮风。四月和五月天气总是暖洋洋的，但有时下雨。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What's it like in summer?","cn":"夏天的天气如何呢？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's always hot in June, July and August. The sun shines every day.","cn":"六月、七月和八月的天气总是炎热的，每天都出太阳。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Is it cold or warm in autumn?","cn":"秋季的天气是冷还是暖呢？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's always warm in September and October. It's often cold in November and it rains sometimes.","cn":"九月和十月总是很暖和。十一月常常就冷了，而且有时下雨。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Is it very cold in winter?","cn":"冬季的天气很冷吗？","speaker":"HANS","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's often cold in December, January and February. It snows sometimes.","cn":"十二月、一月和二月常常很冷，有时下雪。","speaker":"DIMITRI","source":"textbook","pdfPage":105,"printedPage":101,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"What's the weather like?","chat":"问天气的专用句：What's the weather like?（天气怎么样？）——这里的 like 是「像……样子」，不是「喜欢」！季节、月份前面用 in：in spring、in March。雨和雪还能当动词：It rains. It snows.","formula":"What's the weather like in + 季节/月份? → It's windy / warm / hot.","examples":[{"en":"What's the climate like in your country?","cn":"你们国家气候怎么样？","source":"supplement"},{"en":"It's often windy in March.","cn":"三月常刮风。","source":"supplement"},{"en":"It's always hot in June, July and August.","cn":"六、七、八月总是很热。","source":"supplement"}],"watch":"climate 指一个地方长期的气候特点；weather 指天气情况，可以说今天、某一天，也可以说某个季节的天气，并不只限今天。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"It's often windy ___ March.","opts":["in","on","at","of"],"a":"in","why":"月份前用 in。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"___ it often rain here?","opts":["Does","Do","Is","Are"],"a":"Does","why":"这是一般现在时、含实义动词 rain 的疑问句；it 是第三人称单数，用 Does，rain 保持原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"根据课文，迪米特里（Dimitri）来自哪里？","opts":["希腊","英国","美国","中国"],"a":"希腊","hint":"I come from Greece.","why":"Dimitri 说 I come from Greece.（我来自希腊）。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"根据课文描述，希腊夏天天气如何？","opts":["总是炎热","常常寒冷","常刮大风","总是下雨"],"a":"总是炎热","hint":"It's always hot in June, July and August.","why":"夏天每天出太阳、总是热。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":105,"printedPage":101,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":52,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":51},{"id":53,"title":"An interesting climate","titleCn":"有趣的气候","kind":"text","words":[{"en":"England","ipa":"/ˈɪŋɡlənd/","cn":"n. 英格兰，（泛指）英国","source":"supplement"},{"en":"mild","ipa":"/maɪld/","cn":"adj. 温和的","source":"supplement"},{"en":"always","ipa":"/ˈɔːlweɪz/","cn":"adv. 总是","source":"supplement"},{"en":"north","ipa":"/nɔːθ/","cn":"n. 北方","source":"supplement"},{"en":"east","ipa":"/iːst/","cn":"n. 东方","source":"supplement"},{"en":"south","ipa":"/saʊθ/","cn":"n. 南方","source":"supplement"},{"en":"west","ipa":"/west/","cn":"n. 西方","source":"supplement"},{"en":"season","ipa":"/ˈsiːzn/","cn":"n. 季节","source":"supplement"},{"en":"best","ipa":"/best/","cn":"adv. 最好地；adj. 最好的","source":"supplement"},{"en":"night","ipa":"/naɪt/","cn":"n. 夜晚","source":"supplement"}],"patterns":[{"en":"It's mild, but it's not always pleasant.","cn":"气候温和，但不总是宜人。","source":"adaptation"},{"en":"The weather's often cold in the North and windy in the East.","cn":"北部天气常常寒冷，东部则常常刮风。","source":"adaptation"},{"en":"It's our favourite subject of conversation.","cn":"它是我们最喜欢谈论的话题。","source":"adaptation"}],"grammar":"方位名词前加 the：in the North / in the East；favourite 本身就含“最”的意味，不用再加 most。","tip":"谈论天气的万能句：What's the weather like today?；四方位 north/east/south/west 成对记。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Where do you come from?","cn":"你是哪国人？","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I come from England.","cn":"我来自英国。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the climate like in your country?","cn":"你们国家的气候怎么样？","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's mild, but it's not always pleasant.","cn":"气候温和，但也不总是宜人的。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the weather like in summer?","cn":"夏季的天气怎么样？","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's often cold in the North and windy in the East. It's often wet in the West and sometimes warm in the South.","cn":"北部常冷，东部常刮风。西部常下雨，南部有时则很暖和。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Which seasons do you like best?","cn":"你最喜欢哪些季节？","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I like spring and summer. The days are long and the nights are short. The sun rises early and sets late.","cn":"我喜欢春季和夏季。此时白天长而夜晚短，太阳升得早而落得晚。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I don't like autumn and winter. The days are short and the nights are long. The sun rises late and sets early.","cn":"我不喜欢秋季和冬季。此时白天短而夜晚长，太阳升得迟而落得早。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Our climate is not very good, but it's interesting. It's our favourite subject of conversation.","cn":"我们的气候不是很好，但很有意思。它是我最喜欢谈论的话题。","source":"adaptation","pdfPage":109,"printedPage":105,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"方位与 favourite","chat":"说一个国家的方位要加 the：in the North（在北方）、in the East（在东方）。说「最喜欢的」用 favourite，它天生带着「最」字，前面不能再加 most！","formula":"in the North / East / South / West ｜ favourite + 名词 = 最喜欢的……","examples":[{"en":"It's often cold in the North.","cn":"北方常常很冷。","source":"supplement"},{"en":"I like spring and summer best.","cn":"我最喜欢春天和夏天。","source":"supplement"},{"en":"It's our favourite subject of conversation.","cn":"这是我们最爱聊的话题。","source":"supplement"}],"watch":"favourite = 最喜欢的：不说 most favourite，「最」已经包含在里面了！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"It's often cold in ___ North.","opts":["the","不填","a","an"],"a":"the","why":"方位名词前要加 the。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The sun rises ___ and sets late.","opts":["early","late","slowly","well"],"a":"early","why":"升得早落得晚 = 白天长。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"说话人最喜欢哪几个季节？","opts":["春季和夏季","秋季和冬季","三月和四月","六月和七月"],"a":"春季和夏季","hint":"I like spring and summer.","why":"因为白天长、夜晚短。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"英国的气候怎么样？","opts":["温和但不总是宜人","非常糟糕","总是寒冷","总是炎热"],"a":"温和但不总是宜人","hint":"It's mild, but it's not always pleasant.","why":"mild 温和。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":109,"printedPage":105,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":54,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":53},{"id":55,"title":"The Sawyer family","titleCn":"索耶一家人","kind":"text","words":[{"en":"live","ipa":"/lɪv/","cn":"v. 住，居住","source":"supplement"},{"en":"stay","ipa":"/steɪ/","cn":"v. 呆在，停留","source":"supplement"},{"en":"home","ipa":"/həʊm/","cn":"n. 家；adv. 在家","source":"supplement"},{"en":"housework","ipa":"/ˈhaʊswɜːk/","cn":"n. 家务","source":"supplement"},{"en":"lunch","ipa":"/lʌntʃ/","cn":"n. 午饭","source":"supplement"},{"en":"usually","ipa":"/ˈjuːʒʊəli/","cn":"adv. 通常","source":"supplement"},{"en":"together","ipa":"/təˈɡeðə/","cn":"adv. 一起","source":"supplement"},{"en":"evening","ipa":"/ˈiːvnɪŋ/","cn":"n. 傍晚，晚上","source":"supplement"},{"en":"arrive","ipa":"/əˈraɪv/","cn":"v. 到达","source":"supplement"},{"en":"late","ipa":"/leɪt/","cn":"adv. 晚地；adj. 迟的","source":"supplement"}],"patterns":[{"en":"The Sawyers live at 87 King Street.","cn":"索耶一家住在国王街87号。","source":"adaptation"},{"en":"She stays at home every day.","cn":"她每天呆在家里。","source":"adaptation"},{"en":"Mr. Sawyer arrives home late.","cn":"索耶先生到家很晚。","source":"adaptation"}],"grammar":"一般现在时表示习惯性动作，含实义动词的肯定句中，第三人称单数动词通常加 -s/-es（goes, does, watches）；always/usually/often 通常放在实义动词前、be 动词后。","tip":"arrive home 到家（home 是副词，前面不加 to）；go to bed 上床睡觉，go to sleep 入睡。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"The Sawyers live at 87 King Street.","cn":"索耶一家住在国王街87号。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"In the morning, Mr. Sawyer goes to work and the children go to school.","cn":"早上，索耶先生去上班，孩子们去上学。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Their father takes them to school every day.","cn":"父亲每天送孩子们去上学。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mrs. Sawyer stays at home every day.","cn":"索耶太太每天呆在家里。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She does the housework.","cn":"她操持家务。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She always eats her lunch at noon.","cn":"她总是在正午吃午饭。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"In the afternoon, she usually sees her friends.","cn":"下午，她通常会见朋友。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They often drink tea together.","cn":"她们经常在一起喝茶。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"In the evening, the children come home from school.","cn":"傍晚，孩子们放学回家。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They arrive home early.","cn":"他们到家很早。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mr. Sawyer comes home from work.","cn":"索耶先生下班回家。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He arrives home late.","cn":"他到家很晚。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"At night, the children always do their homework.","cn":"晚上，孩子们总是做作业。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then they go to bed.","cn":"然后他们去睡觉。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mr. Sawyer usually reads his newspaper, but sometimes he and his wife watch television.","cn":"索耶先生通常在晚上看报，但有时他和妻子一起看电视。","source":"adaptation","pdfPage":113,"printedPage":109,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"一般现在时与动词的 s","chat":"讲每天的习惯动作，用一般现在时。含实义动词的肯定句中，主语是 he/she/it 等第三人称单数时，动词通常加 s 或 es：goes、does、watches、stays。always（总是）、usually（通常）、often（经常）通常放在实义动词前、be 动词后。","formula":"He/She + 实义动词s/es + 时间. ｜ always/usually/often 通常在实义动词前、be 动词后","examples":[{"en":"Mr. Sawyer goes to work early.","cn":"索耶先生早早去上班。","source":"supplement"},{"en":"She always eats her lunch at noon.","cn":"她总在正午吃午饭。","source":"supplement"},{"en":"They often drink tea together.","cn":"他们经常一起喝茶。","source":"supplement"}],"watch":"三单动词忘加 s 是小学生第一大扣分点：he like ❌ → he likes ✓！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Mr. Sawyer ___ to work every day.","opts":["goes","go","going","gos"],"a":"goes","why":"三单动词加 es：go→goes。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"She always ___ her lunch at noon.","opts":["eats","eat","eating","ate"],"a":"eats","why":"She 是第三人称单数。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"索耶一家住在哪儿？","opts":["国王街87号","大桥街83号","特拉法加广场","乡下"],"a":"国王街87号","hint":"The Sawyers live at 87 King Street.","why":"87 King Street。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"索耶先生到家早还是晚？","opts":["晚","早","正午","半夜"],"a":"晚","hint":"He arrives home late.","why":"孩子们到得早，爸爸到得晚。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":113,"printedPage":109,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":56,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":55},{"id":57,"title":"An unusual day","titleCn":"不平常的一天","kind":"text","words":[{"en":"unusual","ipa":"/ʌnˈjuːʒʊəl/","cn":"adj. 不平常的","source":"supplement"},{"en":"o'clock","ipa":"/əˈklɒk/","cn":"adv. ……点钟","source":"supplement"},{"en":"shop","ipa":"/ʃɒp/","cn":"n. 商店","source":"supplement"},{"en":"moment","ipa":"/ˈməʊmənt/","cn":"n. 时刻（at the moment 此刻）","source":"supplement"},{"en":"foot","ipa":"/fʊt/","cn":"n. 脚（on foot 步行）","source":"supplement"},{"en":"by","ipa":"/baɪ/","cn":"prep. 乘（交通工具）","source":"supplement"},{"en":"read","ipa":"/riːd/","cn":"v. 读","source":"supplement"},{"en":"interesting","ipa":"/ˈɪntrəstɪŋ/","cn":"adj. 有趣的","source":"supplement"}],"patterns":[{"en":"The children go to school by car every day.","cn":"孩子们每天都乘小汽车上学。","source":"adaptation"},{"en":"But this morning, they are going to school on foot.","cn":"可今天早上，他们正步行去上学。","source":"adaptation"},{"en":"It is eight o'clock.","cn":"现在是八点钟。","source":"adaptation"}],"grammar":"一般现在时（every day，习惯）与现在进行时（this morning，此刻）对比使用；by car 乘车，on foot 步行。","tip":"o'clock 只能跟在整点后面：eight o'clock；几点半说 half past eight。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"It is eight o'clock.","cn":"现在是8点钟。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The children go to school by car every day, but this morning, they are going to school on foot.","cn":"孩子们每天都乘小汽车去上学，而今天早上，他们正步行去上学。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is ten o'clock.","cn":"现在是10点钟。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mrs. Sawyer usually stays at home in the morning, but this morning, she is going to the shops.","cn":"上午，索耶太太通常呆在家里，但今天上午，她正去商店买东西。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is four o'clock.","cn":"现在是4点钟。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"In the afternoon, Mrs. Sawyer usually drinks tea in the living room, but this afternoon, she is drinking tea in the garden.","cn":"下午，索耶太太通常在客厅里喝茶，但今天下午，她正在花园里喝茶。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is six o'clock.","cn":"现在是6点钟。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"In the evening, the children usually do their homework, but this evening, they are not doing their homework.","cn":"晚上，孩子们通常是做作业，而今天晚上，他们没做作业。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"At the moment, they are playing in the garden.","cn":"此刻，他们正在花园里玩。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It is nine o'clock.","cn":"现在是9点钟。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Mr. Sawyer usually reads his newspaper at night, but he's not reading his newspaper tonight.","cn":"索耶先生通常在晚上看报，但今天晚上他没看报。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"At the moment, he's reading an interesting book.","cn":"此刻，他正在看一本有趣的书。","source":"adaptation","pdfPage":117,"printedPage":113,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"两种时态同台对比","chat":"这课把两种时态放在一起对比：every day（每天，习惯）用一般现在时；this morning / at the moment（此刻）用现在进行时。整点时间用 o'clock：eight o'clock 八点整。","formula":"every day → 一般现在时 ｜ this morning / at the moment → be + 动词ing","examples":[{"en":"The children go to school by car every day.","cn":"孩子们每天乘车上学。","source":"supplement"},{"en":"This morning, they are going to school on foot.","cn":"今天早上他们正步行去上学。","source":"supplement"},{"en":"At the moment, he's reading an interesting book.","cn":"此刻，他正在读一本有趣的书。","source":"supplement"}],"watch":"乘交通工具用 by：by car / by bus；只有走路用 on：on foot 步行！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"The children go to school ___ car.","opts":["by","on","with","in"],"a":"by","why":"乘交通工具用 by。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"This morning they are going ___.","opts":["on foot","by foot","by feet","with foot"],"a":"on foot","why":"步行是固定说法 on foot。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"今天早上孩子们怎么去上学？","opts":["步行","乘小汽车","坐公交","骑车"],"a":"步行","hint":"this morning, they are going to school on foot.","why":"平常乘车，今天步行。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"索耶先生今晚在做什么？","opts":["读一本有趣的书","看报纸","看电视","洗澡"],"a":"读一本有趣的书","hint":"he's reading an interesting book.","why":"平时看报，今晚看书。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":117,"printedPage":113,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":58,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":57},{"id":59,"title":"Is that all?","titleCn":"就这些吗？","kind":"text","words":[{"en":"envelope","ipa":"/ˈenvələʊp/","cn":"n. 信封","source":"supplement"},{"en":"writing paper","ipa":"/ˈraɪtɪŋ ˈpeɪpə/","cn":"n. 信纸","source":"supplement"},{"en":"size","ipa":"/saɪz/","cn":"n. 尺寸，尺码","source":"supplement"},{"en":"pad","ipa":"/pæd/","cn":"n. 信纸簿，便笺本","source":"supplement"},{"en":"glue","ipa":"/ɡluː/","cn":"n. 胶水","source":"supplement"},{"en":"chalk","ipa":"/tʃɔːk/","cn":"n. 粉笔","source":"supplement"},{"en":"change","ipa":"/tʃeɪndʒ/","cn":"n. 零钱；v. 改变","source":"supplement"},{"en":"large","ipa":"/lɑːdʒ/","cn":"adj. 大的","source":"supplement"},{"en":"small","ipa":"/smɔːl/","cn":"adj. 小的","source":"supplement"},{"en":"all","ipa":"/ɔːl/","cn":"pron. 全部","source":"supplement"}],"patterns":[{"en":"I want some envelopes, please.","cn":"我要买些信封。","source":"adaptation"},{"en":"Do you want the large size or the small size?","cn":"您要大号的还是小号的？","source":"adaptation"},{"en":"Is that all?","cn":"就这些吗？","source":"adaptation"}],"grammar":"表示“一些”时，肯定句通常用 some，普通疑问句和否定句通常用 any：I want some... / Do you want any...?；请求、邀请或期待肯定回答的问句也可以用 some。I don’t have any small pads. 表示没有小号便笺本。","tip":"购物收尾必用：That's all, thank you.（就这些，谢谢）；Are they? 这类简短反问可承接对话。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"I want some envelopes, please.","cn":"请给我拿几个信封。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want the large size or the small size?","cn":"您要大号的还是要小号的？","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The large size, please. And do you have any writing paper?","cn":"请拿大号的。你们有信纸吗？","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, we do. I don't have any small pads. I only have large ones. Do you want a pad?","cn":"有。我没有小本的信纸簿，只有大本的。您要一本吗？","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please. And I want a bottle of glue.","cn":"好的，麻烦你。我还要一瓶胶水。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"A bottle of glue.","cn":"一瓶胶水。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And I want a large box of chalk, too.","cn":"我还要一大盒粉笔。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I only have small boxes. Do you want one?","cn":"我只有小盒的。您要一盒吗？","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, thank you.","cn":"不了，谢谢。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is that all?","cn":"就这些吗？","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's all, thank you.","cn":"就这些，谢谢。","source":"adaptation","pdfPage":121,"printedPage":117,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"购物：I want some…","chat":"买东西时说要什么：I want some envelopes, please.（请给我些信封）。店员问规格：the large size or the small size?（大的还是小的？）——or 连接的叫「选择疑问句」。买完说 That's all, thank you.","formula":"I want some…, please. ｜ A or B? （选哪个？）","examples":[{"en":"I want some envelopes, please.","cn":"我要买些信封。","source":"supplement"},{"en":"Do you want the large size or the small size?","cn":"您要大号的还是小号的？","source":"supplement"},{"en":"Is that all?","cn":"就这些吗？","source":"supplement"}],"watch":"选择疑问句不用 Yes/No 回答，直接选一个：The large size, please.！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I want ___ envelopes, please.","opts":["some","any","a","an"],"a":"some","why":"肯定句用 some。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Do you want the large size ___ the small size?","opts":["or","and","but","so"],"a":"or","why":"选择疑问句用 or。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"女士要的信封是什么规格？","opts":["大号","小号","两种都要","不要"],"a":"大号","hint":"The large size, please.","why":"选了大号。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"大盒粉笔她买到了吗？","opts":["没有，只有小盒","买到了","店里没粉笔","买了两盒"],"a":"没有，只有小盒","hint":"I only have small boxes.","why":"她回答 No, thank you.，所以小盒粉笔她没有买。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":121,"printedPage":117,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":60,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":59},{"id":61,"title":"A bad cold","titleCn":"重感冒","kind":"text","words":[{"en":"feel","ipa":"/fiːl/","cn":"v. 感觉","source":"supplement"},{"en":"look","ipa":"/lʊk/","cn":"v. 看起来（系动词）","source":"supplement"},{"en":"call","ipa":"/kɔːl/","cn":"v. 叫，请（医生）；打电话","source":"supplement"},{"en":"doctor","ipa":"/ˈdɒktə/","cn":"n. 医生","source":"supplement"},{"en":"telephone","ipa":"/ˈtelɪfəʊn/","cn":"v. 打电话；n. 电话","source":"supplement"},{"en":"remember","ipa":"/rɪˈmembə/","cn":"v. 记得，想起","source":"supplement"},{"en":"cold","ipa":"/kəʊld/","cn":"n. 感冒；adj. 冷的","source":"supplement"},{"en":"mouth","ipa":"/maʊθ/","cn":"n. 嘴","source":"supplement"},{"en":"tongue","ipa":"/tʌŋ/","cn":"n. 舌头","source":"supplement"},{"en":"news","ipa":"/njuːz/","cn":"n. 消息（不可数）","source":"supplement"}],"patterns":[{"en":"He feels ill.","cn":"他觉得不舒服。（feel 系动词）","source":"adaptation"},{"en":"We must call the doctor.","cn":"我们得去请医生。","source":"adaptation"},{"en":"He has a bad cold.","cn":"他得了重感冒。","source":"adaptation"}],"grammar":"feel / look 是系动词，后面接形容词：feel ill, look well；have a cold 感冒是固定搭配。","tip":"感冒了说 I have a cold.，重感冒 a bad cold；听到好消息说 That's good news（news 不可数，不加 s）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Where's Jimmy?","cn":"吉米在哪儿？","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's in bed.","cn":"他躺在床上。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the matter with him?","cn":"他怎么啦？","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He feels ill. He looks ill.","cn":"他觉得不舒服。他看上去也确实病了。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We must call the doctor.","cn":"我们得去请医生。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, we must.","cn":"是的，一定得请。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you remember the doctor's telephone number?","cn":"你还记得医生的电话号码吗？","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes. It's 09754.","cn":"记得，是09754。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Open your mouth, Jimmy. Show me your tongue. Say, “Ah”.","cn":"吉米，张开嘴，让我看看你的舌头。说“啊”。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He has a bad cold, Mr. Williams, so he must stay in bed for a week.","cn":"威廉斯先生，他得了重感冒，因此他必须卧床一周。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's good news for Jimmy.","cn":"对吉米来说，这可是个好消息。","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Good news? Why?","cn":"好消息？为什么？","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Because he doesn't like school!","cn":"因为他不喜欢上学！","source":"adaptation","pdfPage":125,"printedPage":121,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"系动词：feel 和 look","chat":"feel（感觉起来）和 look（看起来）是「系动词」，像小桥一样连接主语和形容词：He feels ill.（他觉得病了）He looks ill.（他看上去病了）。「感冒」是固定搭配 have a cold。","formula":"主语 + feel/look + 形容词 ｜ have a cold 感冒","examples":[{"en":"He feels ill. He looks ill.","cn":"他觉得不舒服，看上去也病了。","source":"supplement"},{"en":"We must call the doctor.","cn":"我们得请医生。","source":"supplement"},{"en":"He has a bad cold.","cn":"他得了重感冒。","source":"supplement"}],"watch":"系动词后面跟形容词，不跟副词：look well ✓（well 这里是「健康的」这个形容词）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"He ___ ill.","opts":["feels","feel","feel to","is feel"],"a":"feels","why":"三单 feels；feel 是系动词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"We must ___ the doctor.","opts":["call","calls","calling","called"],"a":"call","why":"must 后面跟动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"吉米怎么了？","opts":["重感冒","牙疼","摔伤了背","发烧"],"a":"重感冒","hint":"He has a bad cold.","why":"重感冒，要卧床一周。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"为什么说这对吉米是好消息？","opts":["因为他不喜欢上学","因为他喜欢医生","因为他能看电视","因为他有礼物"],"a":"因为他不喜欢上学","hint":"Because he doesn't like school!","why":"不用上学啦，当然是好消息！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":125,"printedPage":121,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":62,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":61},{"id":63,"title":"Thank you, doctor.","titleCn":"谢谢你，医生。","kind":"text","words":[{"en":"better","ipa":"/ˈbetə/","cn":"adj. 好些了（well 的比较级）","source":"supplement"},{"en":"certainly","ipa":"/ˈsɜːtnli/","cn":"adv. 当然","source":"supplement"},{"en":"get up","ipa":"/ɡet ʌp/","cn":"phr. 起床","source":"supplement"},{"en":"yet","ipa":"/jet/","cn":"adv. 还（用于否定句和疑问句）","source":"supplement"},{"en":"rich","ipa":"/rɪtʃ/","cn":"adj. 油腻的；富有的","source":"supplement"},{"en":"food","ipa":"/fuːd/","cn":"n. 食物","source":"supplement"},{"en":"play","ipa":"/pleɪ/","cn":"v. 玩，踢（球）","source":"supplement"},{"en":"match","ipa":"/mætʃ/","cn":"n. 比赛","source":"supplement"},{"en":"talk","ipa":"/tɔːk/","cn":"v. 谈话","source":"supplement"}],"patterns":[{"en":"How's Jimmy today?","cn":"吉米今天怎么样了？","source":"adaptation"},{"en":"Must he stay in bed?","cn":"他还必须卧床吗？","source":"adaptation"},{"en":"He mustn't get up yet.","cn":"他还不该起床。","source":"adaptation"}],"grammar":"mustn't 表示“禁止、千万别”，与 must（必须）对应；表示“不必”要用 needn't。","tip":"better 是 well（身体好）的比较级：I'm better now. 我现在好些了。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"How's Jimmy today?","cn":"吉米今天怎么样了？","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Better. Thank you, doctor.","cn":"好些了。谢谢您，医生。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can I see him please, Mrs. Williams?","cn":"威廉斯太太，我可以看看他吗？","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Certainly, doctor. Come upstairs.","cn":"当然可以，医生。上楼看看吧。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"You look very well, Jimmy. You look better now, but you mustn't get up yet. You must stay in bed for another two days.","cn":"吉米，你看上去很好。你现在好些了，但你还不应该起床。你必须再卧床两天。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The boy mustn't go to school yet, Mrs. Williams. And he mustn't eat rich food.","cn":"这孩子还不能去上学，威廉斯太太，而且他不能吃油腻的食物。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Has he a temperature, doctor?","cn":"医生，他发烧吗？","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, he hasn't.","cn":"不，他不发烧。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Must he stay in bed?","cn":"他还必须卧床吗？","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes. He must remain in bed for another two days. He can get up for about two hours each day, but you must keep the room warm.","cn":"是的，他还必须卧床两天。他每天可以起来两个小时左右，但您必须保持房间温暖。","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Where's Mr. Williams this evening?","cn":"威廉斯先生今晚在哪儿？","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's in bed, doctor. Can you see him please? He has a bad cold, too!","cn":"他在床上呢，医生。您能去看看他吗？他也得了重感冒！","source":"adaptation","pdfPage":129,"printedPage":125,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"mustn't 不是「不必」！","chat":"must 表示「必须」。它的否定 mustn't 不是「不必」，而是「禁止、千万不要」！真正的「不必」是 needn't。这对孪生兄弟是考试最爱，千万别认错！","formula":"must = 必须 ｜ mustn't = 千万不要 ｜ needn't = 不必","examples":[{"en":"He mustn't get up yet.","cn":"他还不该起床。","source":"supplement"},{"en":"He mustn't eat rich food.","cn":"他不能吃油腻的食物。","source":"supplement"},{"en":"He must stay in bed for another two days.","cn":"他必须再卧床两天。","source":"supplement"}],"watch":"Must I…? 的否定回答是 No, you needn't.（你不必），说 No, you mustn't. 就变成「禁止」啦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"He ___ get up yet.","opts":["mustn't","needn't","don't","doesn't"],"a":"mustn't","why":"「还不许起床」用 mustn't。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"He can get up ___ two hours each day.","opts":["for","since","at","on"],"a":"for","why":"for + 一段时间。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"吉米今天怎么样？","opts":["好些了","更糟了","还是病重","完全好了"],"a":"好些了","hint":"Better. Thank you, doctor.","why":"better = 好些了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"威廉斯先生今晚在哪儿？","opts":["躺在床上","上班","在花园","在看医生"],"a":"躺在床上","hint":"He's in bed, doctor. He has a bad cold, too!","why":"他也得了重感冒——课文的大笑话！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":129,"printedPage":125,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":64,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":63},{"id":65,"title":"Not a baby","titleCn":"不是小孩子","kind":"text","words":[{"en":"key","ipa":"/kiː/","cn":"n. 钥匙","source":"supplement"},{"en":"baby","ipa":"/ˈbeɪbi/","cn":"n. 婴儿","source":"supplement"},{"en":"hear","ipa":"/hɪə/","cn":"v. 听见","source":"supplement"},{"en":"fun","ipa":"/fʌn/","cn":"n. 乐趣，有趣的事","source":"supplement"},{"en":"enjoy","ipa":"/ɪnˈdʒɔɪ/","cn":"v. 玩得快活","source":"supplement"},{"en":"yourself","ipa":"/jɔːˈself/","cn":"pron. 你自己（反身代词）","source":"supplement"},{"en":"ourselves","ipa":"/ˌaʊəˈselvz/","cn":"pron. 我们自己（反身代词）","source":"supplement"},{"en":"half","ipa":"/hɑːf/","cn":"n. 一半（half past ten 十点半）","source":"supplement"},{"en":"past","ipa":"/pɑːst/","cn":"prep. 过（几点）","source":"supplement"}],"patterns":[{"en":"Can I have the key to the front door, Dad?","cn":"爸爸，我能拿前门的钥匙吗？","source":"adaptation"},{"en":"You mustn't come home late.","cn":"你不许回来太晚。","source":"adaptation"},{"en":"Enjoy yourself!","cn":"玩得开心！","source":"adaptation"}],"grammar":"反身代词 yourself / ourselves；enjoy oneself = 玩得开心；时刻表达：half past ten 十点半，a quarter past ten 十点一刻。","tip":"key to the front door 用 to 不用 of；have fun = enjoy oneself = have a good time。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"What are you going to do this evening, Jill?","cn":"今晚你打算做什么，吉尔？","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm going to meet some friends, Dad.","cn":"我打算去看几个朋友，爸爸。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"You mustn't come home late. You must be home at half past ten.","cn":"你不许回来太晚，你必须在十点半到家。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I can't get home so early, Dad! Can I have the key to the front door, please?","cn":"可我到家不会那么早，爸爸！请把前门的钥匙给我行吗？","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, you can't.","cn":"不行，不能给你。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Jill's eighteen years old, Tom. She's not a baby. Give her the key. She always comes home early.","cn":"吉尔都18岁了，汤姆，她不是小孩子了。把钥匙给她吧，她总是早早地回家的。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Oh, all right!","cn":"哦，那好吧！","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are. But you mustn't come home after a quarter past eleven. Do you hear?","cn":"给你。但你不许超过十一点一刻才回家，听见了吗？","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, Dad. Thanks, Mum.","cn":"听见了，爸爸。谢谢妈妈。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's all right. Goodbye. Enjoy yourself!","cn":"不用谢。再见吧，好好玩！","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We always enjoy ourselves, Mum. Bye-bye.","cn":"我们总是玩得很开心的，妈妈。再见。","source":"adaptation","pdfPage":133,"printedPage":129,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"反身代词与 half past","chat":"自己「玩得开心」是 enjoy oneself—— oneself 就是反身代词：yourself（你自己）、ourselves（我们自己）。说「几点半」用 half past + 数字：half past ten 十点半。","formula":"enjoy oneself = 玩得开心 ｜ half past + 数字 = ……点半","examples":[{"en":"Enjoy yourself!","cn":"玩得开心！","source":"supplement"},{"en":"We always enjoy ourselves.","cn":"我们总是玩得很开心。","source":"supplement"},{"en":"You must be home at half past ten.","cn":"你必须十点半到家。","source":"supplement"}],"watch":"门钥匙说 the key to the door——用 to 表示「配套的」，不用 of！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Enjoy ___!","opts":["yourself","yours","herself","themselves"],"a":"yourself","why":"对吉尔一个人说，用 yourself。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"You must be home ___ half past ten.","opts":["at","in","on","by"],"a":"at","why":"几点几分前用 at。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"吉尔多少岁了？","opts":["18岁","8岁","80岁","10岁"],"a":"18岁","hint":"Jill's eighteen years old.","why":"所以妈妈说她不是小孩子了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"吉尔向爸爸要什么？","opts":["前门的钥匙","一条新裙子","生日蛋糕","零花钱"],"a":"前门的钥匙","hint":"Can I have the key to the front door?","why":"晚归要开门，所以想要钥匙。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":133,"printedPage":129,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":66,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":65},{"id":67,"title":"The weekend","titleCn":"周末","kind":"text","words":[{"en":"absent","ipa":"/ˈæbsənt/","cn":"adj. 缺席的","source":"supplement"},{"en":"Monday","ipa":"/ˈmʌndi/","cn":"n. 星期一","source":"supplement"},{"en":"Tuesday","ipa":"/ˈtjuːzdi/","cn":"n. 星期二","source":"supplement"},{"en":"Wednesday","ipa":"/ˈwenzdi/","cn":"n. 星期三","source":"supplement"},{"en":"Friday","ipa":"/ˈfraɪdi/","cn":"n. 星期五","source":"supplement"},{"en":"Saturday","ipa":"/ˈsætədi/","cn":"n. 星期六","source":"supplement"},{"en":"Sunday","ipa":"/ˈsʌndi/","cn":"n. 星期日","source":"supplement"},{"en":"weekend","ipa":"/ˌwiːkˈend/","cn":"n. 周末","source":"supplement"},{"en":"keep","ipa":"/kiːp/","cn":"v. 保持","source":"supplement"},{"en":"spend","ipa":"/spend/","cn":"v. 度过；花费","source":"supplement"}],"patterns":[{"en":"Were you at the butcher's last Monday?","cn":"上星期一你去过肉店吗？","source":"adaptation"},{"en":"He was absent on Monday.","cn":"他星期一没来（缺席）。","source":"adaptation"},{"en":"How are you all keeping?","cn":"你们身体都好吗？","source":"adaptation"}],"grammar":"be 的过去式：was（单数）/ were（复数）；在具体某天用介词 on（on Monday）；last week 上周。","tip":"“在周末”英式说 at the weekend，美式说 on the weekend；spend the weekend 度周末。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Hello. Were you at the butcher's?","cn":"你好。刚才你在肉店里吗？","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I was. Were you at the butcher's, too?","cn":"是的，我在。你也在肉店里吗？","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, I wasn't. I was at the greengrocer's. How's Jimmy today?","cn":"不，我不在。我在蔬菜水果店里。吉米今天怎么样？","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's very well, thank you.","cn":"他很好，谢谢。","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Was he absent from school last week?","cn":"上星期他没上学吧？","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, he was. He was absent on Monday, Tuesday, Wednesday and Thursday. How are you all keeping?","cn":"是的，他没上学。他星期一、星期二、星期三和星期四都没去上学。你们身体都好吗？","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Very well, thank you. We're going to spend three days in the country. We're going to stay at my mother's for the weekend.","cn":"都很好，谢谢。我们打算到乡下去三天，在我母亲家过周末。","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Friday, Saturday and Sunday in the country! Aren't you lucky!","cn":"星期五、星期六和星期日在乡下过！你们真幸运啊！","source":"adaptation","pdfPage":137,"printedPage":133,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"be 动词的过去式：was / were","chat":"说「过去」的事，be 动词要换衣服：am/is → was，are → were。星期几前面用 on：on Monday（在星期一）。看到 last week（上周）、yesterday（昨天），就要想到过去式！","formula":"I/he/she → was ｜ you/we/they → were ｜ on + 星期几","examples":[{"en":"Were you at the butcher's?","cn":"你刚才在肉店吗？","source":"supplement"},{"en":"He was absent on Monday.","cn":"他星期一缺席了。","source":"supplement"},{"en":"We're going to stay at my mother's for the weekend.","cn":"我们要去我妈妈家过周末。","source":"supplement"}],"watch":"my mother's 后面省略了 house：'s 也能代替「某人的家」哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ you at the butcher's?","opts":["Were","Was","Are","Is"],"a":"Were","why":"you 配 were。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"He was absent ___ Monday.","opts":["on","in","at","for"],"a":"on","why":"星期几前面用 on。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"第二个人刚才在哪儿？","opts":["蔬菜水果店","肉店","家里","学校"],"a":"蔬菜水果店","hint":"No, I wasn't. I was at the greengrocer's.","why":"第一位在肉店，第二位在蔬果店。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"他们打算在乡下待几天？","opts":["3天","一周","1天","一个月"],"a":"3天","hint":"We're going to spend three days in the country.","why":"周五、六、日三天。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":137,"printedPage":133,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":68,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":67},{"id":69,"title":"The car race","titleCn":"汽车比赛","kind":"text","words":[{"en":"race","ipa":"/reɪs/","cn":"n. 比赛，竞赛","source":"supplement"},{"en":"town","ipa":"/taʊn/","cn":"n. 城镇","source":"supplement"},{"en":"crowd","ipa":"/kraʊd/","cn":"n. 人群","source":"supplement"},{"en":"stand","ipa":"/stænd/","cn":"v. 站立；n. 看台","source":"supplement"},{"en":"exciting","ipa":"/ɪkˈsaɪtɪŋ/","cn":"adj. 激动人心的","source":"supplement"},{"en":"handsome","ipa":"/ˈhænsəm/","cn":"adj. 漂亮的（男子）","source":"supplement"},{"en":"finish","ipa":"/ˈfɪnɪʃ/","cn":"n. 结尾，终点；v. 完成","source":"supplement"},{"en":"winner","ipa":"/ˈwɪnə/","cn":"n. 获胜者","source":"supplement"},{"en":"hundred","ipa":"/ˈhʌndrəd/","cn":"num. 百","source":"supplement"},{"en":"year","ipa":"/jɪə/","cn":"n. 年","source":"supplement"}],"patterns":[{"en":"In 1995, there was a very big race.","cn":"1995年举行了一次盛大的比赛。","source":"textbook","pdfPage":141,"printedPage":137,"verification":"verified","translationSource":"supplement"},{"en":"There were hundreds of people there.","cn":"那里有成百上千的人。","source":"textbook","pdfPage":141,"printedPage":137,"verification":"verified","translationSource":"supplement"},{"en":"The winner was Billy Stewart.","cn":"获胜者是比利·斯图尔特。","source":"textbook","pdfPage":141,"printedPage":137,"verification":"verified","translationSource":"supplement"}],"grammar":"there was / there were 是 there is / there are 的过去式；hundreds of 表示“成百上千”（不确指数字时用复数 + of）。","tip":"exciting 形容事物“令人激动”，excited 形容人“感到激动”——Lesson 141 还会遇到。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"There is a car race near our town every year.","cn":"我们镇子附近每年都有一场汽车比赛。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"In 1995, there was a very big race.","cn":"1995年举行了一次盛大的比赛。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"There were hundreds of people there.","cn":"那里有成百上千的人。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My wife and I were at the race. Our friends Julie and Jack were there, too.","cn":"我和我妻子也去了赛场，我们的朋友朱莉和杰克也去了。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"You can see us in the crowd. We are standing on the left.","cn":"你可以在人群中看到我们。我们站在照片的左边。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"There were twenty cars in the race. There were English cars, French cars, German cars, Italian cars, American cars and Japanese cars.","cn":"参加比赛的有20辆汽车，有英国、法国、德国、意大利、美国和日本的汽车。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It was an exciting finish. The winner was Billy Stewart.","cn":"比赛的结尾是激动人心的，获胜者是比利·斯图尔特。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He was in car number fifteen. Five other cars were just behind him.","cn":"他在第15号车里，其他5辆汽车紧随其后。","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"On the way home, my wife said to me, “Don't drive so quickly! You're not Billy Stewart!”","cn":"回家的路上，妻子对我说：“别开这么快！你可不是比利·斯图尔特！”","source":"textbook","pdfPage":141,"printedPage":137,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"there was / there were","chat":"过去「存在有」，There is/are 也要换过去式：There was（过去有一个）、There were（过去有一些）。hundred 前有具体数字不加 s：five hundred；不确指时才说 hundreds of（成百上千）。","formula":"There was + 单数 ／ There were + 复数（过去有……）","examples":[{"en":"There was a very big race in 1995.","cn":"1995年有一场盛大的比赛。","source":"supplement"},{"en":"There were hundreds of people there.","cn":"那里有成百上千的人。","source":"supplement"},{"en":"There were twenty cars in the race.","cn":"比赛有20辆车。","source":"supplement"}],"watch":"exciting 形容事物「令人激动」：an exciting finish 激动人心的结尾！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"In 1995, there ___ hundreds of people there.","opts":["were","was","is","are"],"a":"were","why":"In 1995 指过去；people 是复数，所以用 were。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"In 1995, the winner ___ Billy Stewart.","opts":["was","were","is","are"],"a":"was","why":"In 1995 指过去；the winner 是单数，所以用 was。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"获胜的车是几号车？","opts":["15号","5号","50号","14号"],"a":"15号","hint":"He was in car number fifteen.","why":"比利·斯图尔特驾驶15号车。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"回家路上妻子提醒丈夫什么？","opts":["别开太快","开快一点","走路回家","加油加满"],"a":"别开太快","hint":"Don't drive so quickly! You're not Billy Stewart!","why":"妻子说 Don’t drive so quickly!，提醒丈夫别开这么快；课文没有提供限速或超速证据。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":141,"printedPage":137,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":70,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":69},{"id":71,"title":"He's awful!","titleCn":"他讨厌透了！","kind":"text","words":[{"en":"awful","ipa":"/ˈɔːfʊl/","cn":"adj. 讨厌的，糟糕的","source":"supplement"},{"en":"time","ipa":"/taɪm/","cn":"n. 次（数）；时间","source":"supplement"},{"en":"answer","ipa":"/ˈɑːnsə/","cn":"v. 接（电话）；回答","source":"supplement"},{"en":"last","ipa":"/lɑːst/","cn":"adj. 上一个的，最后的","source":"supplement"},{"en":"phone","ipa":"/fəʊn/","cn":"n. 电话（telephone 的缩略）","source":"supplement"},{"en":"again","ipa":"/əˈɡen/","cn":"adv. 又一次，再一次","source":"supplement"},{"en":"say","ipa":"/seɪ/","cn":"v. 说","source":"supplement"},{"en":"yesterday","ipa":"/ˈjestədi/","cn":"adv. 昨天","source":"supplement"}],"patterns":[{"en":"What's Ron Marston like, Pauline?","cn":"罗恩·马斯顿是个怎样的人，波琳？","source":"textbook","pdfPage":145,"printedPage":141,"verification":"verified","translationSource":"supplement"},{"en":"He telephoned me four times yesterday.","cn":"他昨天给我打了四次电话。","source":"adaptation"},{"en":"Did he telephone again?","cn":"他又打电话了吗？","source":"textbook","pdfPage":145,"printedPage":141,"verification":"verified","translationSource":"supplement"}],"grammar":"规则动词过去式加 -ed：telephoned, answered；次数表达：一次 once，两次 twice，三次以上 数字 + times。","tip":"过去时疑问句用 did 提问、动词还原：Did he telephone? 不能说 Did he telephoned?","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}],"teachingSource":"supplement","text":[{"en":"What's Ron Marston like, Pauline?","cn":"罗恩·马斯顿是个怎样的人，波琳？","speaker":"JANE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He's awful!","cn":"他讨厌透了！","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He telephoned me four times yesterday, and three times the day before yesterday.","cn":"他昨天给我打了四次电话，前天打了三次。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He telephoned the office yesterday morning and yesterday afternoon.","cn":"他昨天上午和下午都打电话到办公室。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My boss answered the telephone.","cn":"我的老板接了电话。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What did your boss say to him?","cn":"你老板对他说了什么？","speaker":"JANE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He said, 'Pauline is typing letters. She can't speak to you now!'","cn":"他说：‘波琳正在打信，她现在不能和你讲话！’","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Then I arrived home at six o'clock yesterday evening.","cn":"后来，我昨天傍晚六点到家。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He telephoned again.","cn":"他又打来了电话。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"But I didn't answer the phone!","cn":"但我没接电话！","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Did he telephone again last night?","cn":"他昨晚又打电话了吗？","speaker":"JANE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, he did.","cn":"是的。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He telephoned at nine o'clock.","cn":"他九点钟打来的。","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What did you say to him?","cn":"你对他说了什么？","speaker":"JANE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I said, 'This is Pauline's mother. Please don't telephone my daughter again!'","cn":"我说：‘我是波琳的母亲，请不要再给我女儿打电话了！’","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Did he telephone again?","cn":"他又打电话了吗？","speaker":"JANE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, he didn't!","cn":"不，他没有！","speaker":"PAULINE","pdfPage":145,"printedPage":141,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"动词过去式：加 ed","chat":"规则动词的过去式直接加 ed：telephoned、answered、typed。说「几次」用 times：一次 once、两次 twice、四次 four times。问过去的事用 did 开头，后面的动词变回原形！","formula":"动词 + ed = 过去式 ｜ once 一次 → twice 两次 → …times","examples":[{"en":"He telephoned me four times yesterday.","cn":"他昨天给我打了4次电话。","source":"supplement"},{"en":"My boss answered the telephone.","cn":"我老板接了电话。","source":"supplement"},{"en":"Did he telephone again?","cn":"他又打电话了吗？","source":"supplement"}],"watch":"did 后面的动词要「脱掉」ed 变回原形：Did he telephoned ❌ → Did he telephone ✓！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},"ex":{"g":[{"q":"He telephoned me four ___ yesterday.","opts":["times","time","some time","timing"],"a":"times","why":"四次 = four times。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""},{"q":"Did he ___ again?","opts":["telephone","telephoned","telephones","telephoning"],"a":"telephone","why":"did 后面动词用原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""}],"c":[{"q":"根据课文，罗恩前天给波琳打了几次电话？","opts":["3次","4次","2次","1次"],"a":"3次","hint":"three times the day before yesterday","why":"昨天4次，前天3次。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},{"q":"办公室里是谁接的电话？","opts":["老板","波琳","简","罗恩"],"a":"老板","hint":"My boss answered the telephone.","why":"波琳说 My boss answered the telephone.；老板告诉罗恩，波琳正在打信。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":145,"printedPage":141,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}}]}},{"id":72,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":71},{"id":73,"title":"The way to King Street","titleCn":"到国王街的走法","kind":"text","words":[{"en":"week","ipa":"/wiːk/","cn":"n. 星期，周","source":"supplement"},{"en":"London","ipa":"/ˈlʌndən/","cn":"n. 伦敦","source":"supplement"},{"en":"suddenly","ipa":"/ˈsʌdnli/","cn":"adv. 突然地","source":"supplement"},{"en":"smile","ipa":"/smaɪl/","cn":"v. 微笑","source":"supplement"},{"en":"pleasantly","ipa":"/ˈplezntli/","cn":"adv. 愉快地","source":"supplement"},{"en":"understand","ipa":"/ˌʌndəˈstænd/","cn":"v. 懂，理解","source":"supplement"},{"en":"speak","ipa":"/spiːk/","cn":"v. 讲（语言），说话","source":"supplement"},{"en":"pocket","ipa":"/ˈpɒkɪt/","cn":"n. 衣袋","source":"supplement"},{"en":"phrasebook","ipa":"/ˈfreɪzbʊk/","cn":"n. 短语手册，常用语手册","source":"supplement"},{"en":"slowly","ipa":"/ˈsləʊli/","cn":"adv. 缓慢地","source":"supplement"}],"patterns":[{"en":"Last week Mrs. Mills went to London.","cn":"上星期米尔斯夫人去了伦敦。","source":"adaptation"},{"en":"She lost her way.","cn":"她迷路了。","source":"adaptation"},{"en":"Can you tell me the way to King Street, please?","cn":"请问到国王街怎么走？","source":"adaptation"}],"grammar":"不规则动词过去式：go→went, lose→lost, see→saw, speak→spoke, take→took；the way to... 表示“去……的路”。","tip":"问路句型：Can you tell me the way to...? / How can I get to...?；副词多由形容词加 -ly 构成：slow→slowly。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Last week Mrs. Mills went to London. She does not know London very well, and she lost her way.","cn":"上星期米尔斯夫人去了伦敦。她对伦敦不很熟悉，因此迷了路。","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Suddenly, she saw a man near a bus stop. “I can ask him the way,” she said to herself.","cn":"突然，她在公共汽车站附近看到一个男人。“我可以向他问路，”她想。","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“Excuse me,” she said. “Can you tell me the way to King Street, please?”","cn":"“对不起，”她说，“您能告诉我到国王街怎么走吗？”","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The man smiled pleasantly. He did not understand English! He spoke German. He was a tourist.","cn":"这人友好地笑了笑。他不懂英语！他讲德语，他是个游客。","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then he put his hand into his pocket, and took out a phrasebook.","cn":"然后他把手伸进了衣袋，掏出了一本常用语手册。","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He opened the book and found a phrase. He read the phrase slowly.","cn":"他翻开书找到了一条短语，他缓慢地读着这条短语。","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“I am sorry,” he said. “I do not speak English.”","cn":"“很抱歉，”他说，“我不会讲英语。”","source":"adaptation","pdfPage":153,"printedPage":149,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"不规则动词家族","chat":"英语有一批「不规则动词」，过去式要单独记，像记名字一样：go→went、lose→lost、see→saw、speak→spoke、take→took。问路句型 Can you tell me the way to…? 也超实用！","formula":"go→went ｜ lose→lost ｜ see→saw ｜ speak→spoke ｜ take→took","examples":[{"en":"Last week Mrs. Mills went to London.","cn":"上周米尔斯夫人去了伦敦。","source":"supplement"},{"en":"She lost her way.","cn":"她迷路了。","source":"supplement"},{"en":"Can you tell me the way to King Street, please?","cn":"请问到国王街怎么走？","source":"supplement"}],"watch":"很多副词 = 形容词 + ly：slow→slowly（慢慢地）、sudden→suddenly（突然地）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Mrs. Mills ___ her way in London.","opts":["lost","losed","loses","losing"],"a":"lost","why":"lose 不规则过去式 lost。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"He read the phrase ___.","opts":["slowly","slow","slower","slowest"],"a":"slowly","why":"修饰动词 read 用副词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"那位男士为什么不用英语回答？","opts":["他是讲德语的游客","他是法国人","他不会说话","他生气了"],"a":"他是讲德语的游客","hint":"He spoke German. He was a tourist.","why":"他不懂英语，是德国游客。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"他从口袋里掏出了什么？","opts":["一本短语手册","一张地图","一些钱","一张车票"],"a":"一本短语手册","hint":"took out a phrasebook","why":"照着短语手册慢慢念。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":153,"printedPage":149,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":74,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":73},{"id":75,"title":"Uncomfortable shoes","titleCn":"不舒适的鞋子","kind":"text","words":[{"en":"ago","ipa":"/əˈɡəʊ/","cn":"adv. 以前","source":"supplement"},{"en":"shoes","ipa":"/ʃuːz/","cn":"n. 鞋子（复数）","source":"supplement"},{"en":"fashion","ipa":"/ˈfæʃn/","cn":"n. 流行款式（in fashion 时兴）","source":"supplement"},{"en":"uncomfortable","ipa":"/ʌnˈkʌmftəbl/","cn":"adj. 不舒适的","source":"supplement"},{"en":"wear","ipa":"/weə/","cn":"v. 穿着，戴着","source":"supplement"},{"en":"buy","ipa":"/baɪ/","cn":"v. 买（bought）","source":"supplement"},{"en":"pair","ipa":"/peə/","cn":"n. 一双，一对","source":"supplement"},{"en":"then","ipa":"/ðen/","cn":"adv. 那时，然后","source":"supplement"}],"patterns":[{"en":"Do you have any shoes like these?","cn":"你们有像这样的鞋吗？","source":"adaptation"},{"en":"They were in fashion last year and the year before last.","cn":"它们去年和前年时兴。","source":"adaptation"},{"en":"Women always wear uncomfortable shoes!","cn":"女人们总是穿不舒适的鞋子！","source":"adaptation"}],"grammar":"“一段时间 + ago” 与一般过去时连用：ten years ago；like these 是介词短语作后置定语，修饰 shoes。","tip":"in fashion 流行 ↔ out of fashion 过时；a pair of shoes 一双鞋；buy 的过去式 bought。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you have any shoes like these?","cn":"你们有像这样的鞋吗？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What size?","cn":"什么尺码的？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Size five.","cn":"5号的。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What colour?","cn":"什么颜色？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Black.","cn":"黑色的。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm sorry. We don't have any.","cn":"很抱歉，我们没有。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"But my sister bought this pair last month.","cn":"但是，我姐姐上个月买了一双这样的鞋子。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Did she buy them here?","cn":"她是在您这儿买的吗？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, she bought them in the U.S.","cn":"不，她是在美国买的。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We had some shoes like those a month ago, but we don't have any now.","cn":"一个月前我们有这种鞋，但现在没有了。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you get a pair for me, please?","cn":"您能为我找一双吗？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid that I can't. They were in fashion last year and the year before last. But they're not in fashion this year.","cn":"恐怕不行。这种鞋子去年和前年时兴，而今年已不流行了。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"These shoes are in fashion now.","cn":"现在流行的是这种鞋子。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you like them?","cn":"您喜欢这种鞋子吗？","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, they look very uncomfortable.","cn":"喜欢，不过它们看上去很不舒服。","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They are very uncomfortable. But women always wear uncomfortable shoes!","cn":"的确很不舒服。可女人们总是穿不舒适的鞋子！","source":"adaptation","pdfPage":157,"printedPage":153,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"ago：过去的信号灯","chat":"「一段时间 + ago」是一般过去时的信号灯：a month ago（一个月前）→ 用过去式 bought。「在流行」是 in fashion，「过时了」是 out of fashion。","formula":"时间段 + ago → 一般过去时 ｜ in fashion 流行 ⇄ out of fashion 过时","examples":[{"en":"We had some shoes like those a month ago.","cn":"一个月前我们有那种鞋。","source":"supplement"},{"en":"They were in fashion last year.","cn":"它们去年很流行。","source":"supplement"},{"en":"But they're not in fashion this year.","cn":"但今年不流行了。","source":"supplement"}],"watch":"buy 的过去式不规则：buy → bought！wear → wore（穿的过去式）也是。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Do you have any shoes ___ these?","opts":["like","likes","liking","liked"],"a":"like","why":"like these 是介词短语作定语：「像这样的」。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"They were in fashion last year and ___ ___ ___.","opts":["the year before last","last year ago","next year","the last year"],"a":"the year before last","why":"the year before last = 前年。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"女士要什么尺码的鞋？","opts":["5号","6号","7号","9号"],"a":"5号","hint":"Size five.","why":"5号黑鞋。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"她姐姐的鞋是在哪儿买的？","opts":["美国","这家店","伦敦","中国"],"a":"美国","hint":"she bought them in the U.S.","why":"美国买的，所以这家店没有。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":157,"printedPage":153,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":76,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":75},{"id":77,"title":"Terrible toothache","titleCn":"要命的牙痛","kind":"text","words":[{"en":"appointment","ipa":"/əˈpɔɪntmənt/","cn":"n. 预约，约会","source":"supplement"},{"en":"urgent","ipa":"/ˈɜːdʒənt/","cn":"adj. 紧急的","source":"supplement"},{"en":"till","ipa":"/tɪl/","cn":"prep. 直到","source":"supplement"},{"en":"toothache","ipa":"/ˈtuːθeɪk/","cn":"n. 牙痛","source":"supplement"},{"en":"dentist","ipa":"/ˈdentɪst/","cn":"n. 牙医","source":"supplement"},{"en":"wait","ipa":"/weɪt/","cn":"v. 等待","source":"supplement"},{"en":"afternoon","ipa":"/ˌɑːftəˈnuːn/","cn":"n. 下午","source":"supplement"}],"patterns":[{"en":"Do you have an appointment?","cn":"您预约了吗？","source":"adaptation"},{"en":"Is it urgent?","cn":"急吗？","source":"adaptation"},{"en":"Can't you wait till this afternoon?","cn":"您就不能等到今天下午吗？","source":"adaptation"}],"grammar":"have an appointment 有预约；否定疑问句 Can't you...? 带有惊讶或不耐烦的语气。","tip":"till = until 直到；牙疼 have a toothache，看牙医 see the dentist——课末金句：I can wait, but my toothache can't!","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"I want to see the dentist, please.","cn":"我想见牙科医生。","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you have an appointment?","cn":"您预约了吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, I don't.","cn":"没有。","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is it urgent?","cn":"急吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, it is. It's very urgent. I have terrible toothache.","cn":"是的，很急。我牙痛得厉害。","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you come at 10 a.m. on Monday, May 4th?","cn":"您在星期一，5月4日上午10点来行吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I must see the dentist now, nurse.","cn":"护士，我现在就必须见牙科医生。","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The dentist is very busy at the moment. Can you come at 2 p.m.?","cn":"牙科医生这会儿很忙，您下午2点来行吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's very late. Can't the dentist see me now?","cn":"那就太晚了。牙医现在就不能看一下吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid that he can't, Mr. Croft. Can't you wait till this afternoon?","cn":"恐怕不行，克罗夫特先生。您就不能等到今天下午吗？","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I can wait, but my toothache can't!","cn":"我可以等，可我的牙痛等不了啊！","source":"adaptation","pdfPage":161,"printedPage":157,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"否定疑问句的语气","chat":"Can't you…? 是否定疑问句，带着「你就不能……吗？」的语气（有点不耐烦或惊讶）。till = until，表示「直到……」。看病先问：Do you have an appointment?（您预约了吗？）","formula":"Can't you + 动词…? （你就不能……吗？）｜ wait till… 等到……","examples":[{"en":"Do you have an appointment?","cn":"您预约了吗？","source":"supplement"},{"en":"Is it urgent?","cn":"急吗？","source":"supplement"},{"en":"Can't you wait till this afternoon?","cn":"您就不能等到今天下午吗？","source":"supplement"}],"watch":"牙疼是 have a toothache；看牙医是 see the dentist——两个固定搭配一起记！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Do you have an ___?","opts":["appointment","urgent","till","dentist"],"a":"appointment","why":"have an appointment 有预约。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Can't you wait ___ this afternoon?","opts":["till","to","at","on"],"a":"till","why":"till = until 直到。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"克罗夫特先生怎么了？","opts":["牙痛得厉害","重感冒","摔伤了背","发烧"],"a":"牙痛得厉害","hint":"I have terrible toothache.","why":"要命的牙痛。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"克罗夫特先生能等吗？","opts":["我能等，可我的牙痛等不了","他完全不能等","他乐意等一天","他直接回家了"],"a":"我能等，可我的牙痛等不了","hint":"I can wait, but my toothache can't!","why":"课文金句！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":161,"printedPage":157,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":78,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":77},{"id":79,"title":"Carol's shopping list","titleCn":"卡罗尔的购物单","kind":"text","words":[{"en":"shopping","ipa":"/ˈʃɒpɪŋ/","cn":"n. 购物","source":"supplement"},{"en":"list","ipa":"/lɪst/","cn":"n. 单子，清单","source":"supplement"},{"en":"vegetable","ipa":"/ˈvedʒtəbl/","cn":"n. 蔬菜","source":"supplement"},{"en":"need","ipa":"/niːd/","cn":"v. 需要","source":"supplement"},{"en":"hope","ipa":"/həʊp/","cn":"v. 希望","source":"supplement"},{"en":"thing","ipa":"/θɪŋ/","cn":"n. 东西，事情","source":"supplement"},{"en":"money","ipa":"/ˈmʌni/","cn":"n. 钱（不可数）","source":"supplement"},{"en":"beer","ipa":"/bɪə/","cn":"n. 啤酒","source":"supplement"},{"en":"wine","ipa":"/waɪn/","cn":"n. 葡萄酒，果酒","source":"supplement"},{"en":"grocer","ipa":"/ˈɡrəʊsə/","cn":"n. 食品杂货商","source":"supplement"}],"patterns":[{"en":"I'm making a shopping list.","cn":"我在拟一张购物单。","source":"adaptation"},{"en":"We need a lot of things this week.","cn":"这里期我们需要很多东西。","source":"adaptation"},{"en":"I hope you've got some money.","cn":"我希望你带了钱。","source":"adaptation"}],"grammar":"need 后接名词或 to do；a lot of + 复数或不可数名词；have got = have（英式口语）：We haven't got much tea.","tip":"go shopping 去购物；money 不可数——much money / a lot of money，不能说 many moneys。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"I'm making a shopping list, Tom.","cn":"我在拟一张购物单，汤姆。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What do we need?","cn":"我们需要买些什么？","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We need a lot of things this week.","cn":"这里期我们需要很多东西。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I must go to the grocer's. We haven't got much tea or coffee, and we haven't got any sugar or jam.","cn":"我得到食品店去一趟。我们的茶叶和咖啡不多了，糖和果酱也没有了。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about vegetables?","cn":"蔬菜呢？","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I must go to the greengrocer's. We haven't got many tomatoes, but we've got a lot of potatoes.","cn":"我也得到蔬菜水果店去一趟。我们的西红柿不多了，但土豆还有不少。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I must go to the butcher's, too. We need some meat. We haven't got any meat at all.","cn":"我还要到肉店去一下。我们需要些肉，我们一点肉也没有了。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Have we got any beer and wine?","cn":"我们还有啤酒和果酒吗？","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, we haven't. And I'm not going to get any!","cn":"没有了。不过，我也不打算去买！","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I hope that you've got some money.","cn":"我希望你带钱了。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I haven't got much.","cn":"我的钱不多。","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, I haven't got much either!","cn":"唉，我的钱也不多！","source":"adaptation","pdfPage":165,"printedPage":161,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"have got 与 much/many","chat":"have got 就是 have 的口语版：We haven't got much tea.（我们的茶不多了）。量词怎么选？much 配「数不清」的（much money），many 配「数得清」的（many eggs），a lot of 两者通吃！","formula":"haven't got = don't have ｜ much + 不可数 ／ many + 可数 ／ a lot of 都可以","examples":[{"en":"We haven't got much tea or coffee.","cn":"我们的茶和咖啡不多了。","source":"supplement"},{"en":"We need a lot of things this week.","cn":"这里期我们需要很多东西。","source":"supplement"},{"en":"Have we got any beer and wine?","cn":"我们还有啤酒和果酒吗？","source":"supplement"}],"watch":"money 数不清：much money ✓ many money ❌！tomatoes 数得清：many tomatoes ✓","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"We haven't got ___ tea.","opts":["much","many","a lot","lot"],"a":"much","why":"tea 不可数，用 much。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"We haven't got ___ tomatoes.","opts":["many","much","much of","a lot"],"a":"many","why":"tomatoes 可数，用 many。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"卡罗尔正在写什么？","opts":["购物单","一封信","一张贺卡","菜单"],"a":"购物单","hint":"I'm making a shopping list.","why":"本周要买很多东西。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"他们还有啤酒吗？","opts":["没有了，也不打算买","还有很多","只剩一点","汤姆去买"],"a":"没有了，也不打算买","hint":"And I'm not going to get any!","why":"卡罗尔赌气说不去买。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":165,"printedPage":161,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":80,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":79},{"id":81,"title":"Roast beef and potatoes","titleCn":"烤牛肉和土豆","kind":"text","words":[{"en":"bath","ipa":"/bɑːθ/","cn":"n. 洗澡（have a bath）；浴缸","source":"supplement"},{"en":"nearly","ipa":"/ˈnɪəli/","cn":"adv. 几乎，差不多","source":"supplement"},{"en":"ready","ipa":"/ˈredi/","cn":"adj. 准备好的","source":"supplement"},{"en":"dinner","ipa":"/ˈdɪnə/","cn":"n. 正餐，晚餐","source":"supplement"},{"en":"restaurant","ipa":"/ˈrestrɒnt/","cn":"n. 餐馆","source":"supplement"},{"en":"roast","ipa":"/rəʊst/","cn":"adj. 烤的","source":"supplement"},{"en":"breakfast","ipa":"/ˈbrekfəst/","cn":"n. 早饭","source":"supplement"},{"en":"haircut","ipa":"/ˈheəkʌt/","cn":"n. 理发","source":"supplement"},{"en":"party","ipa":"/ˈpɑːti/","cn":"n. 聚会","source":"supplement"}],"patterns":[{"en":"Where's Tom? He's having a bath.","cn":"汤姆在哪儿？他在洗澡。","source":"adaptation"},{"en":"We had roast beef and potatoes.","cn":"我们吃了烤牛肉和土豆。","source":"adaptation"},{"en":"What did you have for lunch?","cn":"你们午饭吃了什么？","source":"adaptation"}],"grammar":"have + 名词 = 做某事：have a bath 洗澡 / have lunch 吃饭 / have a haircut 理发；have 的过去式是 had。","tip":"这里的 have 表示“从事、进行”而不是“拥有”，所以能有进行时：He's having a bath.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Hi, Carol! Where's Tom?","cn":"嗨，卡罗尔！汤姆在哪儿？","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's upstairs. He's having a bath.","cn":"他在楼上，他正在洗澡。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Tom!","cn":"汤姆！","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes?","cn":"什么事？","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Sam's here.","cn":"萨姆来了。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm nearly ready.","cn":"我就好。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Hello, Sam. Have a cigarette.","cn":"你好，萨姆。请抽烟。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, thanks, Tom.","cn":"不抽了，谢谢，汤姆。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Have a glass of whisky then.","cn":"那么，来杯威士忌吧。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"OK. Thanks.","cn":"好的，谢谢。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is dinner ready, Carol?","cn":"卡罗尔，饭好了吗？","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's nearly ready. We can have dinner at seven o'clock.","cn":"马上就好。7点钟我们可以吃饭。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Sam and I had lunch together today. We went to a restaurant.","cn":"今天我和萨姆一起吃的午饭，我们去了一家餐馆。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What did you have?","cn":"你们吃的什么？","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We had roast beef and potatoes.","cn":"我们吃的是烤牛肉和土豆。","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Oh!","cn":"噢！","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the matter, Carol?","cn":"怎么了，卡罗尔？","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, you're going to have roast beef and potatoes again tonight!","cn":"唉，今晚你们又要吃烤牛肉和土豆了！","source":"adaptation","pdfPage":169,"printedPage":165,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"have 不只是「有」","chat":"have + 名词 = 「做某件事」：have a bath 洗澡、have lunch 吃午饭、have a haircut 理发。因为是「做事」，它能用进行时：He's having a bath.（他正在洗澡）。have 的过去式是 had！","formula":"have a bath / have lunch / have a haircut ｜ What did you have?（你们吃了什么？）","examples":[{"en":"He's upstairs. He's having a bath.","cn":"他在楼上洗澡呢。","source":"supplement"},{"en":"What did you have for lunch?","cn":"你们午饭吃了什么？","source":"supplement"},{"en":"We had roast beef and potatoes.","cn":"我们吃了烤牛肉和土豆。","source":"supplement"}],"watch":"问句里已经有 did，动词用原形：What did you had ❌ → What did you have ✓！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"He's ___ a bath.","opts":["having","have","has","had"],"a":"having","why":"现在进行时 be + having。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"What did you ___ for lunch?","opts":["have","had","has","having"],"a":"have","why":"did 后面用动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"汤姆在哪儿？","opts":["楼上洗澡","上班","在花园","吃午饭"],"a":"楼上洗澡","hint":"He's upstairs. He's having a bath.","why":"在楼上洗澡。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"萨姆和汤姆午饭吃了什么？","opts":["烤牛肉和土豆","鱼和薯条","鸡肉米饭","汤和面包"],"a":"烤牛肉和土豆","hint":"We had roast beef and potatoes.","why":"结果晚上又是烤牛肉和土豆！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":169,"printedPage":165,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":82,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":81},{"id":83,"title":"Going on holiday","titleCn":"度假","kind":"text","words":[{"en":"mess","ipa":"/mes/","cn":"n. 乱七八糟","source":"supplement"},{"en":"pack","ipa":"/pæk/","cn":"v. 打包，装箱","source":"supplement"},{"en":"suitcase","ipa":"/ˈsuːtkeɪs/","cn":"n. 手提箱","source":"supplement"},{"en":"leave","ipa":"/liːv/","cn":"v. 离开（left）","source":"supplement"},{"en":"already","ipa":"/ɔːlˈredi/","cn":"adv. 已经","source":"supplement"},{"en":"holiday","ipa":"/ˈhɒlədeɪ/","cn":"n. 假期","source":"supplement"}],"patterns":[{"en":"Have you packed your suitcase yet?","drill":true,"cn":"你把手提箱收拾好了吗？","source":"supplement"},{"en":"I've already packed it.","drill":true,"cn":"我已经收拾好了。","source":"supplement"},{"en":"We're going on holiday tomorrow.","cn":"我们明天要去度假。","source":"adaptation"}],"grammar":"现在完成时 have/has + 过去分词；already 用于肯定句，yet 用于否定句和疑问句（常放句尾）。","tip":"go on holiday 去度假（英式），美国人常说 go on vacation；What a mess! 乱死了！","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Hello, Sam. Come in.","cn":"你好，萨姆，进来吧。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Hi, Sam. We're having lunch. Do you want to have lunch with us?","cn":"嗨，萨姆。我们正在吃午饭，你跟我们一起吃好吗？","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, thank you, Tom. I've already had lunch. I had lunch at half past twelve.","cn":"不，汤姆，谢谢。我已经吃过午饭了。我在12点半吃的。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Have a cup of coffee then.","cn":"那么喝杯咖啡吧。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I've just had a cup, thank you. I had one after my lunch.","cn":"我刚喝了一杯，谢谢。我吃完午饭就喝了一杯。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Let's go into the living room, Carol. We can have our coffee there.","cn":"我们到客厅去，卡罗尔，我们可以在那里喝咖啡。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Excuse the mess, Sam. This room's very untidy. We're packing our suitcases. We're going to leave tomorrow. Tom and I are going to have a holiday.","cn":"屋子很乱，请原谅，萨姆。房间里乱七八糟。我们正在收拾手提箱，明天我们就要走了。我和汤姆准备去度假。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Aren't you lucky!","cn":"你们真幸运啊！","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"When are you going to have a holiday, Sam?","cn":"萨姆，你打算什么时候度假？","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I don't know. I've already had my holiday this year.","cn":"我不知道。今年我已经度过假了。","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Where did you go?","cn":"你去了哪儿？","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I stayed at home!","cn":"我呆在家里！","source":"adaptation","pdfPage":173,"printedPage":169,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"现在完成时登场","chat":"现在完成时 = have/has + 过去分词，表示「已经做完，跟现在有关系」。already（已经）放在句中；yet（还）放在句尾，只出现在疑问句和否定句里。","formula":"主语 + have/has + 过去分词 ｜ Have you…yet? → I've already…","examples":[{"en":"Have you packed your suitcase yet?","cn":"你行李箱收拾好了吗？","source":"supplement"},{"en":"I've already packed it.","cn":"我已经收拾好了。","source":"supplement"},{"en":"I've just had a cup of coffee.","cn":"我刚喝了一杯咖啡。","source":"supplement"}],"watch":"pack→packed，have→had；go 的过去分词是 gone：be→was/were→been。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Have you packed your suitcase ___?","opts":["yet","already","just","still"],"a":"yet","why":"疑问句句尾用 yet。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I've ___ had lunch.","opts":["already","yet","still","too"],"a":"already","why":"肯定句用 already。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"卡罗尔和汤姆什么时候出发？","opts":["明天","今天","下周","今晚"],"a":"明天","hint":"We're going to leave tomorrow.","why":"行李都打包好了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"萨姆今年在哪儿度的假？","opts":["家里","巴黎","乡下","海边"],"a":"家里","hint":"I stayed at home!","why":"课文的笑点：别人去度假，他在家。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":173,"printedPage":169,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":84,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":83},{"id":85,"title":"Paris in the spring","titleCn":"巴黎之春","kind":"text","words":[{"en":"Paris","ipa":"/ˈpærɪs/","cn":"n. 巴黎","source":"supplement"},{"en":"cinema","ipa":"/ˈsɪnəmə/","cn":"n. 电影院","source":"supplement"},{"en":"film","ipa":"/fɪlm/","cn":"n. 电影","source":"supplement"},{"en":"beautiful","ipa":"/ˈbjuːtɪfʊl/","cn":"adj. 美丽的","source":"supplement"},{"en":"city","ipa":"/ˈsɪti/","cn":"n. 城市","source":"supplement"},{"en":"never","ipa":"/ˈnevə/","cn":"adv. 从来没有","source":"supplement"},{"en":"ever","ipa":"/ˈevə/","cn":"adv. 曾经","source":"supplement"}],"patterns":[{"en":"Have you just been to the cinema?","cn":"你刚去过电影院吗？","source":"adaptation"},{"en":"What's on?","cn":"上映什么片子？","source":"adaptation"},{"en":"I've never been there.","cn":"我从未去过那里。","source":"adaptation"}],"grammar":"have been to 去过（已回来），have gone to 去了（还没回来）；ever / never 用于完成时谈论经历。","tip":"谈“去过某地”的经历用完成时：Have you ever been to Paris?；What's on? 问“上演什么”。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Have you just been to the cinema?","cn":"你刚去过电影院吗？","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I have.","cn":"是的，我刚去过。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's on?","cn":"上映什么片子？","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“Paris in the Spring”.","cn":"《巴黎之春》。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Oh, I've already seen it. I saw it on television last year. It's an old film, but it's very good.","cn":"噢，我已经看过了。我是去年在电视上看的。这是老片子，但影片很好。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Paris is a beautiful city.","cn":"巴黎是座美丽的城市。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I've never been there. Have you ever been there, Ken?","cn":"我从未去过。肯，你去过吗？","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I have. I was there in April.","cn":"去过，我是4月份去的。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Paris in the spring, eh?","cn":"巴黎之春，是吧？","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It was raining at the time.","cn":"那段时间一直在下雨。","source":"adaptation","pdfPage":177,"printedPage":173,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"have been to 与 have gone to","chat":"「去过某地」（人已回来）用 have been to；「去了某地」（人还没回）用 have gone to。谈「人生的经历」用 ever（曾经）提问、never（从未）回答。","formula":"have been to 去过（已回）｜ have gone to 去了（未回）｜ ever / never","examples":[{"en":"Have you just been to the cinema?","cn":"你刚去过电影院吗？","source":"supplement"},{"en":"I've never been there.","cn":"我从没去过那儿。","source":"supplement"},{"en":"Have you ever been there, Ken?","cn":"肯，你去过那儿吗？","source":"supplement"}],"watch":"been 是 be 的过去分词；seen 是 see 的过去分词（see→saw→seen）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Have you ___ been to the cinema?","opts":["just","already","yet","never"],"a":"just","why":"「刚刚」用 just。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I've ___ been there.","opts":["never","ever","already","yet"],"a":"never","why":"「从未」用 never。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"电影院上映什么片子？","opts":["巴黎之春","伦敦之秋","罗马之夏","车祸"],"a":"巴黎之春","hint":"Paris in the Spring.","why":"乔治已经在电视上看过了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"肯是什么时候去的巴黎？","opts":["4月","8月","上周","冬天"],"a":"4月","hint":"I was there in April.","why":"可惜那段时间一直下雨。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":177,"printedPage":173,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":86,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":85},{"id":87,"title":"A car crash","titleCn":"车祸","kind":"text","words":[{"en":"attendant","ipa":"/əˈtendənt/","cn":"n. 接待员，服务员","source":"supplement"},{"en":"bring","ipa":"/brɪŋ/","cn":"v. 带来（brought）","source":"supplement"},{"en":"garage","ipa":"/ˈɡærɑːʒ/","cn":"n. 车库；修车厂","source":"supplement"},{"en":"crash","ipa":"/kræʃ/","cn":"n. 碰撞；v. 碰撞","source":"supplement"},{"en":"lamp-post","ipa":"/ˈlæmp pəʊst/","cn":"n. 灯杆，路灯柱","source":"supplement"},{"en":"repair","ipa":"/rɪˈpeə/","cn":"v. 修理","source":"supplement"},{"en":"try","ipa":"/traɪ/","cn":"v. 设法，努力","source":"supplement"},{"en":"drive","ipa":"/draɪv/","cn":"v. 驾驶（drove）","source":"supplement"}],"patterns":[{"en":"Isn't your car ready yet?","cn":"你的车还没有修好吗？","source":"adaptation"},{"en":"I drove it into a lamp-post.","cn":"我把汽车撞到路灯杆上了。","source":"adaptation"},{"en":"Can your mechanics repair it?","cn":"你们的机械师能把它修好吗？","source":"adaptation"}],"grammar":"不规则过去式：drive→drove, bring→brought；still 表示“仍然”，yet 用于否定句和疑问句。","tip":"have a crash 出车祸；try to do sth 设法做某事——They're still trying to repair it.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Isn't my car ready yet?","cn":"我的汽车还没有修好吗？","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, I'm afraid not. They're still working on it.","cn":"还没有，恐怕没有。机械师们还在修呢。","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I brought it here three days ago.","cn":"我是3天前送来的。","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I know. Didn't you have a crash?","cn":"是的，我知道。您难道没有出过车祸吗？","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's right. I drove it into a lamp-post. Can your mechanics repair it?","cn":"是的，我把汽车撞在电线杆上了。你们的机械师能修好吗？","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, they're trying to repair it, sir. But to tell you the truth, you need a new car!","cn":"好吧，他们正在设法修呢，先生。不过说实在的，您需要买一辆新车了！","source":"adaptation","pdfPage":181,"printedPage":177,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"still 与 yet 的位置","chat":"still（仍然）放在 be 动词后面：They're still working on it.（他们还在修呢）。yet（还）放在句尾，配合否定：not ready yet（还没好）。两个不规则过去式一起记：drive→drove、bring→brought。","formula":"主语 + be + still + 动词ing ｜ not… yet 还没……","examples":[{"en":"Isn't your car ready yet?","cn":"你的车还没好吗？","source":"supplement"},{"en":"They're still working on it.","cn":"他们还在修呢。","source":"supplement"},{"en":"I drove it into a lamp-post.","cn":"我把它撞到路灯杆上了。","source":"supplement"}],"watch":"try to do = 设法做：They're trying to repair it. 他们正设法修。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I ___ it into a lamp-post.","opts":["drove","drived","drink","driven"],"a":"drove","why":"drive 不规则过去式 drove。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"They're still ___ on it.","opts":["working","work","works","worked"],"a":"working","why":"still + 进行时：还在修。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"那位先生把车撞到了什么上？","opts":["路灯杆","树上","墙上","别的车"],"a":"路灯杆","hint":"I drove it into a lamp-post.","why":"车祸的起因。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"接待员最后说先生需要什么？","opts":["一辆新车","一个新轮胎","一根新灯杆","一个新车库"],"a":"一辆新车","hint":"you need a new car!","why":"修不如买，课文的幽默。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":181,"printedPage":177,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":88,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":87},{"id":89,"title":"For sale","titleCn":"待售","kind":"text","words":[{"en":"believe","ipa":"/bɪˈliːv/","cn":"v. 相信","source":"supplement"},{"en":"may","ipa":"/meɪ/","cn":"aux. 可以","source":"supplement"},{"en":"sell","ipa":"/sel/","cn":"v. 卖（sold）","source":"supplement"},{"en":"because","ipa":"/bɪˈkɒz/","cn":"conj. 因为","source":"supplement"},{"en":"retire","ipa":"/rɪˈtaɪə/","cn":"v. 退休","source":"supplement"},{"en":"cost","ipa":"/kɒst/","cn":"v. 花费（cost）","source":"supplement"},{"en":"pound","ipa":"/paʊnd/","cn":"n. 英镑","source":"supplement"},{"en":"worth","ipa":"/wɜːθ/","cn":"adj. 值……钱","source":"supplement"},{"en":"penny","ipa":"/ˈpeni/","cn":"n. 便士（复数 pence）","source":"supplement"},{"en":"since","ipa":"/sɪns/","cn":"prep. 自从","source":"supplement"}],"patterns":[{"en":"I believe this house is for sale.","cn":"我想这房子是要出售的吧？","source":"adaptation"},{"en":"How long have you lived here?","cn":"您在这里住了多久了？","source":"adaptation"},{"en":"I've lived here for twenty years.","cn":"我在这里已经住了二十年了。","source":"adaptation"},{"en":"How much does this house cost?","cn":"这座房子卖多少钱？","source":"adaptation"}],"grammar":"现在完成时 + for（接一段时间）/ since（接时间点）；how much 问价格；for sale 待售。","tip":"for + 时间段，since + 时间点：for twenty years / since 2005；It's worth every penny. 一分钱一分货。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Good afternoon. I believe that this house is for sale.","cn":"下午好。我想这房子是要出售的吧？","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's right.","cn":"是的。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"May I have a look at it, please?","cn":"我可以看一看吗？","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, of course. Come in.","cn":"可以，当然可以。请进。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How long have you lived here?","cn":"您在这里住了多长时间？","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I've lived here for twenty years.","cn":"我在这里住了20年了。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Twenty years! That's a long time.","cn":"20年！这个时间可不短。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I've been here since 1976.","cn":"是啊，从1976年起我就住在这里。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Then why do you want to sell it?","cn":"那么，您为什么要卖掉它呢？","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Because I've just retired. I want to buy a small house in the country.","cn":"因为我刚退休。我想在乡下买幢小房子。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How much does this house cost?","cn":"这座房子卖多少钱？","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"£68,500.","cn":"68500英镑。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's a lot of money!","cn":"那可真是一大笔钱啊！","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's worth every penny of it.","cn":"它值那么多钱。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, I like the house, but I can't decide yet. My wife must see it first.","cn":"嗯，我喜欢这房子，但我还不能作决定。我妻子必须先来看一看。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Women always have the last word.","cn":"最后作出决定的总是女人。","source":"adaptation","pdfPage":185,"printedPage":181,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"for 和 since 的分工","chat":"现在完成时说「持续了多久」：for + 一段时间（for twenty years 二十年），since + 起点（since 1976 从1976年起）。问价钱用 How much…? 问时长用 How long…?","formula":"have + 过去分词 + for + 时间段 ／ since + 时间点","examples":[{"en":"How long have you lived here?","cn":"您在这里住了多久？","source":"supplement"},{"en":"I've lived here for twenty years.","cn":"我住了20年了。","source":"supplement"},{"en":"I've been here since 1976.","cn":"我从1976年起就住这儿。","source":"supplement"}],"watch":"for 后面跟「20年」这样的长度，since 后面跟「1976年」这样的起点，一个管长度、一个管起点！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"How ___ have you lived here?","opts":["long","much","often","old"],"a":"long","why":"问时长用 How long。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I've lived here ___ twenty years.","opts":["for","since","at","in"],"a":"for","why":"for + 时间段。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"房主为什么卖房？","opts":["刚退休了","房子太旧","房子太小","不喜欢邻居"],"a":"刚退休了","hint":"Because I've just retired.","why":"想去乡下买小房子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"这座房子卖多少钱？","opts":["68500英镑","6850英镑","685英镑","68050英镑"],"a":"68500英镑","hint":"£68,500.","why":"It's worth every penny of it.","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":185,"printedPage":181,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":90,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":89},{"id":91,"title":"Poor Ian!","titleCn":"可怜的伊恩！","kind":"text","words":[{"en":"still","ipa":"/stɪl/","cn":"adv. 还，仍旧","source":"supplement"},{"en":"move","ipa":"/muːv/","cn":"v. 搬家；移动","source":"supplement"},{"en":"miss","ipa":"/mɪs/","cn":"v. 想念；错过","source":"supplement"},{"en":"neighbour","ipa":"/ˈneɪbə/","cn":"n. 邻居","source":"supplement"},{"en":"person","ipa":"/ˈpɜːsn/","cn":"n. 人（单数）","source":"supplement"},{"en":"people","ipa":"/ˈpiːpl/","cn":"n. 人们（复数）","source":"supplement"},{"en":"poor","ipa":"/pɔː/","cn":"adj. 可怜的；贫穷的","source":"supplement"}],"patterns":[{"en":"Has Ian sold his house yet?","cn":"伊恩把房子卖了吗？","source":"textbook","pdfPage":189,"printedPage":185,"verification":"verified","translationSource":"supplement"},{"en":"He's still here.","cn":"他还在这儿。","source":"textbook","pdfPage":189,"printedPage":185,"verification":"verified","translationSource":"supplement"},{"en":"We'll all miss him.","cn":"我们都会想念他的。","source":"textbook","pdfPage":189,"printedPage":185,"verification":"verified","translationSource":"supplement"}],"grammar":"现在完成时疑问句：Has he ... yet?；will 可表示将来：I’ll miss him.；本课 He’s still here 中 still 放在 be 动词后。","tip":"miss 常表示想念朋友或错过火车（I missed the bus.）。本课 people 表示“人们”，已经按复数使用，不再加 s；不是说 peoples 在所有语境中都错误。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"Has Ian sold his house yet?","cn":"伊恩把他的房子卖掉了吗？","speaker":"CATHERINE","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, he has. He sold it last week.","cn":"是的，卖掉了。他是上星期卖掉的。","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Has he moved to his new house yet?","cn":"他已经搬进新居了吗？","speaker":"CATHERINE","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, not yet. He's still here. He's going to move tomorrow.","cn":"不，还没有。他仍在这里，他打算明天搬家。","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"When? Tomorrow morning?","cn":"什么时候？明天上午吗？","speaker":"CATHERINE","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No. Tomorrow afternoon. I'll miss him. He has always been a good neighbour.","cn":"不，是明天下午。我会想念他的，他一直是个好邻居。","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He's a very nice person. We'll all miss him.","cn":"他是个非常好的人，我们都会想念他的。","speaker":"LINDA","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"When will the new people move into this house?","cn":"新住户什么时候搬进这所房子？","speaker":"CATHERINE","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I think that they'll move in the day after tomorrow.","cn":"我想他们将会在后天搬进来吧。","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Will you see Ian today, Jenny?","cn":"詹妮，你今天会见到伊恩吗？","speaker":"LINDA","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, I will.","cn":"会的。","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Please give him my regards.","cn":"请代我问候他。","speaker":"LINDA","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Poor Ian! He didn't want to leave this house.","cn":"可怜的伊恩！他本不想离开这幢房子。","speaker":"CATHERINE","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, he didn't want to leave, but his wife did!","cn":"是啊，他不想离开，可是他妻子要离开！","speaker":"JENNY","source":"textbook","pdfPage":189,"printedPage":185,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"Has he…yet? 与 will","chat":"现在完成时的一般疑问句把 Have/Has 提前：Has he sold his house yet?（他卖掉房子了吗？）；yet 在这里表示“已经”，并不是每个疑问句都必须加 yet。will 表示将来：I’ll miss him.（我会想念他）。本课 He’s still here 中 still 放在 be 动词后。","formula":"Has + 主语 + 过去分词 + yet? ｜ 主语 + will + 动词原形","examples":[{"en":"Has Ian sold his house yet?","cn":"伊恩把房子卖了吗？","source":"supplement"},{"en":"He's going to move tomorrow.","cn":"他打算明天搬家。","source":"supplement"},{"en":"We'll all miss him.","cn":"我们都会想念他的。","source":"supplement"}],"watch":"miss 有两个意思：想念朋友／错过公交车（I missed the bus!）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"Has Ian ___ his house yet?","opts":["sold","sell","sells","selling"],"a":"sold","why":"完成时用过去分词 sold。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"We'll all ___ him.","opts":["miss","misses","missing","missed"],"a":"miss","why":"will 后面跟动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"伊恩打算什么时候搬家？","opts":["明天下午","明天上午","后天","下周"],"a":"明天下午","hint":"No. Tomorrow afternoon.","why":"还没搬，仍在老房子里。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"谁想离开这幢房子？","opts":["伊恩的妻子","伊恩","詹妮","新住户"],"a":"伊恩的妻子","hint":"he didn't want to leave, but his wife did!","why":"课文的反转结尾！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":189,"printedPage":185,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":92,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":91},{"id":93,"title":"Our new neighbour","titleCn":"我们的新邻居","kind":"text","words":[{"en":"pilot","ipa":"/ˈpaɪlət/","cn":"n. 飞行员","source":"supplement"},{"en":"return","ipa":"/rɪˈtɜːn/","cn":"v. 返回","source":"supplement"},{"en":"New York","ipa":"/njuː jɔːk/","cn":"n. 纽约","source":"supplement"},{"en":"Tokyo","ipa":"/ˈtəʊkiəʊ/","cn":"n. 东京","source":"supplement"},{"en":"Madrid","ipa":"/məˈdrɪd/","cn":"n. 马德里","source":"supplement"},{"en":"next door","ipa":"/nekst dɔː/","cn":"phr. 隔壁","source":"supplement"},{"en":"month","ipa":"/mʌnθ/","cn":"n. 月","source":"supplement"},{"en":"will","ipa":"/wɪl/","cn":"aux. 将要","source":"supplement"}],"patterns":[{"en":"Nigel is our new next-door neighbour.","cn":"奈杰尔是我们新搬来的隔壁邻居。","source":"adaptation"},{"en":"He will fly to New York next month.","cn":"他下个月要飞往纽约。","source":"adaptation"},{"en":"He'll return to London the week after next.","cn":"他下下个星期返回伦敦。","source":"adaptation"}],"grammar":"will + 动词原形表示将来，缩写 he'll；时间轴：last week 上周 → next week 下周 → the week after next 下下周。","tip":"乘飞机去某地说 fly to...，非常形象；return to... 返回某地。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Nigel is our new next-door neighbour.","cn":"奈杰尔是我们新搬来的隔壁邻居。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's a pilot.","cn":"他是个飞行员。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He was in the R.A.F.","cn":"他曾在皇家空军任职。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He will fly to New York next month.","cn":"下个月他将飞往纽约。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The month after next he'll fly to Tokyo.","cn":"再下个月他将飞往东京。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"At the moment, he's in Madrid. He flew to Spain a week ago.","cn":"现在他在马德里。他是一个星期以前飞往西班牙的。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He'll return to London the week after next.","cn":"再下个星期他将返回伦敦。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He's only forty-one years old, and he has already been to nearly every country in the world.","cn":"他只有41岁，但他几乎已经去过世界上所有的国家。","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Nigel is a very lucky man. But his wife isn't very lucky. She usually stays at home!","cn":"奈杰尔是个很幸运的人，但他的妻子运气不很好，她通常呆在家里！","source":"adaptation","pdfPage":193,"printedPage":189,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"will：将来的车票","chat":"will + 动词原形 = 将来做某事：He will fly to New York. 缩写成 he'll。时间轴背下来：last week 上周 → next month 下个月 → the week after next 下下周。","formula":"主语 + will + 动词原形（将要……）","examples":[{"en":"He will fly to New York next month.","cn":"他下个月将飞往纽约。","source":"supplement"},{"en":"He'll return to London the week after next.","cn":"他下下周回伦敦。","source":"supplement"},{"en":"He has already been to nearly every country.","cn":"他几乎已经去过每个国家。","source":"supplement"}],"watch":"fly to… 就是「飞去……」，return to… 是「回到……」——to 后面跟地点！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"He will ___ to New York next month.","opts":["fly","flew","flies","flying"],"a":"fly","why":"will + 动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"He's only forty-one years ___.","opts":["old","age","years","young"],"a":"old","why":"…years old 固定说法。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"奈杰尔的职业是什么？","opts":["飞行员","医生","教师","售票员"],"a":"飞行员","hint":"He's a pilot.","why":"曾在美国空军? 不——皇家空军（R.A.F.）。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"奈杰尔现在在哪儿？","opts":["马德里","纽约","东京","伦敦"],"a":"马德里","hint":"At the moment, he's in Madrid.","why":"一周前飞去了西班牙。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":193,"printedPage":189,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":94,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":93},{"id":95,"title":"Tickets, please.","titleCn":"请把车票拿出来。","kind":"text","words":[{"en":"return ticket","ipa":"/rɪˈtɜːn ˈtɪkɪt/","cn":"n. 来回票，往返票","source":"supplement"},{"en":"platform","ipa":"/ˈplætfɔːm/","cn":"n. 站台，月台","source":"supplement"},{"en":"plenty","ipa":"/ˈplenti/","cn":"n. 充足（plenty of 大量）","source":"supplement"},{"en":"bar","ipa":"/bɑː/","cn":"n. 酒吧","source":"supplement"},{"en":"station","ipa":"/ˈsteɪʃn/","cn":"n. 车站","source":"supplement"},{"en":"catch","ipa":"/kætʃ/","cn":"v. 赶上；抓住","source":"supplement"},{"en":"train","ipa":"/treɪn/","cn":"n. 火车","source":"supplement"},{"en":"miss","ipa":"/mɪs/","cn":"v. 错过；未赶上","source":"supplement"},{"en":"miss","ipa":"/mɪs/","cn":"v. 错过；未赶上","source":"supplement"},{"en":"had better","ipa":"/hæd ˈbetə/","cn":"phr. 最好（做某事）","source":"supplement"}],"patterns":[{"en":"Two return tickets to London, please.","cn":"请买两张去伦敦的来回票。","source":"adaptation"},{"en":"What time will the next train leave?","cn":"下一班火车几点开？","source":"adaptation"},{"en":"We had better go back to the station now.","cn":"我们现在最好回到车站去。","source":"adaptation"}],"grammar":"had better + 动词原形表示“最好……”，没有人称变化；will 问将来时刻：What time will...?","tip":"plenty of 可接复数或不可数名词：plenty of time / plenty of books；赶火车 catch the train，误车 miss the train.","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Two return tickets to London, please.","cn":"请买两张去伦敦的来回票。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What time will the next train leave?","cn":"下一班火车几点开？","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"At nineteen minutes past eight.","cn":"8点19分。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Which platform?","cn":"在哪个站台？","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Platform Two. Over the bridge.","cn":"2号站台，过桥去。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We've got plenty of time.","cn":"我们的时间还很充裕。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's only three minutes past eight.","cn":"现在才8点3分。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Let's go and have a drink. There's a bar next door to the station.","cn":"我们去喝点什么吧，车站旁边有一个酒吧。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We had better go back to the station now, Ken.","cn":"肯，我们现在最好回到车站去。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Tickets, please.","cn":"请出示车票。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We want to catch the eight nineteen to London.","cn":"我们要赶8点19分去伦敦的那班车。","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"You've just missed it!","cn":"你们刚好错过了！","source":"adaptation","pdfPage":197,"printedPage":193,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"had better：最好做……","chat":"had better + 动词原形 = 「最好做……」，谁用都不变形：We had better go.（我们最好走）。问将来的时间点：What time will…?","formula":"had better + 动词原形 = 最好…… ｜ What time will…?","examples":[{"en":"What time will the next train leave?","cn":"下一班火车几点开？","source":"supplement"},{"en":"We had better go back to the station now.","cn":"我们现在最好回车站去。","source":"supplement"},{"en":"We've got plenty of time.","cn":"我们的时间还很充裕。","source":"supplement"}],"watch":"had better 缩写成 'd better：We'd better hurry!（我们最好快点！）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Two ___ tickets to London, please.","opts":["return","returns","returning","returned"],"a":"return","why":"return ticket 来回票。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"We had ___ go back to the station now.","opts":["better","best","good","well"],"a":"better","why":"had better + 动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"下一班火车几点开？","opts":["8点19分","8点整","8点半","9点整"],"a":"8点19分","hint":"At nineteen minutes past eight.","why":"8:19。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"在哪个站台？","opts":["2号站台","1号站台","3号站台","10号站台"],"a":"2号站台","hint":"Platform Two. Over the bridge.","why":"过了桥就是。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":197,"printedPage":193,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":96,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":95},{"id":97,"title":"A small blue case","titleCn":"一只蓝色的小箱子","kind":"text","words":[{"en":"describe","ipa":"/dɪˈskraɪb/","cn":"v. 描述","source":"supplement"},{"en":"zip","ipa":"/zɪp/","cn":"n. 拉链","source":"supplement"},{"en":"label","ipa":"/ˈleɪbl/","cn":"n. 标签","source":"supplement"},{"en":"handle","ipa":"/ˈhændl/","cn":"n. 提手，把手","source":"supplement"},{"en":"address","ipa":"/əˈdres/","cn":"n. 地址","source":"supplement"},{"en":"belong","ipa":"/bɪˈlɒŋ/","cn":"v. 属于（belong to）","source":"supplement"},{"en":"pence","ipa":"/pens/","cn":"n. 便士（penny 的复数）","source":"supplement"}],"patterns":[{"en":"Can you describe it, sir?","cn":"先生，您能描述一下它的样子吗？","source":"adaptation"},{"en":"It's a small blue case and it's got a zip.","cn":"是一只蓝色小箱子，上面有拉链。","source":"adaptation"},{"en":"This case doesn't belong to you!","cn":"这箱子不是您的！","source":"adaptation"}],"grammar":"have got = have：It's got a zip.（它有一个拉链）；belong to 后面接人称宾语，不能说 belong to sb's。","tip":"多个形容词修饰名词的顺序：大小 → 颜色 → 名词，如 a small blue case（一只蓝色小箱子）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"I left a suitcase on the train to London the other day.","cn":"几天前我把一只手提箱忘在开往伦敦的火车上了。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can you describe it, sir?","cn":"先生，您能描述一下它是什么样子的吗？","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's a small blue case and it's got a zip.","cn":"是只蓝色的小箱子，上面有拉链。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There's a label on the handle with my name and address on it.","cn":"箱柄上有一个标签，上面写着我的姓名和住址。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is this case yours?","cn":"这箱子是您的吗？","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, that's not mine.","cn":"不，那不是我的。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about this one? This one's got a label.","cn":"这只呢？这只箱子有标签。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Let me see it.","cn":"让我看看。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's your name and address?","cn":"您的姓名和住址？","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"David Hall, 83, Bridge Street.","cn":"大卫·霍尔，大桥街83号。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's right. D.N. Hall, 83, Bridge Street.","cn":"那就对了。D.N.霍尔，大桥街83号。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Three pounds and fifty pence, please.","cn":"请付3英镑50便士。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Here you are.","cn":"给您。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Thank you.","cn":"谢谢。","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Hey!","cn":"嘿！","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the matter?","cn":"怎么回事？","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This case doesn't belong to me! You've given me the wrong case!","cn":"这箱子不是我的！您给错了！","source":"adaptation","pdfPage":201,"printedPage":197,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"have got 与 belong to","chat":"have got 就是 have：It's got a zip.（它带拉链）。「属于某人」用 belong to：This case doesn't belong to me.（这箱子不是我的）。描述东西时形容词有排队规则：大小 → 颜色 → 名词。","formula":"a + 大小 + 颜色 + 名词：a small blue case ｜ belong to + 人","examples":[{"en":"It's a small blue case and it's got a zip.","cn":"是只蓝色小箱子，带拉链。","source":"supplement"},{"en":"Can you describe it?","cn":"您能描述一下吗？","source":"supplement"},{"en":"This case doesn't belong to me!","cn":"这箱子不是我的！","source":"supplement"}],"watch":"belong to 后面跟人或 me/him：belong to me ✓ belong to my ❌！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"It's got ___ zip.","opts":["a","an","the","不填"],"a":"a","why":"a zip 一条拉链。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"This case doesn't belong ___ you!","opts":["to","at","for","with"],"a":"to","why":"belong to 固定搭配。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"丢失的箱子是什么样子？","opts":["带拉链的蓝色小箱子","红色大箱子","棕色大箱子","黑色小包"],"a":"带拉链的蓝色小箱子","hint":"a small blue case and it's got a zip","why":"蓝色小箱子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"取箱子要付多少钱？","opts":["3英镑50便士","35英镑","53英镑","3英镑5便士"],"a":"3英镑50便士","hint":"Three pounds and fifty pence, please.","why":"结果拿错了箱子！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":201,"printedPage":197,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":98,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":97},{"id":99,"title":"Ow!","titleCn":"啊哟！","kind":"text","words":[{"en":"slip","ipa":"/slɪp/","cn":"v. 滑倒，滑了一跤","source":"supplement"},{"en":"fall","ipa":"/fɔːl/","cn":"v. 摔倒，落下（fell）","source":"supplement"},{"en":"downstairs","ipa":"/ˌdaʊnˈsteəz/","cn":"adv. 在楼下，往楼下","source":"supplement"},{"en":"hurt","ipa":"/hɜːt/","cn":"v. 伤害，使受伤（原形、过去式同形）","source":"supplement"},{"en":"back","ipa":"/bæk/","cn":"n. 背，背部","source":"supplement"},{"en":"stand up","ipa":"/ˈstænd ʌp/","cn":"phr. 站起来","source":"supplement"},{"en":"help","ipa":"/help/","cn":"v. 帮助","source":"supplement"},{"en":"sure","ipa":"/ʃʊə/","cn":"adj. 确信的","source":"supplement"},{"en":"X-ray","ipa":"/ˈeks reɪ/","cn":"n. X 光透视","source":"supplement"}],"patterns":[{"en":"I slipped and fell downstairs.","cn":"我滑了一跤，从楼梯上摔了下来。","source":"adaptation"},{"en":"Have you hurt yourself?","cn":"你摔伤了没有？","source":"adaptation"},{"en":"I'm sure that you need an X-ray.","cn":"我看你需要拍一张X光片。","source":"adaptation"}],"grammar":"hurt yourself 用反身代词作宾语；have hurt 是 hurt 的现在完成时（hurt 三态同形：hurt-hurt-hurt）。","tip":"滑倒三步曲：slip（滑）→ fall（摔）→ hurt（受伤）；I'm sure (that) + 从句表示“我确信……”。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Ow!","cn":"啊哟！","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What's the matter, Andy?","cn":"怎么了，安迪？","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I slipped and fell downstairs.","cn":"我滑了一跤，从楼梯上摔了下来。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Have you hurt yourself?","cn":"你摔伤了没有？","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I have. I think that I've hurt my back.","cn":"是啊，摔伤了。我想我把背摔坏了。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Try and stand up. Can you stand up? Here. Let me help you.","cn":"试着站起来。你能站起来吗？来，我帮你。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm sorry, Lucy. I'm afraid that I can't get up.","cn":"对不起，露西，恐怕我站不起来。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I think that the doctor had better see you. I'll telephone Dr. Carter.","cn":"我想最好还是请医生来给你看一看。我去给卡特医生打电话。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The doctor says that he will come at once. I'm sure that you need an X-ray.","cn":"医生说他马上就来。我看你需要拍一张X光片。","source":"adaptation","pdfPage":205,"printedPage":201,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"反身代词与三态同形","chat":"动作落在自己身上，要用反身代词：hurt yourself（伤到你自己）。hurt 这个词三态同形：hurt-hurt-hurt，过去式不用变！「我确信……」：I'm sure (that)…","formula":"hurt oneself 伤到自己 ｜ I'm sure (that) + 句子","examples":[{"en":"Have you hurt yourself?","cn":"你伤到自己了吗？","source":"supplement"},{"en":"I think that I've hurt my back.","cn":"我想我把背摔伤了。","source":"supplement"},{"en":"I'm sure that you need an X-ray.","cn":"我看你需要拍张X光片。","source":"supplement"}],"watch":"三态同形小家族：hurt / hit / cut——过去式和原形长得一模一样！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I think that I've hurt my ___.","opts":["back","backs","backing","backed"],"a":"back","why":"back 背部。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"___ and stand up.","opts":["Try","Tries","Trying","Tried"],"a":"Try","why":"祈使句用动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"安迪怎么了？","opts":["滑倒摔下楼梯","被车撞了","骑车摔倒","伤了手"],"a":"滑倒摔下楼梯","hint":"I slipped and fell downstairs.","why":"Ow! 的原因。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"露西认为安迪需要什么？","opts":["拍X光片","看牙医","买新外套","吃药"],"a":"拍X光片","hint":"I'm sure that you need an X-ray.","why":"医生也这么说。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":205,"printedPage":201,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":100,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":99},{"id":101,"title":"A card from Jimmy","titleCn":"吉米的明信片","kind":"text","words":[{"en":"Scotland","ipa":"/ˈskɒtlənd/","cn":"n. 苏格兰","source":"supplement"},{"en":"card","ipa":"/kɑːd/","cn":"n. 明信片；纸牌","source":"supplement"},{"en":"youth","ipa":"/juːθ/","cn":"n. 青年（Youth Hostel 青年招待所）","source":"supplement"},{"en":"hotel","ipa":"/həʊˈtel/","cn":"n. 旅馆","source":"supplement"},{"en":"association","ipa":"/əˌsəʊʃiˈeɪʃn/","cn":"n. 协会","source":"supplement"},{"en":"soon","ipa":"/suːn/","cn":"adv. 不久","source":"supplement"},{"en":"write","ipa":"/raɪt/","cn":"v. 写（wrote）","source":"supplement"}],"patterns":[{"en":"He says he's just arrived in Scotland.","cn":"他说他刚到苏格兰。","source":"adaptation"},{"en":"He says he's staying at a Youth Hostel.","cn":"他说他正住在一家青年招待所。","source":"adaptation"},{"en":"He will write a letter soon.","cn":"他很快就会写信来的。","source":"adaptation"}],"grammar":"He says (that) + 从句，用来转述别人所说的话；say 后面的 that 常可省略，从句时态跟原话保持一致。","tip":"say 强调“说”的内容，后面不直接跟人；tell 后面必须跟人：He says... ／ He tells me...","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Read Jimmy's card to me please, Mary.","cn":"请把吉米的明信片念给我听，玛丽。","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“I have just arrived in Scotland and I'm staying at a Youth Hostel.”","cn":"“我刚到苏格兰，现在住在一家青年招待所。”","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Eh?","cn":"你说什么？","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He says he's just arrived in Scotland. He says he's staying at a Youth Hostel.","cn":"他说他刚到苏格兰，他说他现在住在一家青年招待所。","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"You know he's a member of the Y.H.A.","cn":"你知道他是“青年招待所协会”的成员。","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The what?","cn":"什么协会？","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The Y.H.A., mother. The Youth Hostels Association.","cn":"“青招协”，妈妈，青年招待所协会。","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What else does he say?","cn":"他还说了些什么？","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“I'll write a letter soon. I hope you are all well.”","cn":"“我很快会写信。祝大家身体都好。”","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Is that all? He doesn't say very much, does he?","cn":"就这些吗？他没有写许多，是吗？","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He can't write very much on a card, mother.","cn":"在明信片上他写不了很多，妈妈。","source":"adaptation","pdfPage":209,"printedPage":205,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"says that：转述刚说的话","chat":"把别人说的话转告给别人，用 He says (that) + 原话。小 that 可以省略，引号也不需要了，时态跟原话保持一致。","formula":"He says (that) + 他说的内容","examples":[{"en":"He says he's just arrived in Scotland.","cn":"他说他刚到苏格兰。","source":"supplement"},{"en":"He says he's staying at a Youth Hostel.","cn":"他说他住在青年招待所。","source":"supplement"},{"en":"He says he'll write a letter soon.","cn":"他说他很快会写信来。","source":"supplement"}],"watch":"say 后面不接人；要接人说 tell：He tells me…（他告诉我……）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"He says he ___ just arrived in Scotland.","opts":["has","have","is","was"],"a":"has","why":"has arrived 现在完成时。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"He will write a letter ___.","opts":["soon","now","yet","yesterday"],"a":"soon","why":"soon 不久。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"吉米住在哪儿？","opts":["青年招待所","旅馆","朋友家","家里"],"a":"青年招待所","hint":"He says he's staying at a Youth Hostel.","why":"他是青招协成员。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"奶奶请玛丽做什么？","opts":["把明信片念给她听","写一张明信片","买份报纸","给吉米打电话"],"a":"把明信片念给她听","hint":"Read Jimmy's card to me please.","why":"奶奶想了解吉米的近况。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":209,"printedPage":205,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":102,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":101},{"id":103,"title":"The French test","titleCn":"法语考试","kind":"text","words":[{"en":"exam","ipa":"/ɪɡˈzæm/","cn":"n. 考试","source":"supplement"},{"en":"pass","ipa":"/pɑːs/","cn":"v. 及格，通过","source":"supplement"},{"en":"mark","ipa":"/mɑːk/","cn":"n. 分数","source":"supplement"},{"en":"paper","ipa":"/ˈpeɪpə/","cn":"n. 试卷；纸","source":"supplement"},{"en":"easy","ipa":"/ˈiːzi/","cn":"adj. 容易的","source":"supplement"},{"en":"enough","ipa":"/ɪˈnʌf/","cn":"adv. 足够地；adj. 足够的","source":"supplement"},{"en":"question","ipa":"/ˈkwestʃən/","cn":"n. 问题","source":"supplement"},{"en":"maths","ipa":"/mæθs/","cn":"n. 数学","source":"supplement"},{"en":"hate","ipa":"/heɪt/","cn":"v. 讨厌","source":"supplement"}],"patterns":[{"en":"How was the exam, Richard?","cn":"考试考得怎样，理查德？","source":"adaptation"},{"en":"I think I passed.","cn":"我想我及格了。","source":"adaptation"},{"en":"The English paper wasn't easy enough for me.","cn":"英语试卷对我来说不够容易。","source":"adaptation"}],"grammar":"too + 形容词（太……而不适合）；形容词 + enough（足够……），enough 要放在形容词后面；think (that) + 从句。","tip":"too hard = 难得过火（做不了），hard enough = 足够难——位置相反：too 在前，enough 在后。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"How was the exam, Richard?","cn":"考试考得怎样，理查德？","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Not too bad.","cn":"还不错。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I think I passed in English and Mathematics.","cn":"我想我的英语和数学及格了。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The questions were very easy.","cn":"题目很容易。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"How about you, Gary?","cn":"加里，你怎么样？","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The English and Maths papers weren't easy enough for me.","cn":"英语和数学试题对我来说不很容易。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I hope I haven't failed.","cn":"我希望自己没有不及格。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I think I failed the French paper.","cn":"我想我的法语没及格。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I could answer sixteen of the questions.","cn":"我能回答其中的16道题。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They were very easy.","cn":"这些题很容易。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"But I couldn't answer the rest.","cn":"但我回答不出其余的题。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"They were too difficult for me.","cn":"那些题对我来说太难了。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Oh, cheer up! Perhaps we didn't do too badly.","cn":"哦，振作一点！也许我们不会考得太糟。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The man next to me wrote his name at the top of the paper.","cn":"坐在我旁边的那个人只在试卷顶端写自己的名字。","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And then he sat there and looked at it for three hours!","cn":"然后他就坐在那里盯着它看了三个小时！","source":"adaptation","pdfPage":213,"printedPage":209,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"too 与 enough：一前一后","chat":"too 和 enough 都管「程度」，位置正好相反：too + 形容词（太……而做不到），形容词 + enough（足够……）。「我认为……」用 I think (that)…","formula":"too + 形容词（太……）｜ 形容词 + enough（足够……）","examples":[{"en":"The paper wasn't easy enough for me.","cn":"试卷对我来说不够容易。","source":"supplement"},{"en":"They were too difficult for me.","cn":"它们对我来说太难了。","source":"supplement"},{"en":"I think I passed.","cn":"我想我及格了。","source":"supplement"}],"watch":"enough 永远跟在形容词后面：easy enough ✓ enough easy ❌！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I think I ___ in English and Mathematics.","opts":["passed","pass","passing","passs"],"a":"passed","why":"过去时 passed。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"The questions were not difficult ___ for me.","opts":["enough","too","very","much"],"a":"enough","why":"形容词 + enough，enough 后置。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"有一门考试有人觉得自己没及格，是哪一门？","opts":["法语","英语","数学","音乐"],"a":"法语","hint":"I think I failed the French paper.","why":"法语试卷太难了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"坐在旁边的人三个小时做了什么？","opts":["盯着试卷上的名字看","睡觉","奋笔疾书","哭"],"a":"盯着试卷上的名字看","hint":"he sat there and looked at it for three hours!","why":"课文的幽默结尾！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":213,"printedPage":209,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":104,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":103},{"id":105,"title":"Full of mistakes","titleCn":"错误百出","kind":"text","words":[{"en":"spell","ipa":"/spel/","cn":"v. 拼写（spelt）","source":"supplement"},{"en":"intelligently","ipa":"/ɪnˈtelɪdʒəntli/","cn":"adv. 聪明地","source":"supplement"},{"en":"mistake","ipa":"/mɪˈsteɪk/","cn":"n. 错误","source":"supplement"},{"en":"correct","ipa":"/kəˈrekt/","cn":"v. 改正；adj. 正确的","source":"supplement"},{"en":"present","ipa":"/ˈpreznt/","cn":"n. 礼物","source":"supplement"},{"en":"dictionary","ipa":"/ˈdɪkʃənri/","cn":"n. 词典","source":"supplement"}],"patterns":[{"en":"I want her to type this letter again.","cn":"我要她把这封信再打一遍。","source":"adaptation"},{"en":"You've made seventeen mistakes.","drill":true,"cn":"你有十七处错误。","source":"supplement"},{"en":"Here's a present for you.","cn":"这是送给你的礼物。","source":"adaptation"}],"grammar":"want sb to do sth 要某人做某事；make a mistake 犯错误（复数 make mistakes）。","tip":"记住结构：I want you to spell it. —— to 后面的动作才是让对方做的。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Where's Sandra, Bob? I want her.","cn":"鲍勃，桑德拉在哪儿？我要她。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you want to see her?","cn":"您要见她吗？","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I do. I want her to come to my office. Tell her to come at once.","cn":"是的。我要她到我的办公室来，叫她马上就来。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Did you want to see me, sir?","cn":"您找我，先生？","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Ah, yes, Sandra. How do you spell “intelligent”? Can you tell me?","cn":"啊，是的，桑德拉。intelligent 这个词怎样拼写？你能告诉我吗？","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I-N-T-E-L-L-I-G-E-N-T.","cn":"I-N-T-E-L-L-I-G-E-N-T。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's right. You've typed it with only one “L”. This letter's full of mistakes. I want you to type it again.","cn":"对了。可你只打了1个L。这封信里错误百出，我要你重打一遍。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I'll do that. I'm sorry about that.","cn":"是，我重打。对此我感到很抱歉。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"And here's a little present for you.","cn":"这里有一件小礼物送你。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What is it?","cn":"是什么？","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's a dictionary. I hope it'll help you.","cn":"是本词典。我希望它能对你有所帮助。","source":"adaptation","pdfPage":217,"printedPage":213,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"want sb to do sth","chat":"要「某人去做某事」，公式是 want + 人 + to + 动词原形：I want her to come to my office.（我要她来我办公室）。「犯错误」固定说 make a mistake。","formula":"want + 人 + to + 动词原形（要某人做……）","examples":[{"en":"I want her to type this letter again.","cn":"我要她把这封信再打一遍。","source":"supplement"},{"en":"Tell her to come at once.","cn":"叫她马上来。","source":"supplement"},{"en":"You've made seventeen mistakes.","cn":"你犯了17处错误。","source":"supplement"}],"watch":"to 后面的动作是「对方」做的：I want you to spell it. 是要「你」来拼，不是我拼！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"I want her ___ this letter again.","opts":["to type","type","typing","typed"],"a":"to type","why":"want sb to do sth。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"How do you ___ intelligent?","opts":["spell","spell to","spelling","spelt to"],"a":"spell","why":"问拼写用 spell。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"老板送了桑德拉什么礼物？","opts":["一本词典","一个书架","一件貂皮大衣","一支钢笔"],"a":"一本词典","hint":"It's a dictionary. I hope it'll help you.","why":"帮她少犯拼写错误。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"信里有多少处错误？","opts":["17处","7处","70处","16处"],"a":"17处","hint":"You've made seventeen mistakes.","why":"所以要从头再打一遍。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":217,"printedPage":213,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":106,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":105},{"id":107,"title":"It's too small.","titleCn":"太小了。","kind":"text","words":[{"en":"madam","ipa":"/ˈmædəm/","cn":"n. 夫人，女士（尊称）","source":"supplement"},{"en":"pretty","ipa":"/ˈprɪti/","cn":"adj. 漂亮的","source":"supplement"},{"en":"suit","ipa":"/sjuːt/","cn":"v. 适合；n. 西装","source":"supplement"},{"en":"short","ipa":"/ʃɔːt/","cn":"adj. 短的","source":"supplement"},{"en":"long","ipa":"/lɒŋ/","cn":"adj. 长的","source":"supplement"},{"en":"prettier","ipa":"/ˈprɪtiə/","cn":"adj. 更漂亮的","source":"supplement"},{"en":"smaller","ipa":"/ˈsmɔːlə/","cn":"adj. 更小的","source":"supplement"},{"en":"bigger","ipa":"/ˈbɪɡə/","cn":"adj. 更大的","source":"supplement"}],"patterns":[{"en":"Do you like this dress, madam?","cn":"这件连衣裙您喜欢吗，夫人？","source":"adaptation"},{"en":"I'm afraid it's too small for me.","cn":"恐怕它对我来说太小了。","source":"adaptation"},{"en":"This one's prettier than that one.","drill":true,"cn":"这件比那件更漂亮。","source":"supplement"}],"grammar":"比较级：短形容词加 -er，than 引出比较对象；too + 形容词 + for sb 表示“对某人来说太……”。","tip":"变尾规则：pretty→prettier（y 变 i），big→bigger（双写 g），long→longer（直接加）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you like this dress, madam?","cn":"这件连衣裙您喜欢吗，夫人？","source":"adaptation","pdfPage":221,"printedPage":217,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I like the colour very much. It's a lovely dress, but it's too small for me.","cn":"我很喜欢这颜色。这是件漂亮的连衣裙，可是对我来说太小了。","source":"adaptation","pdfPage":221,"printedPage":217,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about this one? It's a lovely dress. It's very smart. Short skirts are in fashion now. Would you like to try it?","cn":"这件怎么样？这是件漂亮的连衣裙，非常时髦。短裙现在很流行。您愿意试一试吗？","source":"adaptation","pdfPage":221,"printedPage":217,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"All right.","cn":"好的。","source":"adaptation","pdfPage":221,"printedPage":217,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid this green dress is too short as well.","cn":"恐怕这件绿连衣裙也太小了。","source":"adaptation","pdfPage":221,"printedPage":217,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"比较级：谁更……","chat":"比较两个东西，用比较级：短形容词 + er + than。pretty 变 y 为 i 加 er：prettier；big 双写 g：bigger。too…for me = 对我来说太……","formula":"A + 形容词er + than + B（A 比 B 更……）","examples":[{"en":"It's a lovely dress, but it's too small for me.","cn":"裙子很漂亮，但我穿太小。","source":"supplement"},{"en":"Short skirts are in fashion now.","cn":"现在流行短裙。","source":"supplement"},{"en":"This one's prettier than that one.","cn":"这件比那件更漂亮。","source":"supplement"}],"watch":"变尾三规则：y→ier（pretty→prettier）、双写（big→bigger）、直接加（long→longer）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"This one's ___ than that one.","opts":["prettier","prettiest","pretty","more pretty"],"a":"prettier","why":"pretty 变比较级：prettier。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"It's too small ___ me.","opts":["for","to","at","with"],"a":"for","why":"too…for sb 对某人来说太……","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"女士为什么不买第一条连衣裙？","opts":["太小了","太长了","不喜欢颜色","太贵了"],"a":"太小了","hint":"it's too small for me","why":"颜色她很喜欢，只是尺码小。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"现在流行什么？","opts":["短裙","长裙","蓝裙子","大帽子"],"a":"短裙","hint":"Short skirts are in fashion now.","why":"店员这样推荐。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":221,"printedPage":217,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":108,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":107},{"id":109,"title":"A good idea","titleCn":"好主意","kind":"text","words":[{"en":"idea","ipa":"/aɪˈdɪə/","cn":"n. 主意","source":"supplement"},{"en":"teaspoonful","ipa":"/ˈtiːspuːnfʊl/","cn":"n. 一茶匙的量","source":"supplement"},{"en":"less","ipa":"/les/","cn":"adj. 较少的（little 的比较级）","source":"supplement"},{"en":"a few","ipa":"/ə fjuː/","cn":"phr. 几个（修饰复数名词）","source":"supplement"},{"en":"pity","ipa":"/ˈpɪti/","cn":"n. 遗憾","source":"supplement"},{"en":"instead","ipa":"/ɪnˈsted/","cn":"adv. 代替，而是","source":"supplement"},{"en":"advice","ipa":"/ədˈvaɪs/","cn":"n. 建议，忠告（不可数）","source":"supplement"},{"en":"milk","ipa":"/mɪlk/","cn":"n. 牛奶","source":"supplement"}],"patterns":[{"en":"Shall I make some coffee, Jane?","cn":"我来煮点咖啡好吗，简？","source":"adaptation"},{"en":"That's a good idea.","cn":"这是个好主意。","source":"adaptation"},{"en":"Just a little, please.","cn":"只要一点点。","source":"adaptation"}],"grammar":"Shall I...? 用来提出建议或主动帮忙；a little + 不可数名词，a few + 复数名词。","tip":"主动帮忙最地道的开头是 Shall I...?，接受说 That's a good idea.；What a pity! 真遗憾！","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Shall I make some coffee, Jane?","cn":"我来煮点咖啡好吗，简？","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's a good idea, Charlotte.","cn":"这是个好主意，夏洛特。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's ready. Do you want any milk?","cn":"咖啡好了。你要放点牛奶吗？","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Just a little, please.","cn":"请放一点吧。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What about some sugar? Two teaspoonfuls?","cn":"加些糖怎么样？两茶匙糖？","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, less than that. One and a half teaspoonfuls, please. That's enough for me.","cn":"不，再少一些。请放一勺半。对我来说已足够了。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Would you like some more?","cn":"你再来点吗？","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, please. I'd like a cigarette, too. May I have one?","cn":"好的，请再来点。我还想抽支烟，可以给我一支吗？","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Of course. I think there are a few in that box.","cn":"当然可以。我想那个盒子里还有一些。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid it's empty.","cn":"恐怕盒子是空的。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What a pity!","cn":"真遗憾！","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It doesn't matter.","cn":"没关系。","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Have a biscuit instead. Eat more and smoke less!","cn":"那就吃块饼干吧。多吃点，少抽点！","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's very good advice!","cn":"这是极好的忠告啊！","source":"adaptation","pdfPage":225,"printedPage":221,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"Shall I…? 与 a little/a few","chat":"主动提出帮忙：Shall I…?（我来……好吗？）。「一点」分两种：a little 配不可数名词（a little milk 一点牛奶），a few 配可数名词（a few biscuits 几块饼干）。","formula":"Shall I + 动词…? ｜ a little + 不可数 ／ a few + 可数","examples":[{"en":"Shall I make some coffee, Jane?","cn":"简，我来煮点咖啡好吗？","source":"supplement"},{"en":"Just a little, please.","cn":"请放一点点。","source":"supplement"},{"en":"What a pity!","cn":"真遗憾！","source":"supplement"}],"watch":"advice（建议）不可数：a piece of advice ✓ an advice ❌！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ I make some coffee?","opts":["Shall","Will","Do","Am"],"a":"Shall","why":"Shall I…? 提出建议。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Just a ___, please.（牛奶不可数）","opts":["little","few","lot","some"],"a":"little","why":"a little + 不可数名词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"简要多少糖？","opts":["一茶匙半","两茶匙","三茶匙","不要糖"],"a":"一茶匙半","hint":"One and a half teaspoonfuls, please.","why":"比两勺少一点。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"夏洛特最后给了什么建议？","opts":["多吃点，少抽点","多抽点，少吃点","多喝茶","早点睡"],"a":"多吃点，少抽点","hint":"Eat more and smoke less!","why":"烟盒空了，吃饼干代替。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":225,"printedPage":221,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":110,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":109},{"id":111,"title":"The most expensive model","titleCn":"最昂贵的型号","kind":"text","words":[{"en":"model","ipa":"/ˈmɒdl/","cn":"n. 型号；模型","source":"supplement"},{"en":"afford","ipa":"/əˈfɔːd/","cn":"v. 付得起（钱）","source":"supplement"},{"en":"deposit","ipa":"/dɪˈpɒzɪt/","cn":"n. 预付定金","source":"supplement"},{"en":"instalment","ipa":"/ɪnˈstɔːlmənt/","cn":"n. 分期付款（on instalments）","source":"supplement"},{"en":"price","ipa":"/praɪs/","cn":"n. 价格","source":"supplement"},{"en":"millionaire","ipa":"/ˌmɪljəˈneə/","cn":"n. 百万富翁","source":"supplement"},{"en":"expensive","ipa":"/ɪkˈspensɪv/","cn":"adj. 昂贵的","source":"supplement"},{"en":"pay","ipa":"/peɪ/","cn":"v. 支付（paid）","source":"supplement"},{"en":"cheap","ipa":"/tʃiːp/","cn":"adj. 便宜的","source":"supplement"}],"patterns":[{"en":"It costs five hundred pounds.","cn":"它的价格是五百英镑。","source":"adaptation"},{"en":"It's the most expensive model in the shop.","cn":"它是店里最贵的型号。","source":"adaptation"},{"en":"We can't afford all that money.","cn":"我们付不起那么多钱。","source":"adaptation"}],"grammar":"多音节形容词的比较级 / 最高级用 more / the most：less expensive, the most expensive；as good as 与……一样好。","tip":"afford 常与 can 连用：can't afford 买不起；buy ... on instalments 分期付款购买。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"I like this television very much. How much does it cost?","cn":"我非常喜欢这台电视机，请问它多少钱？","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"It's the most expensive model in the shop. It costs five hundred pounds.","cn":"这是店里最贵的型号，它的价格是500英镑。","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"That's too expensive for us. We can't afford all that money.","cn":"这对我们来说太贵了，我们付不起那么多钱。","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"This model's less expensive than that one. It's only three hundred pounds. But, of course, it's not as good as the expensive one.","cn":"这种型号的比那种要便宜些，它只要300英镑。但是，它当然没有那么贵的好。","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I don't like this model. The other model's more expensive, but it's worth the money.","cn":"我不喜欢这种型号。那种型号的价格贵些，但它物有所值。","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Can we buy it on instalments?","cn":"我们可以用分期付款的方式购买吗？","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, of course. You can pay a deposit of thirty pounds, and then fourteen pounds a month for three years.","cn":"当然可以。您可以先付30英镑定金，然后每月再付14英镑，3年付清。","source":"adaptation","pdfPage":229,"printedPage":225,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"最高级：谁最……","chat":"三个以上比高低，用最高级：多音节形容词用 the most（the most expensive 最贵的）；「不如……贵」用 less expensive。付不起说 can't afford。","formula":"the most + 形容词（最……）｜ less + 形容词 + than（不如……）","examples":[{"en":"It's the most expensive model in the shop.","cn":"它是店里最贵的型号。","source":"supplement"},{"en":"This model's less expensive than that one.","cn":"这台比那台便宜些。","source":"supplement"},{"en":"We can't afford all that money.","cn":"我们付不起那么多钱。","source":"supplement"}],"watch":"比较级 → 最高级三兄弟：more → the most；prettier → the prettiest！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"It's ___ expensive model in the shop.","opts":["the most","more","most","much most"],"a":"the most","why":"最高级 the most + 多音节形容词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"We can't ___ all that money.","opts":["afford","pay","cost","buy"],"a":"afford","why":"afford 付得起；cost 主语是物。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"最贵的型号多少钱？","opts":["500英镑","300英镑","30英镑","每月14英镑"],"a":"500英镑","hint":"It costs five hundred pounds.","why":"便宜的型号只要300镑但没那么好。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"他们可以怎么付款？","opts":["分期付款","一次付清","用支票","用现金"],"a":"分期付款","hint":"Can we buy it on instalments?","why":"先付定金再按月付。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":229,"printedPage":225,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":112,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":111},{"id":113,"title":"Small change","titleCn":"零钱","kind":"text","words":[{"en":"conductor","ipa":"/kənˈdʌktə/","cn":"n. 售票员","source":"supplement"},{"en":"fare","ipa":"/feə/","cn":"n. 车费","source":"supplement"},{"en":"note","ipa":"/nəʊt/","cn":"n. 纸币；便条","source":"supplement"},{"en":"passenger","ipa":"/ˈpæsɪndʒə/","cn":"n. 乘客","source":"supplement"},{"en":"none","ipa":"/nʌn/","cn":"pron. 一个也没有","source":"supplement"},{"en":"neither","ipa":"/ˈnaɪðə/","cn":"adv. 也不","source":"supplement"},{"en":"tramp","ipa":"/træmp/","cn":"n. 流浪汉","source":"supplement"},{"en":"get off","ipa":"/ɡet ɒf/","cn":"phr. 下（车）","source":"supplement"}],"patterns":[{"en":"Fares, please!","cn":"请买票！","source":"adaptation"},{"en":"I can't change a ten-pound note.","cn":"我找不开十英镑的钞票。","source":"adaptation"},{"en":"Neither can I.","drill":true,"cn":"我也不能。（neither 引起倒装）","source":"supplement"}],"grammar":"neither + 倒装语序（Neither can I.）表示“也不”；none 表示数量上“一个也没有”。","tip":"change 既可作动词“兑换”，也可作名词“零钱”；回应别人否定情况用 Neither have I / Neither can I。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Fares, please!","cn":"请买票！","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Trafalgar Square, please.","cn":"到特拉法加广场。","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm sorry, sir. I can't change a ten-pound note. Haven't you got any small change?","cn":"对不起，先生，我找不开10英镑的钞票。您没有零钱吗？","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I've got no small change, I'm afraid.","cn":"恐怕我没有零钱。","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Neither have I.","cn":"我也没有。","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I haven't got any either.","cn":"我也没有零钱。","source":"adaptation","pdfPage":233,"printedPage":229,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"Neither can I：我也不","chat":"回应别人的否定情况，把 Neither 提到最前面，后面的词序要「倒」过来：Neither can I.（我也不能）。none 表示「一个也没有」：I've got none.","formula":"Neither + 助动词 + 主语 = ……也不 ｜ none = 一个也没有","examples":[{"en":"I can't change a ten-pound note.","cn":"我找不开10镑的钞票。","source":"supplement"},{"en":"Neither can I.","cn":"我也找不开。","source":"supplement"},{"en":"Haven't you got any small change?","cn":"您没有零钱吗？","source":"supplement"}],"watch":"回应否定用 Neither have I / Neither can I（我也<不>……）；Me too 是回应肯定句的！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"___ can I.","opts":["Neither","So","Too","Also"],"a":"Neither","why":"回应否定用 Neither + 倒装。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"根据本课常见表达，补全原句：Haven't you got ___ small change?","opts":["any","some","many","a"],"a":"any","why":"本题按本课给出的表达选择 any；some/any 的选择还受语境影响，不能把疑问句或否定句一律当作排除 some 的依据。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"售票员做不了什么事？","opts":["找开10英镑钞票","开车","开门","停车"],"a":"找开10英镑钞票","hint":"I can't change a ten-pound note.","why":"没有零钱找。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"这位乘客要去哪儿？","opts":["特拉法加广场","国王街","伦敦桥","火车站"],"a":"特拉法加广场","hint":"Trafalgar Square, please.","why":"车费付不出零钱闹了笑话。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":233,"printedPage":229,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":114,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":113},{"id":115,"title":"Knock, knock!","titleCn":"敲敲门！","kind":"text","words":[{"en":"knock","ipa":"/nɒk/","cn":"v. 敲（门）","source":"supplement"},{"en":"everything","ipa":"/ˈevriθɪŋ/","cn":"pron. 一切事物","source":"supplement"},{"en":"quiet","ipa":"/ˈkwaɪət/","cn":"adj. 安静的","source":"supplement"},{"en":"impossible","ipa":"/ɪmˈpɒsəbl/","cn":"adj. 不可能的","source":"supplement"},{"en":"invite","ipa":"/ɪnˈvaɪt/","cn":"v. 邀请","source":"supplement"},{"en":"joke","ipa":"/dʒəʊk/","cn":"v. 开玩笑；n. 玩笑","source":"supplement"},{"en":"asleep","ipa":"/əˈsliːp/","cn":"adj. 睡着的","source":"supplement"},{"en":"anyone","ipa":"/ˈeniwʌn/","cn":"pron. 任何人","source":"supplement"}],"patterns":[{"en":"Isn't there anyone at home?","cn":"家里没有人吗？","source":"textbook","pdfPage":237,"printedPage":233,"verification":"verified","translationSource":"supplement"},{"en":"Everything's very quiet.","cn":"四周静悄悄的。","source":"textbook","pdfPage":237,"printedPage":233,"verification":"verified","translationSource":"supplement"},{"en":"There's no one at home.","cn":"家里一个人也没有。","source":"adaptation"}],"grammar":"不定代词 anyone / nobody / no one / everything / nothing 都按单数对待，谓语动词用单数；Isn't there...? 否定疑问句表示惊讶。","tip":"形容词修饰本课复合不定代词时放在后面：something nice。everyone、anything 写成一个词；no one 通常写成两个词。some/any 的选择还要看语境，疑问句并非只能用 any。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"Isn't there anyone at home?","cn":"家里没有人吗？","speaker":"HELEN","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'll knock again, Helen.","cn":"海伦，我再敲一次。","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Everything's very quiet. I'm sure there's no one at home.","cn":"毫无动静，我肯定家里没有人。","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"But that's impossible. Carol and Tom invited us to lunch. Look through the window.","cn":"但这不可能。卡罗尔和汤姆请我们来吃午饭。从窗子往里看看。","speaker":"HELEN","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Can you see anything?","cn":"你能看见什么吗？","speaker":"HELEN","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Nothing at all.","cn":"什么也看不见。","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Let's try the back door.","cn":"让我们试试后门。","speaker":"HELEN","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Look! Everyone's in the garden.","cn":"瞧！大家都在花园里呢。","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Hello, Helen. Hello, Jim.","cn":"你好，海伦。你好，吉姆。","speaker":"CAROL","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Everybody wants to have lunch in the garden. It's nice and warm out here.","cn":"大家都想在花园里吃午饭。这外面挺暖和。","speaker":"TOM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Come and have something to drink.","cn":"来喝点什么吧。","speaker":"CAROL","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Thanks, Carol. May I have a glass of beer please?","cn":"谢谢，卡罗尔。给我一杯啤酒好吗？","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Beer? There's none left. You can have some lemonade.","cn":"啤酒？全喝光了。你可以喝点柠檬水！","speaker":"CAROL","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Lemonade!","cn":"柠檬水！","speaker":"JIM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Don't believe her, Jim. She's only joking. Have some beer!","cn":"吉姆，别信她的，她只是在开玩笑。喝点啤酒吧！","speaker":"TOM","source":"textbook","pdfPage":237,"printedPage":233,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"复合不定代词都是「单数」","chat":"anyone（任何人）、nobody（没人）、everything（一切）这些词虽然意思像「很多」，但都当单数用：Everything's quiet.（一切都很安静）。修饰它们的词要放在后面。","formula":"everyone / anyone / nobody / nothing + 单数动词 ｜ 修饰语后置","examples":[{"en":"Isn't there anyone at home?","cn":"家里没有人吗？","source":"supplement"},{"en":"Everything's very quiet.","cn":"四周静悄悄的。","source":"supplement"},{"en":"Everyone's in the garden.","cn":"大家都在花园里。","source":"supplement"}],"watch":"形容词后置：something nice（好东西）。anyone 常用于疑问、否定语境，someone 也可用于期待肯定回答的问句；本课原句用 anyone，不是说所有问句都必须用它。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"根据课文原句：Isn’t there ___ at home?","opts":["anyone","someone","no one","everyone"],"a":"anyone","why":"PDF237 原句用 anyone。someone 在其他期待肯定回答的问句中也可能成立，不能仅凭“疑问句”排除它。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"___ wants to have lunch in the garden.","opts":["Everyone","All","Every","Nothing"],"a":"Everyone","why":"everyone 按单数对待。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"大家都在哪儿？","opts":["花园里","电影院","厨房","聚会上"],"a":"花园里","hint":"Everyone's in the garden.","why":"外面又好又暖和。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"汤姆说卡罗尔在做什么？","opts":["开玩笑","生气了","睡着了","说对了"],"a":"开玩笑","hint":"She's only joking.","why":"其实啤酒还有，别信她的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":237,"printedPage":233,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":116,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":115},{"id":117,"title":"Tommy's breakfast","titleCn":"汤米的早餐","kind":"text","words":[{"en":"dining room","ipa":"/ˈdaɪnɪŋ ruːm/","cn":"n. 餐厅","source":"supplement"},{"en":"coin","ipa":"/kɔɪn/","cn":"n. 硬币","source":"supplement"},{"en":"swallow","ipa":"/ˈswɒləʊ/","cn":"v. 吞下","source":"supplement"},{"en":"later","ipa":"/ˈleɪtə/","cn":"adv. 后来","source":"supplement"},{"en":"toilet","ipa":"/ˈtɔɪlət/","cn":"n. 厕所","source":"supplement"},{"en":"while","ipa":"/waɪl/","cn":"conj. 当……的时候","source":"supplement"}],"patterns":[{"en":"When my husband was going into the dining room, he dropped some coins.","cn":"我丈夫走进餐厅的时候，把一些硬币掉在了地上。","source":"adaptation"},{"en":"What were you doing while we were having breakfast?","cn":"我们吃早饭时你在干什么？","source":"adaptation"}],"grammar":"过去进行时 was/were + doing 表示过去某时正在进行的动作；when / while 引导时间状语从句。","tip":"叙事经典结构：长动作用进行时（was going into...），短动作用过去时（dropped），while 后多用进行时。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"When my husband was going into the dining room this morning, he dropped some coins on the floor.","cn":"今天早晨我丈夫走进饭厅时，把一些硬币掉在地上了。","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"There were coins everywhere.","cn":"到处都是硬币。","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We looked for them, but while we were having breakfast, Tommy found two small coins on the floor.","cn":"我们虽然找了，但我们吃早饭的时候，汤米在地板上找到了两枚小硬币。","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He put them both into his mouth. We both tried to get the coins, but it was too late. Tommy had already swallowed them!","cn":"他把这两枚硬币都放进了嘴里。我们俩都试图把硬币拿出来，但太迟了，汤米已经把硬币咽了下去！","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Late that morning, when I was doing the housework, my husband phoned me from the office.","cn":"那天晚些时候，当我正做家务时，我丈夫从办公室打来电话。","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“How's Tommy?” he asked. “I don't know,” I answered, “Tommy's been to the toilet three times this morning, but I haven't seen any coins!”","cn":"“汤米怎么样？”他问。“我不知道，”我回答说，“今天上午汤米去了3次厕所了，但我还没看到硬币！”","source":"adaptation","pdfPage":241,"printedPage":237,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"过去进行时：过去的「直播」","chat":"过去进行时 = was/were + 动词ing，表示「过去那一刻正在做」。讲故事时：长动作用进行时当背景，短动作用过去式突然打断——when/while 负责报时！","formula":"was/were + 动词ing（过去正在……）｜ when/while + 从句","examples":[{"en":"When my husband was going into the dining room, he dropped some coins.","cn":"丈夫走进饭厅时，硬币掉在了地上。","source":"supplement"},{"en":"While we were having breakfast, Tommy found two small coins.","cn":"我们吃早饭时，汤米找到了两枚硬币。","source":"supplement"}],"watch":"长动作（was going）当背景，短动作（dropped）是主角——进行时负责「画面」，过去式负责「事件」！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"When my husband ___ going into the dining room, he dropped some coins.","opts":["was","were","is","has"],"a":"was","why":"过去进行时 was going。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"Tommy had already ___ them!","opts":["swallowed","swallow","swallows","swallowing"],"a":"swallowed","why":"过去完成时 had + 过去分词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"汤米把硬币怎么了？","opts":["吞下去了","买了糖","交给了妈妈","藏起来了"],"a":"吞下去了","hint":"Tommy had already swallowed them!","why":"放进嘴里拿不出来了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"丈夫打电话时在哪儿？","opts":["办公室","家里","街上","医院"],"a":"办公室","hint":"my husband phoned me from the office","why":"他上班时打电话问汤米。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":241,"printedPage":237,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":118,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":117},{"id":119,"title":"A true story","titleCn":"一个真实的故事","kind":"text","words":[{"en":"true","ipa":"/truː/","cn":"adj. 真实的","source":"supplement"},{"en":"story","ipa":"/ˈstɔːri/","cn":"n. 故事","source":"supplement"},{"en":"happen","ipa":"/ˈhæpən/","cn":"v. 发生","source":"supplement"},{"en":"thief","ipa":"/θiːf/","cn":"n. 贼（复数 thieves）","source":"supplement"},{"en":"enter","ipa":"/ˈentə/","cn":"v. 进入","source":"supplement"},{"en":"dark","ipa":"/dɑːk/","cn":"adj. 黑暗的","source":"supplement"},{"en":"torch","ipa":"/tɔːtʃ/","cn":"n. 手电筒","source":"supplement"},{"en":"voice","ipa":"/vɔɪs/","cn":"n. 说话声，嗓音","source":"supplement"},{"en":"parrot","ipa":"/ˈpærət/","cn":"n. 鹦鹉","source":"supplement"}],"patterns":[{"en":"It happened to a friend of mine a year ago.","cn":"这是一年前发生在我一个朋友身上的事。","source":"adaptation"},{"en":"Suddenly, they heard a voice behind them.","cn":"突然，他们听到身后有声音。","source":"adaptation"},{"en":"The thieves ran away as quickly as they could.","cn":"小偷们拼命地跑掉了。","source":"adaptation"}],"grammar":"happen to sb 发生在某人身上（不及物动词，没有被动语态）；as ... as one can/could 表示“尽可能……”。","tip":"讲故事的经典开头：It happened to...；吓跑小偷的正是鹦鹉 Henry 那句 What's up?","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you like stories? I want to tell you a true story. It happened to a friend of mine a year ago.","cn":"你喜欢听故事吗？我要告诉你一个真实的故事。这是一年前发生在我一个朋友身上的事。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"While my friend, George, was reading in bed, two thieves climbed into his kitchen.","cn":"当我的朋友乔治在床上看书时，两个小偷爬进了他的厨房。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"After they went into the house, they went into the dining room. It was very dark, so they turned on a torch.","cn":"他们进了屋子后，走进了饭厅。饭厅非常黑暗，于是他们打开了手电筒。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Suddenly, they heard a voice behind them. “What's up? What's up?” someone called.","cn":"突然，他们听到身后有声音。“什么事？什么事？”有人喊叫着。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The thieves dropped the torch and ran away as quickly as they could.","cn":"小偷扔下了手电筒，飞快地逃走了。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"George heard the noise and came downstairs quickly.","cn":"乔治听到了响声，迅速地下了楼。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"He turned on the light, but he couldn't see anyone. The thieves had already gone.","cn":"他打开了灯，但看不到一个人，小偷们已经逃走了。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"But George's parrot, Henry, was still there.","cn":"但是乔治的鹦鹉亨利还在那里。","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“What's up, George?” it called. “Nothing, Henry,” George said and smiled. “Go back to sleep.”","cn":"“什么事，乔治？”鹦鹉喊着。“没事，亨利。”乔治笑着说，“接着睡觉吧。”","source":"adaptation","pdfPage":245,"printedPage":241,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"happen to 与 as…as","chat":"happen（发生）后面用 to 接人：It happened to me.（发生在我身上）。「尽可能快」= as quickly as they could（as…as 中间放副词）。happen 没有被动语态！","formula":"happen to sb 发生在某人身上 ｜ as + 副词 + as one can = 尽可能……","examples":[{"en":"It happened to a friend of mine a year ago.","cn":"这是一年前发生在我朋友身上的事。","source":"supplement"},{"en":"They ran away as quickly as they could.","cn":"他们飞快地逃走了。","source":"supplement"},{"en":"What's up?","cn":"怎么回事？","source":"supplement"}],"watch":"happen 不能用被动：It was happened ❌ → It happened ✓！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"The thieves ran away as ___ as they could.","opts":["quickly","quick","quicker","quickest"],"a":"quickly","why":"修饰 ran 用副词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"It ___ to a friend of mine.","opts":["happened","happen","happening","happens"],"a":"happened","why":"一年前的事，用过去式。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"是谁吓跑了小偷？","opts":["一只鹦鹉","警察","乔治的狗","一位邻居"],"a":"一只鹦鹉","hint":"George's parrot, Henry","why":"鹦鹉喊 What's up? 小偷以为有人。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"小偷逃跑时丢下了什么？","opts":["手电筒","钱","鞋子","包"],"a":"手电筒","hint":"The thieves dropped the torch","why":"慌忙逃走顾不上了。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":245,"printedPage":241,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":120,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":119},{"id":121,"title":"The man in a hat","titleCn":"戴帽子的男士","kind":"text","words":[{"en":"customer","ipa":"/ˈkʌstəmə/","cn":"n. 顾客","source":"supplement"},{"en":"forget","ipa":"/fəˈɡet/","cn":"v. 忘记（forgot）","source":"supplement"},{"en":"manager","ipa":"/ˈmænɪdʒə/","cn":"n. 经理","source":"supplement"},{"en":"serve","ipa":"/sɜːv/","cn":"v. 接待（顾客），服务","source":"supplement"},{"en":"counter","ipa":"/ˈkaʊntə/","cn":"n. 柜台","source":"supplement"},{"en":"recognize","ipa":"/ˈrekəɡnaɪz/","cn":"v. 认出","source":"supplement"},{"en":"hour","ipa":"/ˈaʊə/","cn":"n. 小时","source":"supplement"}],"patterns":[{"en":"I forgot to take them with me.","cn":"我忘了把它们带走。","source":"textbook","pdfPage":249,"printedPage":245,"verification":"verified","translationSource":"supplement"},{"en":"Who served you, sir?","cn":"先生，是谁接待您的？","source":"textbook","pdfPage":249,"printedPage":245,"verification":"verified","translationSource":"supplement"},{"en":"The lady who is standing behind the counter.","cn":"站在柜台后面的那位女士。","source":"textbook","pdfPage":249,"printedPage":245,"verification":"verified","translationSource":"supplement"}],"grammar":"forget to do sth 忘记去做某事；定语从句补充说明人或物：the lady who is standing behind the counter（站在柜台后面的女士）。","tip":"本课用 who/that 说明人，用 which 说明物；从句紧跟它所修饰的名词。戴帽子的是顾客，不是接待他的卡罗琳。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}],"teachingSource":"supplement","text":[{"en":"I bought two expensive dictionaries here half an hour ago, but I forgot to take them with me.","cn":"半小时前我在这里买了两本很贵的词典，但忘了带走。","speaker":"CUSTOMER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Who served you, sir?","cn":"先生，是谁接待您的？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"The lady who is standing behind the counter.","cn":"站在柜台后面的那位女士。","speaker":"CUSTOMER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Which books did you buy?","cn":"您买的是哪几本书？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"The books which are on the counter.","cn":"柜台上的那些书。","speaker":"CUSTOMER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Did you serve this gentleman half an hour ago, Caroline?","cn":"卡罗琳，半小时前是你接待的这位先生吗？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"He says he's the man who bought these books.","cn":"他说他就是买这些书的人。","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I can't remember.","cn":"我想不起来了。","speaker":"CAROLINE","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"The man who I served was wearing a hat.","cn":"我接待的那个人戴着帽子。","speaker":"CAROLINE","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Have you got a hat, sir?","cn":"先生，您有帽子吗？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, I have.","cn":"是的，我有。","speaker":"CUSTOMER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Would you put it on, please?","cn":"请您把帽子戴上好吗？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"All right.","cn":"好的。","speaker":"CUSTOMER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Is this the man that you served, Caroline?","cn":"卡罗琳，这就是你接待的那个人吗？","speaker":"MANAGER","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes.","cn":"是的。","speaker":"CAROLINE","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I recognize him now.","cn":"我现在认出他来了。","speaker":"CAROLINE","pdfPage":249,"printedPage":245,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"定语从句：贴在名词后的说明","chat":"想给名词加一段说明（……的那个人/东西），用定语从句。本课用 who/that 说明人、which 说明物：The lady who is standing behind the counter.（站在柜台后面的女士。）接待顾客的是卡罗琳，戴帽子的是顾客。","formula":"本课：人 + who/that + 说明 ｜ 物 + which + 说明","examples":[{"en":"Who served you, sir?","cn":"先生，是谁接待您的？","source":"supplement"},{"en":"The lady who is standing behind the counter.","cn":"站在柜台后面的那位女士。","source":"supplement"},{"en":"The books which are on the counter.","cn":"柜台上的那些书。","source":"supplement"}],"watch":"从句是名词的「小尾巴」，必须紧贴在名词后面，不能甩到句尾哦！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},"ex":{"g":[{"q":"The lady ___ is standing behind the counter.","opts":["who","which","what","whose"],"a":"who","why":"这里用 who 引导说明 lady 的定语从句；接待顾客的是站在柜台后的女士。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""},{"q":"I forgot ___ them with me.","opts":["to take","taking","took","take"],"a":"to take","why":"forget to do 忘记去做。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""}],"c":[{"q":"顾客买了什么？","opts":["两本很贵的词典","两顶帽子","几本杂志","两本相册"],"a":"两本很贵的词典","hint":"I bought two expensive dictionaries","why":"顾客买了两本很贵的词典，但忘了带走。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},{"q":"卡罗琳在顾客做什么后认出了他？","opts":["戴上帽子","买一顶新帽子","站到柜台后","打电话"],"a":"戴上帽子","hint":"Would you put it on, please? / I recognize him now.","why":"卡罗琳记得自己接待的人戴着帽子；顾客戴上帽子后，她才认出他。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":249,"printedPage":245,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}}]}},{"id":122,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":121},{"id":123,"title":"A trip to Australia","titleCn":"澳大利亚之行","kind":"text","words":[{"en":"Australia","ipa":"/ɒˈstreɪliə/","cn":"n. 澳大利亚","source":"supplement"},{"en":"during","ipa":"/ˈdjʊərɪŋ/","cn":"prep. 在……期间","source":"supplement"},{"en":"trip","ipa":"/trɪp/","cn":"n. 旅行","source":"supplement"},{"en":"travel","ipa":"/ˈtrævl/","cn":"v. 旅行","source":"supplement"},{"en":"offer","ipa":"/ˈɒfə/","cn":"v. 提供","source":"supplement"},{"en":"guess","ipa":"/ɡes/","cn":"v. 猜","source":"supplement"},{"en":"grow","ipa":"/ɡrəʊ/","cn":"v. 长，留（胡子）（grew）","source":"supplement"},{"en":"beard","ipa":"/bɪəd/","cn":"n. （下巴上的）胡须","source":"supplement"},{"en":"shave","ipa":"/ʃeɪv/","cn":"v. 刮（胡子）","source":"supplement"}],"patterns":[{"en":"This is a photograph I took during my trip to Australia.","cn":"这是我在澳大利亚旅行期间拍的一张照片。","source":"textbook","pdfPage":253,"printedPage":249,"verification":"verified","translationSource":"supplement"},{"en":"Do you know the man who's standing there?","drill":true,"cn":"你认识站在那儿的那个人吗？","source":"supplement"},{"en":"I grew a beard during the trip, but I shaved it off when I came home.","cn":"我旅行时留了胡子，但我到家后就把它刮掉了。","source":"textbook","pdfPage":253,"printedPage":249,"verification":"verified","translationSource":"supplement"}],"grammar":"who / which 引导定语从句复习；grew a beard 留胡子，shave ... off 刮掉。","tip":"during + 名词（during the trip），while + 句子（while I was travelling）——两者都表“在……期间”。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"Look, Scott.","cn":"看，斯科特。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"This is a photograph I took during my trip to Australia.","cn":"这是我在澳大利亚旅行期间拍的一张照片。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Let me see it, Mike.","cn":"让我看看，迈克。","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"This is a good photograph.","cn":"这张照片拍得很好。","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Who are these people?","cn":"这些人是谁？","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"They're people I met during the trip.","cn":"他们是我在旅行期间认识的人。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That's the ship we travelled on.","cn":"那是我们乘坐的船。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"What a beautiful ship!","cn":"多漂亮的船啊！","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Who's this?","cn":"这是谁？","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That's the man I told you about.","cn":"那就是我跟你说过的那个人。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Remember?","cn":"还记得吗？","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Ah yes.","cn":"啊，记得。","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"The one who offered you a job in Australia.","cn":"就是那个在澳大利亚给你提供工作的人。","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That's right.","cn":"对。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Who's this?","cn":"这是谁？","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Guess!","cn":"猜猜看！","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It's not you, is it?","cn":"不是你，对吧？","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That's right.","cn":"正是我。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I grew a beard during the trip, but I shaved it off when I came home.","cn":"我在旅行期间留了胡子，但回家时就把它刮掉了。","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Why did you shave it off?","cn":"你为什么把胡子刮掉？","speaker":"SCOTT","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"My wife didn't like it!","cn":"我妻子不喜欢！","speaker":"MIKE","source":"textbook","pdfPage":253,"printedPage":249,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"during 与过去式拍档","chat":"during + 名词表示「在……期间」：during the trip（旅行期间）。两个新过去式：grow→grew（grow a beard 留胡子）、shave…off（刮掉）。","formula":"during + 名词（在……期间）｜ grow a beard 留胡子 ｜ shave it off 刮掉","examples":[{"en":"This is a photograph I took during my trip to Australia.","cn":"这是我在澳大利亚旅行期间拍的一张照片。","source":"supplement"},{"en":"I grew a beard during the trip.","cn":"我旅行时留了胡子。","source":"supplement"},{"en":"But I shaved it off when I came home.","cn":"但我到家就刮掉了。","source":"supplement"}],"watch":"during + 名词，while + 句子：during the trip = while I was travelling！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"I grew a beard ___ the trip.","opts":["during","while","when","at"],"a":"during","why":"表示“在旅行期间”，during 后接名词短语 the trip；while/when 通常接表示时间的句子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"I ___ a beard during the trip.","opts":["grew","growed","grow","grown"],"a":"grew","why":"grow 不规则过去式 grew。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"旅行去了哪里？","opts":["澳大利亚","美国","中国","日本"],"a":"澳大利亚","hint":"my trip to Australia","why":"照片是旅行时拍的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"到家后他把胡子怎么了？","opts":["刮掉了","留得更长","染了色","编了起来"],"a":"刮掉了","hint":"I shaved it off when I came home.","why":"迈克说回家时刮掉了胡子，因为妻子不喜欢；照片中的胡子让斯科特一时没认出他。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":253,"printedPage":249,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":124,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":123},{"id":125,"title":"Tea for two","titleCn":"两人一起喝茶","kind":"text","words":[{"en":"terribly","ipa":"/ˈterəbli/","cn":"adv. 非常地","source":"supplement"},{"en":"dry","ipa":"/draɪ/","cn":"adj. 干燥的","source":"supplement"},{"en":"nuisance","ipa":"/ˈnjuːsns/","cn":"n. 讨厌的事或人","source":"supplement"},{"en":"mean","ipa":"/miːn/","cn":"v. 意味着","source":"supplement"},{"en":"have to","ipa":"/ˈhæftə/","cn":"phr. 不得不，必须","source":"supplement"},{"en":"needn't","ipa":"/ˈniːdnt/","cn":"phr. 不必（= need not）","source":"supplement"}],"patterns":[{"en":"Do you have to water the garden every day?","cn":"你一定要每天浇花园吗？","source":"adaptation"},{"en":"It's terribly dry.","cn":"天太干燥了。","source":"adaptation"},{"en":"You needn't water the garden now.","cn":"你现在不必浇花园了。","source":"adaptation"},{"en":"What a nuisance!","cn":"真讨厌！","source":"adaptation"}],"grammar":"have to 表示客观上的“必须”（三单 has to）；needn't 表示“不必”；mustn't 表示“千万别”（禁止），与 needn't 完全不同。","tip":"考试重点：对 Must I...? 的否定回答用 No, you needn't.（不必），不能用 mustn't；感叹句 What a + 名词！","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Can't you come in and have tea now, Peter?","cn":"彼得，你现在能进来喝茶吗？","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Not yet, dear. I must water the garden first.","cn":"还不行，亲爱的。我必须先给花园浇水。","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Do you have to water it now?","cn":"你一定得现在浇吗？","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid I do. It's terribly dry.","cn":"恐怕我得浇。这天太干燥了。","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What a nuisance!","cn":"真讨厌！","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Last summer it was very dry, too. Don't you remember? I had to water it every day.","cn":"去年夏天也是这样干燥。你记得吗？我不得不每天浇水。","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, I'll have tea ready for you when you come in.","cn":"好吧，等你进来，茶就准备好了。","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Good heavens! It's raining. That means I needn't water the garden!","cn":"天啊！下雨了。这就是说我不用给花园浇水了！","source":"adaptation","pdfPage":257,"printedPage":253,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"have to 与 needn't 再登场","chat":"have to 表示「客观上不得不」（三单变 has to）；「不必」是 needn't！再强调一次：mustn't 是「禁止」，needn't 才是「不必」，这对兄弟总在考试出现！","formula":"have to = 不得不 ｜ needn't = 不必 ｜ mustn't = 禁止","examples":[{"en":"Do you have to water it now?","cn":"你一定得现在浇吗？","source":"supplement"},{"en":"I'm afraid I do. It's terribly dry.","cn":"恐怕得浇，天太干了。","source":"supplement"},{"en":"You needn't water the garden.","cn":"你不用浇花园了。","source":"supplement"}],"watch":"感叹句公式：What a + 名词！What a nuisance!（真讨厌！）What a pity!（真遗憾！）","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Do you have ___ water the garden now?","opts":["to","for","at","in"],"a":"to","why":"have to + 动词原形。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"You ___ water the garden now.（不必）","opts":["needn't","mustn't","can't","don't"],"a":"needn't","why":"needn't = 不必。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"彼得为什么要浇花园？","opts":["天太干燥了","因为下雨","苏珊让他玩","花是新种的"],"a":"天太干燥了","hint":"It's terribly dry.","why":"去年夏天也很干。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"结尾发生了什么？","opts":["下雨了","下雪了","刮大风","出太阳"],"a":"下雨了","hint":"Good heavens! It's raining.","why":"不用浇水了，正好进来喝茶。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":257,"printedPage":253,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":126,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":125},{"id":127,"title":"A famous actress","titleCn":"著名的女演员","kind":"text","words":[{"en":"famous","ipa":"/ˈfeɪməs/","cn":"adj. 著名的","source":"supplement"},{"en":"actress","ipa":"/ˈæktrəs/","cn":"n. 女演员","source":"supplement"},{"en":"actor","ipa":"/ˈæktə/","cn":"n. 男演员","source":"supplement"},{"en":"at least","ipa":"/ət liːst/","cn":"phr. 至少","source":"supplement"},{"en":"opinion","ipa":"/əˈpɪnjən/","cn":"n. 看法，意见","source":"supplement"},{"en":"thirty","ipa":"/ˈθɜːti/","cn":"num. 三十","source":"supplement"},{"en":"forty","ipa":"/ˈfɔːti/","cn":"num. 四十","source":"supplement"}],"patterns":[{"en":"I read she's twenty-nine, but she must be at least forty.","cn":"我读到她是二十九岁，但她一定至少有四十岁了。","source":"textbook","pdfPage":261,"printedPage":257,"verification":"verified","translationSource":"supplement"},{"en":"She was a famous actress when I was still at school.","cn":"我还在上学时，她就已经是著名的女演员了。","source":"textbook","pdfPage":261,"printedPage":257,"verification":"verified","translationSource":"supplement"},{"en":"In my opinion, she's about forty.","drill":true,"cn":"依我看，她大约四十岁。","source":"supplement"}],"grammar":"must be 表示有把握的推测（“肯定是”）；in my opinion 依我看；at least 至少。","tip":"推测三档：must be 肯定是 → may be 可能是 → can't be 不可能是。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}],"teachingSource":"supplement","text":[{"en":"Can you recognize that woman, Liz?","cn":"莉兹，你能认出那个女人吗？","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I think I can, Kate.","cn":"我想我能，凯特。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It must be Karen Marsh, the actress.","cn":"她一定是女演员卡伦·马什。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I thought so.","cn":"我也这样想。","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Who's that beside her?","cn":"她旁边的人是谁？","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That must be Conrad Reeves.","cn":"那一定是康拉德·里夫斯。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Conrad Reeves, the actor?","cn":"男演员康拉德·里夫斯？","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"It can't be.","cn":"不可能是他。","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Let me have another look.","cn":"让我再看一眼。","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I think you're right!","cn":"我想你说对了！","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Isn't he her third husband?","cn":"他不是她的第三任丈夫吗？","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No. He must be her fourth or fifth.","cn":"不，他一定是她的第四任或第五任。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Doesn't Karen Marsh look old!","cn":"卡伦·马什看上去多显老啊！","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"She does, doesn't she!","cn":"是啊，不是吗！","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I read she's twenty-nine, but she must be at least forty.","cn":"我读到她是二十九岁，但她一定至少有四十岁了。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm sure she is.","cn":"我肯定她有了。","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"She was a famous actress when I was still at school.","cn":"我还在上学时，她就已经是著名的女演员了。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That was a long time ago, wasn't it?","cn":"那是很久以前的事了，不是吗？","speaker":"KATE","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Not that long ago!","cn":"没有那么久！","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm not more than twenty-nine myself.","cn":"我自己还不到三十岁呢。","speaker":"LIZ","pdfPage":261,"printedPage":257,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"must be：有把握的推测","chat":"看到证据猜年龄，用 must be（肯定是）：She must be at least forty.（她肯定至少40岁）。发表看法用 In my opinion…（依我看）。","formula":"must be = 一定是（很有把握）｜ may be = 可能是 ｜ can't be = 不可能是","examples":[{"en":"She must be at least forty.","cn":"她一定至少有四十岁了。","source":"supplement"},{"en":"I read she's twenty-nine, but she must be at least forty.","cn":"我读到她是二十九岁，但她一定至少有四十岁了。","source":"supplement"},{"en":"She was a famous actress when I was still at school.","cn":"我还在上学时，她就已经是著名的女演员了。","source":"supplement"}],"watch":"推测三档口诀：must be 肯定是 → may be 也许是 → can't be 不可能是！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},"ex":{"g":[{"q":"根据课文原句：I read she’s twenty-nine, but she ___ be at least forty.","opts":["must","may not","can","should to"],"a":"must","why":"原页用 must be at least forty，表示莉兹有把握的推测，不是已证实的真实年龄。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""},{"q":"In my ___, she's about forty.","opts":["opinion","mind","idea","thought"],"a":"opinion","why":"in my opinion 依我看。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""}],"c":[{"q":"莉兹认为那个女人是谁？","opts":["著名演员卡伦·马什","一位教师","一位医生","一位歌手"],"a":"著名演员卡伦·马什","hint":"It must be Karen Marsh, the actress.","why":"莉兹推测她是女演员卡伦·马什；场景不是在描述一张照片。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},{"q":"莉兹说她读到卡伦是多少岁？","opts":["29岁","35岁","40岁","45岁"],"a":"29岁","hint":"I read she's twenty-nine","why":"莉兹说 I read she’s twenty-nine；她自己猜至少四十岁。原页没有说明读到信息的载体。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":261,"printedPage":257,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}}]}},{"id":128,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":127},{"id":129,"title":"Seventy miles an hour","titleCn":"时速七十英里","kind":"text","words":[{"en":"wave","ipa":"/weɪv/","cn":"v. 招手","source":"supplement"},{"en":"track","ipa":"/træk/","cn":"n. 跑道，轨道","source":"supplement"},{"en":"mile","ipa":"/maɪl/","cn":"n. 英里","source":"supplement"},{"en":"overtake","ipa":"/ˌəʊvəˈteɪk/","cn":"v. 超过（overtook）","source":"supplement"},{"en":"speed limit","ipa":"/ˈspiːd ˈlɪmɪt/","cn":"n. 限速","source":"supplement"},{"en":"dream","ipa":"/driːm/","cn":"v. 做梦；n. 梦","source":"supplement"},{"en":"sign","ipa":"/saɪn/","cn":"n. 标记，牌子","source":"supplement"},{"en":"charge","ipa":"/tʃɑːdʒ/","cn":"v. 罚款；收费","source":"supplement"},{"en":"seventy","ipa":"/ˈsevnti/","cn":"num. 七十","source":"supplement"},{"en":"fine","ipa":"/faɪn/","cn":"n. 罚款","source":"supplement"}],"patterns":[{"en":"You must have been driving at seventy miles an hour.","cn":"你当时一定是以每小时70英里的速度开车。","source":"adaptation"},{"en":"I was doing eighty when I overtook you.","cn":"我超车的时候车速是每小时80英里。","source":"adaptation"},{"en":"You must have been speeding.","cn":"你当时一定是在超速行驶。","source":"adaptation"}],"grammar":"must have been + doing 对过去情况进行有把握的推测；过去进行时 was doing 描述过去某一刻正在进行的动作。","tip":"表示“以……速度”用介词 at：drive at 70 miles an hour；口语里 do 也能表示“开车速”（I was doing 80）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"You must have been driving at seventy miles an hour.","cn":"你刚才一定是以每小时70英里的速度行驶的。","source":"adaptation","pdfPage":265,"printedPage":261,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I can't have been.","cn":"我不可能开得那么快。","source":"adaptation","pdfPage":265,"printedPage":261,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I was doing eighty when I overtook you. Didn't you see the speed limit?","cn":"我以每小时80英里的速度超过你的时候，你没有见到限速牌吗？","source":"adaptation","pdfPage":265,"printedPage":261,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I'm afraid I didn't, officer. I was dreaming.","cn":"恐怕我没注意到，警官。我刚才一定是做梦了。","source":"adaptation","pdfPage":265,"printedPage":261,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"You weren't dreaming! I won't charge you this time, but you'd better not do it again!","cn":"你不是在做梦！这次我就不罚款了，但你最好不要再开这么快！","source":"adaptation","pdfPage":265,"printedPage":261,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"推测过去：must have been","chat":"推测「过去肯定发生了什么」，用 must have been / must have been doing：You must have been driving at seventy.（你当时肯定开到70迈了）。否定推测用 can't have been.","formula":"must have been…（过去一定是）｜ can't have been…（过去不可能）","examples":[{"en":"You must have been driving at seventy miles an hour.","cn":"你当时一定以每小时70英里行驶。","source":"supplement"},{"en":"I can't have been.","cn":"我不可能。","source":"supplement"},{"en":"I was doing eighty when I overtook you.","cn":"我超你车时开到80迈。","source":"supplement"}],"watch":"说「以……速度」用介词 at：drive at seventy miles an hour！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"You must have been driving ___ seventy miles an hour.","opts":["at","on","in","with"],"a":"at","why":"速度用 at。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I was ___ eighty when I overtook you.","opts":["doing","do","did","done"],"a":"doing","why":"过去进行时 was doing。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"司机的借口是什么？","opts":["刚才在做梦","牌子坏了","他是新手","路上没车"],"a":"刚才在做梦","hint":"I was dreaming.","why":"警察不信：You weren't dreaming!","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"警察决定怎么处理？","opts":["这次不罚款","吊销驾照","逮捕他","重罚他"],"a":"这次不罚款","hint":"I won't charge you this time","why":"但警告别再开快车。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":265,"printedPage":261,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":130,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":129},{"id":131,"title":"Don't be so sure!","titleCn":"别那么肯定！","kind":"text","words":[{"en":"worry","ipa":"/ˈwʌri/","cn":"v. 担忧（worry about 担心）","source":"supplement"},{"en":"Egypt","ipa":"/ˈiːdʒɪpt/","cn":"n. 埃及","source":"supplement"},{"en":"abroad","ipa":"/əˈbrɔːd/","cn":"adv. 在国外（go abroad 出国）","source":"supplement"},{"en":"sea","ipa":"/siː/","cn":"n. 海","source":"supplement"},{"en":"might","ipa":"/maɪt/","cn":"aux. 可能，也许","source":"supplement"},{"en":"spend","ipa":"/spend/","cn":"v. 度过（时光）；花钱","source":"supplement"},{"en":"look after","ipa":"/lʊk ˈɑːftə/","cn":"phr. 照看，照顾","source":"supplement"}],"patterns":[{"en":"We may go abroad.","cn":"我们可能要出国。","source":"adaptation"},{"en":"I'm not sure.","drill":true,"cn":"我不敢肯定。","source":"supplement"},{"en":"Don't be so sure!","cn":"别那么肯定！","source":"adaptation"},{"en":"My wife always worries too much.","cn":"我妻子总是忧心忡忡。","source":"adaptation"}],"grammar":"may / might + 动词原形表示“可能”；be not sure 表示不确定；worry about + 担心的事物。","tip":"might 比 may 的可能性更小、语气更弱；go abroad 出国（abroad 是副词，前面不加 to）。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Where are you going to spend your holidays this year, Tom?","cn":"汤姆，今年你们打算去哪里度假？","source":"adaptation","pdfPage":269,"printedPage":265,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We may go abroad.","cn":"我们可能出国。","source":"adaptation","pdfPage":269,"printedPage":265,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"My wife wants to go to Egypt, so I may go there. We may travel by sea.","cn":"我妻子想去埃及，因此我可能去那儿。我们可能乘船去。","source":"adaptation","pdfPage":269,"printedPage":265,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Don't be so sure!","cn":"别那么肯定！","source":"adaptation","pdfPage":269,"printedPage":265,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"We may not go anywhere. My wife always worries too much. Who's going to look after the dog?","cn":"我们可能哪里也去不成。我的妻子总是很担心。谁来照看狗呢？","source":"adaptation","pdfPage":269,"printedPage":265,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"may / might：可能性","chat":"不太确定的事用 may 或 might + 动词原形：We may go abroad.（我们可能出国）。might 比 may 把握更小。「担心……」用 worry about。abroad 是副词，前面不加 to！","formula":"may / might + 动词原形 = 可能……","examples":[{"en":"We may go abroad.","cn":"我们可能出国。","source":"supplement"},{"en":"My wife wants to go to Egypt, so I may go there.","cn":"我妻子想去埃及，所以我可能去那儿。","source":"supplement"},{"en":"My wife always worries too much.","cn":"我妻子总是忧心忡忡。","source":"supplement"}],"watch":"go abroad 出国 ✓ go to abroad ❌——abroad 前面千万不要 to！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"We ___ go abroad.（可能）","opts":["may","must","can","should"],"a":"may","why":"may 表可能性。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"My wife always ___ too much.","opts":["worries","worry","worrying","worried"],"a":"worries","why":"三单 worries。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"妻子想去哪里度假？","opts":["埃及","西班牙","日本","法国"],"a":"埃及","hint":"My wife wants to go to Egypt.","why":"所以可能去埃及。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"他们今年一定能出国吗？","opts":["不一定，「别那么肯定」","非常有把握，肯定去","机票已经订好了","他们明天就出发"],"a":"不一定，「别那么肯定」","hint":"Don't be so sure!","why":"妻子总是担心这担心那，所以可能哪里也去不成。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":269,"printedPage":265,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":132,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":131},{"id":133,"title":"Sensational news!","titleCn":"爆炸性新闻！","kind":"text","words":[{"en":"reporter","ipa":"/rɪˈpɔːtə/","cn":"n. 记者","source":"supplement"},{"en":"sensational","ipa":"/senˈseɪʃənl/","cn":"adj. 爆炸性的，耸人听闻的","source":"supplement"},{"en":"mink coat","ipa":"/ˈmɪŋk kəʊt/","cn":"n. 貂皮大衣","source":"supplement"},{"en":"wonder","ipa":"/ˈwʌndə/","cn":"v. 想知道","source":"supplement"},{"en":"interview","ipa":"/ˈɪntəvjuː/","cn":"v. 采访；n. 面试","source":"supplement"}],"patterns":[{"en":"Have you just made a new film, Miss Marsh?","cn":"马什小姐，您刚拍完一部新电影吗？","source":"adaptation"},{"en":"She said she was not going to make another.","cn":"她说她不打算再拍电影了。","source":"adaptation"},{"en":"I wonder why!","cn":"我很想知道为什么！","source":"adaptation"}],"grammar":"转述别人过去说的话：said (that) + 从句，直接引语里的 am/is going to 要变成 was going to。","tip":"say 后面不接人，tell 后面必须接人：She said (that)... ／ She told me (that)...；时态“后退一步”是转述的关键。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Have you just made a new film, Miss Marsh?","cn":"马什小姐，您刚拍完一部新电影吗？","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I have.","cn":"是的。","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Are you going to make another?","cn":"您准备再拍一部吗？","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"No, I'm not. I'm going to retire. I feel very tired. I don't want to make another film for a long time.","cn":"不，我不准备再拍了。我准备退休了。我觉得很疲惫，我很长一段时间内不打算再拍影片了。","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Let's buy a newspaper, Kate. Listen to this!","cn":"我们买份报纸吧，凯特。听听这一段！","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“Karen Marsh: Sensational News! By our reporter, Alan Jones. Miss Marsh arrived at London Airport this morning. She was wearing a mink coat and she said she was going to retire.”","cn":"“卡伦·马什：爆炸性新闻！由本报记者艾伦·琼斯报道。马什小姐今天上午到达伦敦机场，她身穿一件貂皮大衣，并说她准备退休。”","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I wonder why!","cn":"我很想知道为什么！","source":"adaptation","pdfPage":273,"printedPage":269,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"转述过去：时态后退一步","chat":"把过去说的话转述给别人，时态要「后退一步」：am/is going to → was going to。She said she was going to retire.（她说她准备退休。）say 后不接人，tell 后必须接人！","formula":"She said (that) she was going to… ｜ She told me (that)…","examples":[{"en":"Have you just made a new film, Miss Marsh?","cn":"马什小姐，您刚拍完新电影吗？","source":"supplement"},{"en":"She said she was going to retire.","cn":"她说她准备退休。","source":"supplement"},{"en":"I wonder why!","cn":"我很想知道为什么！","source":"supplement"}],"watch":"直接引语变转述：I'm tired → She said she was tired.（am 后退成 was）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"She said she ___ going to retire.","opts":["was","is","were","has"],"a":"was","why":"转述后退一步：is going to → was going to。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I ___ why!","opts":["wonder","wander","wondering","wonders"],"a":"wonder","why":"wonder 想知道（注意别拼成 wander 游荡）。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"马什小姐对拍电影怎么说？","opts":["不再拍了，准备退休","要拍十部","最爱拍电影","从没拍过"],"a":"不再拍了，准备退休","hint":"I'm going to retire.","why":"她觉得很疲惫。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"她当时穿着什么？","opts":["貂皮大衣","蓝裙子","滑稽的帽子","制服"],"a":"貂皮大衣","hint":"She was wearing a mink coat.","why":"记者在机场拍到的。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":273,"printedPage":269,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":134,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":133},{"id":135,"title":"The latest report","titleCn":"最新消息","kind":"text","words":[{"en":"latest","ipa":"/ˈleɪtɪst/","cn":"adj. 最新的","source":"supplement"},{"en":"future","ipa":"/ˈfjuːtʃə/","cn":"n. 未来（future husband 未婚夫）","source":"supplement"},{"en":"get married","ipa":"/ɡet ˈmærid/","cn":"phr. 结婚","source":"supplement"},{"en":"introduce","ipa":"/ˌɪntrəˈdjuːs/","cn":"v. 介绍","source":"supplement"},{"en":"report","ipa":"/rɪˈpɔːt/","cn":"n. 报道","source":"supplement"},{"en":"would","ipa":"/wʊd/","cn":"aux. 会（will 的过去式）","source":"supplement"}],"patterns":[{"en":"Are you really going to retire?","cn":"您真的打算退休吗？","source":"adaptation"},{"en":"She said she would have to ask her future husband.","cn":"她说她得问问自己的未婚夫。","source":"adaptation"},{"en":"The latest report!","cn":"最新消息！","source":"adaptation"}],"grammar":"转述将来：will → would；said (that) she would...；get married 结婚（get 表状态的变化）。","tip":"would 是 will 的过去式，转述时态要后退；“最新的”说 the latest，不说 the newest。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Are you really going to retire, Miss Marsh?","cn":"马什小姐，您真的准备退休吗？","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Well, I may. I can't make up my mind. I shall have to ask my future husband. He won't let me make another film.","cn":"嗯，有可能。我还拿不定主意。我得问一下我的未婚夫，他不会让我再拍影片的。","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Your future husband, Miss Marsh?","cn":"您的未婚夫，马什小姐？","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes. Let me introduce him to you.","cn":"是的，让我把他介绍给您。","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Listen to this! “Karen Marsh: The Latest Report. Miss Marsh told reporters this morning that she might retire. She said she couldn't make up her mind. She said she would have to ask her future husband. She said her future husband would not let her make another film.”","cn":"听听这一段！“卡伦·马什：最新消息。马什小姐今天上午告诉记者她可能要退休。她说她还拿不定主意。她说她得问问她的未婚夫。她说她的未婚夫不会再让她拍电影。”","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Good heavens! That reporter is her future husband!","cn":"天啊！那位记者就是她的未婚夫！","source":"adaptation","pdfPage":277,"printedPage":273,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"转述将来：will 变 would","chat":"转述「将来的打算」，will 要变成 would：She said she would ask her future husband.（她说她会问未婚夫）。get married = 结婚；最新的 = the latest。","formula":"said (that) + 主语 + would + 动词原形","examples":[{"en":"Are you really going to retire?","cn":"您真准备退休吗？","source":"supplement"},{"en":"I can't make up my mind.","cn":"我还拿不定主意。","source":"supplement"},{"en":"She said she would have to ask her future husband.","cn":"她说她得问问未婚夫。","source":"supplement"}],"watch":"would 是 will 的过去式：I will… → He said he would…——总是后退一步！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"She said she ___ have to ask her future husband.","opts":["would","will","shall","can"],"a":"would","why":"转述将来：will → would。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"I can't make ___ my mind.","opts":["up","on","out","of"],"a":"up","why":"make up one's mind 下决心。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"马什小姐的未婚夫是谁？","opts":["记者艾伦·琼斯","经理","她的牙医","乔治"],"a":"记者艾伦·琼斯","hint":"她把记者介绍给了大家——他就是未婚夫！","why":"课文的反转：记者「自曝」。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"报纸把这则新闻叫什么？","opts":["最新消息（The Latest Report）","车祸","天气新闻","零钱"],"a":"最新消息（The Latest Report）","hint":"The latest report!","why":"报纸头条。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":277,"printedPage":273,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":136,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":135},{"id":137,"title":"A pleasant dream","titleCn":"美好的梦","kind":"text","words":[{"en":"football","ipa":"/ˈfʊtbɔːl/","cn":"n. 足球","source":"supplement"},{"en":"pool","ipa":"/puːl/","cn":"n. 赌注（the football pools 足球博彩）","source":"supplement"},{"en":"win","ipa":"/wɪn/","cn":"v. 赢（won）","source":"supplement"},{"en":"world","ipa":"/wɜːld/","cn":"n. 世界","source":"supplement"},{"en":"depend","ipa":"/dɪˈpend/","cn":"v. 依靠（depend on 取决于）","source":"supplement"},{"en":"if","ipa":"/ɪf/","cn":"conj. 如果","source":"supplement"},{"en":"round","ipa":"/raʊnd/","cn":"adv. 周围（travel round the world 环游世界）","source":"supplement"}],"patterns":[{"en":"What will you do if you win a lot of money?","cn":"如果你赢了许多钱，你打算做什么呢？","source":"adaptation"},{"en":"If we win the football pools, we'll travel round the world.","cn":"如果我们赢得足球博彩，我们就去周游世界。","source":"adaptation"},{"en":"It's only a pleasant dream.","drill":true,"cn":"这只是一个美好的梦。","source":"supplement"}],"grammar":"真实条件句：If + 一般现在时，主句用 will + 动词原形；if 从句可以放在句首或句尾。","tip":"条件句口诀“主将从现”：主句用将来时，if 从句用现在时——不能说 If we'll win...","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"Do you do the football pools, Harry?","cn":"哈里，你买足球赛赌注吗？","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Yes, I do. Every week, but I never win anything.","cn":"是的，我每星期都买，可是从来没赢过。","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"What will you do if you win a lot of money?","cn":"要是你赢了许多钱，你打算做什么呢？","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"If I win a lot of money I'll buy you a mink coat.","cn":"要是我赢了许多钱，我就给你买件貂皮大衣。","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"I don't want a mink coat. I want to see the world.","cn":"我不要貂皮大衣，我要去看看世界。","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"All right. If we win a lot of money, we'll travel round the world and we'll stay at the best hotels. Then we'll return home and buy a big house in the country. We'll have a beautiful garden and…","cn":"好吧。要是我们赢了很多钱，我们就去周游世界，并且住最好的旅馆。然后我们回家，在乡下买幢大房子。我们将有一个漂亮的花园，还有……","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"But if we spend all that money we'll be poor again. What will we do then?","cn":"但是如果我们把所有的钱都花光了，我们又会变穷的。那时我们怎么办呢？","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"If we spend all the money we'll try and win the football pools again!","cn":"如果我们把所有的钱都花光了，我们就再去试一试赢得足球赛赌注！","source":"adaptation","pdfPage":281,"printedPage":277,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"if 条件句：主将从现","chat":"真实的假设用 if 条件句，口诀「主将从现」：if 从句用一般现在时，主句用 will：If we win, we'll travel round the world.（如果赢了，我们就环游世界。）","formula":"If + 一般现在时, 主语 + will + 动词原形","examples":[{"en":"What will you do if you win a lot of money?","cn":"如果你赢了很多钱，你会做什么？","source":"supplement"},{"en":"If we win the pools, we'll travel round the world.","cn":"如果我们赢了，我们就环游世界。","source":"supplement"},{"en":"If we spend all the money we'll be poor again.","cn":"把钱花光我们又会变穷的。","source":"supplement"}],"watch":"if 后面绝对不能用 will：If we'll win ❌ → If we win ✓——这就是「主将从现」！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"If we ___ the pools, we'll travel round the world.","opts":["win","will win","won","winning"],"a":"win","why":"主将从现：if 从句用现在时。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"What will you do if you ___ a lot of money?","opts":["win","wins","will win","won"],"a":"win","why":"从句主语 you 用一般现在时 win。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"如果赢了，妻子想做什么？","opts":["去看看世界","买件貂皮大衣","买大房子","呆在家"],"a":"去看看世界","hint":"I don't want a mink coat. I want to see the world.","why":"丈母娘? 不——是妻子不要貂皮大衣。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"如果钱花光了怎么办？","opts":["再去赢足球赌注","去上班","卖房子","再旅行一次"],"a":"再去赢足球赌注","hint":"we'll try and win the football pools again!","why":"美梦继续！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":281,"printedPage":277,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":138,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":137},{"id":139,"title":"Is that you, John?","titleCn":"是你吗，约翰？","kind":"text","words":[{"en":"extra","ipa":"/ˈekstrə/","cn":"adj. 额外的","source":"supplement"},{"en":"overseas","ipa":"/ˌəʊvəˈsiːz/","cn":"adj. 海外的，国外的","source":"supplement"},{"en":"engineering","ipa":"/ˌendʒɪˈnɪərɪŋ/","cn":"n. 工程","source":"supplement"},{"en":"company","ipa":"/ˈkʌmpəni/","cn":"n. 公司","source":"supplement"},{"en":"line","ipa":"/laɪn/","cn":"n. 线路（电话线）","source":"supplement"},{"en":"speaking","ipa":"/ˈspiːkɪŋ/","cn":"int. 我就是（电话用语）","source":"supplement"}],"patterns":[{"en":"Is that you, John?","cn":"是你吗，约翰？（电话用语）","source":"textbook","pdfPage":285,"printedPage":281,"verification":"verified","translationSource":"supplement"},{"en":"Yes, speaking.","cn":"是我，请讲。","source":"textbook","pdfPage":285,"printedPage":281,"verification":"verified","translationSource":"supplement"},{"en":"Tell Mary we'll be late for dinner this evening.","cn":"告诉玛丽，今晚吃饭我们会晚到。","source":"textbook","pdfPage":285,"printedPage":281,"verification":"verified","translationSource":"supplement"}],"grammar":"本课电话开头用 Is that you, John? 确认对方身份，回答 Yes, speaking.；tell sb (that) + 从句表示转告。后来才发现接电话的是电话工程师，不是要找的那位同名朋友。","tip":"电话里介绍自己常说 This is John；但本课核实姓名时也确实说 Yes, I’m John Smith.，不能把 I am John 一概说成错误。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}],"teachingSource":"supplement","text":[{"en":"Is that you, John?","cn":"是你吗，约翰？","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, speaking.","cn":"是的，我就是。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Tell Mary we'll be late for dinner this evening.","cn":"告诉玛丽，今晚吃饭我们会晚到。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm afraid I don't understand.","cn":"恐怕我不明白。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Hasn't Mary told you?","cn":"玛丽没有告诉你吗？","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"She invited Charlotte and me to dinner this evening.","cn":"她邀请夏洛特和我今晚去吃饭。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I said I would be at your house at six o'clock, but the boss wants me to do some extra work.","cn":"我说过六点到你家，但老板要我加做一些工作。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'll have to stay at the office.","cn":"我只好留在办公室。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I don't know when I'll finish.","cn":"我不知道什么时候能做完。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Oh, and by the way, my wife wants to know if Mary needs any help.","cn":"哦，顺便说一下，我妻子想知道玛丽是否需要帮忙。","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I don't know what you're talking about.","cn":"我不知道你在说什么。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That is John Smith, isn't it?","cn":"你是约翰·史密斯，对吗？","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Yes, I'm John Smith.","cn":"是的，我是约翰·史密斯。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"You are John Smith, the engineer, aren't you?","cn":"你是工程师约翰·史密斯，对吗？","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"That's right.","cn":"没错。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"You work for the Overseas Engineering Company, don't you?","cn":"你在海外工程公司工作，对吗？","speaker":"GRAHAM TURNER","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"No, I don't.","cn":"不，我不在那里工作。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I'm John Smith the telephone engineer and I'm repairing your telephone line.","cn":"我是电话工程师约翰·史密斯，正在修理您的电话线路。","speaker":"JOHN SMITH","pdfPage":285,"printedPage":281,"source":"textbook","sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"电话用语：Is that…?","chat":"英语打电话问「你是……吗」用 Is that…?，回答 Yes, speaking.（我是，请讲）。转告某人一件事：tell + 人 + (that) + 内容。","formula":"Is that…(名字)? → Yes, speaking. ｜ tell + 人 + (that) + 句子","examples":[{"en":"Is that you, John?","cn":"是你吗，约翰？","source":"supplement"},{"en":"Yes, speaking.","cn":"是我，请讲。","source":"supplement"},{"en":"Tell Mary we'll be late for dinner this evening.","cn":"告诉玛丽，今晚吃饭我们会晚到。","source":"supplement"}],"watch":"电话开场介绍自己常用 This is…；本课核实姓名时也说 Yes, I’m John Smith.。格雷厄姆认错了同名的人，接电话的是正在修理线路的电话工程师。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},"ex":{"g":[{"q":"___ that you, John?","opts":["Is","Are","Am","Do"],"a":"Is","why":"电话用语 Is that…?","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""},{"q":"Tell Mary we'll be ___ for dinner.","opts":["late","later","latest","late to"],"a":"late","why":"be late for 迟到。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"},"hint":""}],"c":[{"q":"实际接电话的约翰·史密斯是什么身份？","opts":["正在修线路的电话工程师","海外工程公司的朋友","玛丽的厨师","格雷厄姆的老板"],"a":"正在修线路的电话工程师","hint":"I'm John Smith the telephone engineer and I'm repairing your telephone line.","why":"格雷厄姆认错了同名的人；实际接电话的是电话工程师，不是承诺转告玛丽的朋友。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}},{"q":"格雷厄姆说自己为什么会晚到晚饭？","opts":["老板要他加做工作","饭已经凉了","电话工程师请他吃饭","玛丽取消了邀请"],"a":"老板要他加做工作","hint":"the boss wants me to do some extra work","why":"他要留在办公室加做工作，不知道何时结束；但接电话的并不是他以为的那位朋友。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":285,"printedPage":281,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, complete English-body and speaker","note":"二轮按proposal完整recommended逐行回看原页扫描确证；cn为补充翻译，未核教材参考译文；不含下一页词表、练习册或教师书。"}}]}},{"id":140,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":139},{"id":141,"title":"Sally's first train ride","titleCn":"萨莉第一次乘火车旅行","kind":"text","words":[{"en":"excited","ipa":"/ɪkˈsaɪtɪd/","cn":"adj. 兴奋的","source":"supplement"},{"en":"decide","ipa":"/dɪˈsaɪd/","cn":"v. 决定","source":"supplement"},{"en":"middle-aged","ipa":"/ˈmɪdl eɪdʒd/","cn":"adj. 中年的","source":"supplement"},{"en":"opposite","ipa":"/ˈɒpəzɪt/","cn":"prep. 在……对面","source":"supplement"},{"en":"curiously","ipa":"/ˈkjʊəriəsli/","cn":"adv. 好奇地","source":"supplement"},{"en":"funny","ipa":"/ˈfʌni/","cn":"adj. 有趣的，好笑的","source":"supplement"},{"en":"powder","ipa":"/ˈpaʊdə/","cn":"n. 香粉，粉","source":"supplement"},{"en":"ugly","ipa":"/ˈʌɡli/","cn":"adj. 丑陋的","source":"supplement"},{"en":"amused","ipa":"/əˈmjuːzd/","cn":"adj. 感到有趣的","source":"supplement"},{"en":"embarrassed","ipa":"/ɪmˈbærəst/","cn":"adj. 尴尬的","source":"supplement"}],"patterns":[{"en":"Sally was invited to a children's party.","cn":"萨莉应邀参加一个儿童聚会。","source":"adaptation"},{"en":"She had never travelled on a train before.","cn":"她以前从未坐过火车。","source":"adaptation"},{"en":"She sat opposite the middle-aged lady.","cn":"她坐在一位中年妇女的对面。","source":"adaptation"}],"grammar":"被动语态 was invited（be + 过去分词）；过去完成时 had never done 表示“在过去某时之前从未……”。","tip":"-ing / -ed 分清主客体：exciting 令人兴奋（事物），excited 感到兴奋（人）；embarrassing 事尴尬，embarrassed 人尴尬。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}],"teachingSource":"supplement","text":[{"en":"When my four-year-old daughter, Sally, was invited to a children's party, I decided to take her by train. Sally was very excited because she had never travelled on a train before.","cn":"当我的4岁女儿萨莉被邀请去参加一个儿童聚会时，我决定带她乘火车去。萨莉非常激动，因为她从未乘过火车。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"She sat near the window and asked questions about everything she saw.","cn":"她靠着车窗坐着，对她看到的一切都要问些什么。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"Suddenly, a middle-aged lady came into our compartment and sat opposite Sally.","cn":"突然，一位中年妇女进了我们的车厢，坐在萨莉的对面。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“Hello, little girl,” she said. Sally did not answer, but looked at her curiously.","cn":"“你好，小姑娘，”她说。萨莉没回答，却好奇地看着她。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"The lady was dressed in a blue coat and a large, funny hat.","cn":"那位妇女穿着一件蓝色的大衣，戴着一顶大而滑稽的帽子。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"After the train had left the station, the lady opened her handbag and took out her powder compact. She then began to make up her face.","cn":"火车开出车站后，那位妇女打开了手提包，拿出了粉盒，然后开始打扮起来。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“Why are you doing that?” Sally asked.","cn":"“你为什么要那样做呢？”萨莉问。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“To make myself beautiful,” the lady answered. She put away her compact and smiled kindly.","cn":"“为了把自己打扮漂亮啊，”那位妇女答道。她放好了粉盒，慈祥地微笑着。","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"},{"en":"“But you are still ugly,” Sally said. Sally was amused, but I was very embarrassed!","cn":"“可你仍然很难看呀。”萨莉说。萨莉感到很有趣，而我却非常尴尬！","source":"adaptation","pdfPage":289,"printedPage":285,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"candidate","translationSource":"supplement"}],"teach":{"title":"被动语态与过去完成时","chat":"动作「落在」主语头上，用被动语态：was invited（被邀请）= be + 过去分词。过去完成时 had done 表示「过去的过去」：她上车之前从未坐过火车 → She had never travelled by train before.","formula":"was/were + 过去分词（被……）｜ had + 过去分词（过去以前就……）","examples":[{"en":"Sally was invited to a children's party.","cn":"萨莉被邀请参加儿童聚会。","source":"supplement"},{"en":"She had never travelled on a train before.","cn":"她之前从未坐过火车。","source":"supplement"},{"en":"She sat opposite Sally.","cn":"她坐在萨莉对面。","source":"supplement"}],"watch":"excited 人感到兴奋，exciting 事物令人兴奋：Sally was excited.（萨莉很兴奋）！","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},"ex":{"g":[{"q":"Sally ___ invited to a children's party.","opts":["was","is","has","been"],"a":"was","why":"被动语态 was invited。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""},{"q":"She had ___ travelled on a train before.","opts":["never","ever","already","just"],"a":"never","why":"had never done 过去完成时。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"},"hint":""}],"c":[{"q":"萨莉为什么很兴奋？","opts":["从未坐过火车","最爱聚会","喜欢那位女士","看到了大海"],"a":"从未坐过火车","hint":"she had never travelled on a train before","why":"第一次坐火车。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}},{"q":"最后谁感到很尴尬？","opts":["「我」（家长）","萨莉","那位女士","司机"],"a":"「我」（家长）","hint":"Sally was amused, but I was very embarrassed!","why":"女儿说了实话「你还是很难看」。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":289,"printedPage":285,"status":"candidate","verified":false,"scope":"page-offset-only","note":"按preflight页偏移生成，未逐课回看正文；不能视为全文审核通过。"}}]}},{"id":142,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":141},{"id":143,"title":"A walk through the woods","titleCn":"林中散步","kind":"text","words":[{"en":"surround","ipa":"/səˈraʊnd/","cn":"v. 包围（be surrounded by）","source":"supplement"},{"en":"wood","ipa":"/wʊd/","cn":"n. 树林（常用复数 woods）","source":"supplement"},{"en":"beauty spot","ipa":"/ˈbjuːti spɒt/","cn":"n. 风景点","source":"supplement"},{"en":"through","ipa":"/θruː/","cn":"prep. 穿过","source":"supplement"},{"en":"visitor","ipa":"/ˈvɪzɪtə/","cn":"n. 参观者，游客","source":"supplement"},{"en":"litter","ipa":"/ˈlɪtə/","cn":"n. 废弃物，垃圾","source":"supplement"},{"en":"throw","ipa":"/θrəʊ/","cn":"v. 扔，抛（threw）","source":"supplement"},{"en":"rubbish","ipa":"/ˈrʌbɪʃ/","cn":"n. 垃圾（不可数）","source":"supplement"},{"en":"tyre","ipa":"/ˈtaɪə/","cn":"n. 轮胎","source":"supplement"},{"en":"prosecute","ipa":"/ˈprɒsɪkjuːt/","cn":"v. 依法检控，起诉","source":"supplement"}],"patterns":[{"en":"I live in a very old town which is surrounded by beautiful woods.","cn":"我住在一个被美丽树林环绕的古老小镇上。","source":"textbook","pdfPage":293,"printedPage":289,"verification":"verified","translationSource":"supplement"},{"en":"Visitors have been asked to keep the woods clean and tidy.","cn":"游客们已被要求保持树林的整洁。","source":"textbook","pdfPage":293,"printedPage":289,"verification":"verified","translationSource":"supplement"},{"en":"Anyone who leaves litter in these woods will be prosecuted.","cn":"凡在这树林里丢弃垃圾的人将被依法处理。","source":"adaptation"}],"grammar":"被动语态小结：is surrounded by（一般现在时）/ have been asked（完成时）/ will be prosecuted（将来时）；which 引导定语从句。","tip":"be covered with 被……覆盖；litter 偏指随手丢弃的废弃物，rubbish 是垃圾总称——第144课收尾：全册核心语法一次看全。","source":"adaptation","sourceRefs":[{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}],"teachingSource":"supplement","text":[{"en":"I live in a very old town which is surrounded by beautiful woods. It is a famous beauty spot.","cn":"我住在一个由美丽的树林环绕的古老小镇上。这是一个著名的风景胜地。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"On Sundays, hundreds of people come from the city to see our town and to walk through the woods.","cn":"每逢星期天，有许许多多人从城里来观看我们的小镇，并在树林中散步。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Visitors have been asked to keep the woods clean and tidy.","cn":"游客已被告知要保持树林的整洁。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Litter baskets have been placed under the trees, but people still throw their rubbish everywhere.","cn":"树下都已放置了废物筐，但人们仍到处扔垃圾。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Last Wednesday, I went for a walk in the woods. What I saw made me very sad.","cn":"上星期三我到树林里去散步。我所看到的一切使我非常难过。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"I counted seven old cars and three old refrigerators. The litter baskets were empty and the ground was covered with pieces of paper, cigarette ends, old tyres, empty bottles and rusty tins.","cn":"我数了一下，有7辆旧汽车和3台旧冰箱。废物筐是空的，而满地都是纸片、烟头、旧轮胎、空瓶子和生锈的空罐头盒。","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"},{"en":"Among the rubbish, I found a sign which said, “Anyone who leaves litter in these woods will be prosecuted!”","cn":"在垃圾堆中，我发现了一块牌子，上面写着：“凡在此树林里丢弃垃圾者，将依法处置！”","source":"textbook","pdfPage":293,"printedPage":289,"sourceFile":"电子资料/新概念英语第一册学生用书.pdf","verification":"verified","translationSource":"supplement"}],"teach":{"title":"被动语态大集合（毕业课）","chat":"本课回顾几种被动表达：is surrounded（被环绕）、have been asked（已被要求）、will be prosecuted（将被依法检控）。which 也可以补充说明名词：a sign which said…（一块写着……的牌子）。","formula":"is/are + 过去分词 ｜ have/has been + 过去分词 ｜ will be + 过去分词","examples":[{"en":"The town is surrounded by beautiful woods.","cn":"小镇被美丽的树林环绕。","source":"supplement"},{"en":"Visitors have been asked to keep the woods clean.","cn":"游客已被要求保持树林整洁。","source":"supplement"},{"en":"Anyone who leaves litter will be prosecuted!","cn":"乱扔垃圾者将被依法处置！","source":"supplement"}],"watch":"surrounded by woods 表示“被树林环绕”；by 在这里引出周围的事物。先理解课文，再分句复习，不必一次背全所有形式。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},"ex":{"g":[{"q":"Anyone who leaves litter ___ prosecuted!","opts":["will be","will","is being","prosecutes"],"a":"will be","why":"将来被动：will be + 过去分词。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""},{"q":"The town is surrounded ___ beautiful woods.","opts":["by","with","of","from"],"a":"by","why":"be surrounded by 表示“被……环绕”；by 后面的 woods 是环绕小镇的树林，不一定是人。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"},"hint":""}],"c":[{"q":"作者在垃圾堆里发现了什么？","opts":["一块牌子","一只鹦鹉","一枚硬币","一本词典"],"a":"一块牌子","hint":"I found a sign which said…","why":"牌子上写着乱扔垃圾将被依法处置。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}},{"q":"游客被要求做什么？","opts":["保持树林整洁","砍伐树木","数一数旧车","到处扔垃圾"],"a":"保持树林整洁","hint":"keep the woods clean and tidy","why":"但很多人做不到，所以才有那块牌子。","source":"supplement","basedOn":{"source":"textbook","file":"电子资料/新概念英语第一册学生用书.pdf","pdfPage":293,"printedPage":289,"status":"verified","verified":true,"scope":"lesson-heading, printed-page, English-body, speaker, Chinese-meaning","note":"本轮逐行对照原页；不含下一页词表和偶数课练习。"}}]}},{"id":144,"title":"Exercises","titleCn":"配套练习","kind":"drill","refId":143}];